// ── sound on a phone ─────────────────────────────────────────────────────
// A mobile browser starts audio only from a touch that ENDS or a click, never from one that begins, and it stays locked
// until then. The fake context follows that rule: resume() works inside touchend, pointerup, click or keydown, and
// and NOT afterwards and not inside pointerdown or touchstart, which is how iOS behaves (Chrome also lets a later call
// through once the page has been touched). `__osc` counts the notes that reached it.
const SOUND_POLICY = () => {
  window.__osc = 0;
  let active = 0;
  ["touchend", "pointerup", "click", "keydown"].forEach(t => addEventListener(t, () => { active++; setTimeout(() => active--, 0); }, true));
  window.AudioContext = class {
    constructor() { this.state = "suspended"; this.currentTime = 0; this.destination = {}; this.l = []; }
    addEventListener(t, f) { this.l.push(f); }
    resume() { if (active) { this.state = "running"; this.l.forEach(f => f()); return Promise.resolve(); } return Promise.reject(new Error("blocked")); }
    createGain() { const f = { setValueAtTime() {}, linearRampToValueAtTime() {}, exponentialRampToValueAtTime() {} }; return { gain: f, connect(x) { return x; } }; }
    createOscillator() { window.__osc++; return { frequency: { setValueAtTime() {} }, connect(x) { return x; }, start() {}, stop() {} }; }
  };
};

// The phone layout of the full board: filters folded away, the sound hint out of the way, readable chips, short cards.
async function phoneBoardCompactSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "land";
  const mk = (n, over) => landCard(n + "~land-" + n, Object.assign({ supervised: true, created_at: "2026-09-19T12:00:00Z", worktree: "/home/clint/git/github/openziti/ziti-sdk-c-" + n,
    tags: ["gwt", "orchestrators", "ziti-sdk-c", "needs-review", "backlog-grooming"] }, over || {}));
  mock.landList = [mk("aa"), mk("bb"), mk("cc"), mk("dd")];
  mock.landPerms = [];
  const shots = process.env.PHONE_BOARD_SHOTS || "";
  try {
    const tag = "phoneBoardCompact: ";
    const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
    await ctx.addInitScript(SOUND_POLICY);
    await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    await p.waitForTimeout(600);
    const shot = async n => { if (shots) { fs.mkdirSync(shots, { recursive: true }); await p.screenshot({ path: path.join(shots, n + "-390.png") }); } };
    await shot("stack");
    // the filter rows are folded behind one button, collapsed, with nothing but the search box and the button above the first card
    const f = await p.evaluate(() => {
      const vis = e => !!e && getComputedStyle(e).display !== "none" && e.getBoundingClientRect().height > 0;
      const first = document.querySelector("#stack .stackrow, #stack .card").getBoundingClientRect();
      const btn = document.querySelector("#stack .filtersbtn");
      return { btn: vis(btn), expanded: btn && btn.getAttribute("aria-expanded"), btnH: btn ? Math.round(btn.getBoundingClientRect().height) : 0,
        rows: document.querySelector("#stack .fpanel").inert ? [] : ["stack-seg", "stack-sort", "stack-group"], q: vis(document.getElementById("stack-q")),
        firstTop: Math.round(first.top) };
    });
    if (!f.btn || f.expanded !== "false") fail(tag + "the filters button is missing or open: " + JSON.stringify(f));
    if (f.rows.length) fail(tag + "the pill rows are not folded: " + f.rows.join(","));
    if (!f.q || f.btnH < 40) fail(tag + "the search box is gone or the button is under 40px: " + JSON.stringify(f));
    if (f.firstTop > 200) fail(tag + "the first card starts at " + f.firstTop + "px, the filters still take the screen");
    // the sound hint covers no input and no tray handle, in every view
    const hint = async where => {
      // a switch of view is a click, which unlocks the sound and takes the hint down, so it is put back to measure it
      const r = await p.evaluate(() => {
        const h = document.getElementById("sound-hint");
        if (h) h.hidden = false;
        if (!h || h.hidden || !h.getClientRects().length) return { shown: false };
        const hb = h.getBoundingClientRect();
        const hit = [...document.querySelectorAll("input, textarea, select, button, a, .term-handle, #t-handle, [class*=handle]")].filter(e => {
          const b = e.getBoundingClientRect(), cs = getComputedStyle(e);
          return cs.display !== "none" && cs.visibility !== "hidden" && b.width > 0 && b.height > 0 && b.left < hb.right && b.right > hb.left && b.top < hb.bottom && b.bottom > hb.top
            && /^(INPUT|TEXTAREA|SELECT)$/.test(e.tagName) || (/handle/.test(e.className + e.id) && b.width > 0 && b.left < hb.right && b.right > hb.left && b.top < hb.bottom && b.bottom > hb.top);
        }).map(e => e.tagName + "#" + e.id);
        return { shown: true, hit, pe: getComputedStyle(h).pointerEvents, bottom: Math.round(innerHeight - hb.bottom) };
      });
      if (!r.shown) fail(tag + "the sound hint is not up in " + where);
      else if (r.hit.length) fail(tag + "the sound hint covers " + JSON.stringify(r) + " in " + where);
    };
    await hint("stack");
    // the pill is a real target: a tap on it enables sound and opens nothing, even over a card row
    const under = await p.evaluate(() => {
      const h = document.getElementById("sound-hint"), b = h.getBoundingClientRect();
      h.style.pointerEvents = "none";
      const e = document.elementFromPoint(b.left + b.width / 2, b.top + b.height / 2);
      h.style.pointerEvents = "";
      window.__under = 0;
      document.addEventListener("click", ev => { if (ev.target !== h) window.__under++; }, true);
      return { tag: e ? e.tagName + "." + e.className : "", inList: !!(e && e.closest("#stack-list")) };
    });
    if (!under.inList) fail(tag + "the pill is not over a card row in this setup: " + JSON.stringify(under));
    // a press that slides off the pill and lets go elsewhere takes the pill down, and opens nothing
    const pb = await p.locator("#sound-hint").boundingBox();
    await p.evaluate(() => { window.__row = 0; document.addEventListener("click", ev => { if (ev.target.closest && ev.target.closest("#stack-list .stackrow, #stack-list .card")) window.__row++; }, true); });
    await p.mouse.move(pb.x + pb.width / 2, pb.y + pb.height / 2);
    await p.mouse.down();
    await p.mouse.move(pb.x + pb.width / 2, pb.y - 120, { steps: 4 });
    await p.mouse.up();
    await p.waitForTimeout(250);
    const slid = await p.evaluate(() => ({ hidden: document.getElementById("sound-hint").hidden, press: document.getElementById("sound-hint").dataset.press || "", row: window.__row }));
    if (!slid.hidden || slid.press) fail(tag + "a press that slid off the pill kept it up: " + JSON.stringify(slid));
    if (slid.row) fail(tag + "a press that slid off the pill clicked the row under it: " + JSON.stringify(slid));
    await p.evaluate(() => { document.getElementById("sound-hint").hidden = false; window.__under = 0; });
    await p.tap("#sound-hint");
    await p.waitForTimeout(250);
    const after = await p.evaluate(() => ({ n: window.__under, hidden: document.getElementById("sound-hint").hidden, url: location.pathname + location.hash }));
    if (after.n) fail(tag + "a tap on the sound pill reached what is under it: " + JSON.stringify(after));
    if (!after.hidden) fail(tag + "a tap on the sound pill did not enable sound");
    await p.evaluate(() => alerting.play("waiting"));
    if ((await p.evaluate(() => window.__osc || 0)) < 1) fail(tag + "the sound did not play after tapping the pill");
    // tag chips read in every skin: 4.5:1 for the text over what is behind it
    const skins = await p.evaluate(async () => {
      const css = await (await fetch("/css/themes.css")).text();
      return [...new Set([...css.matchAll(/data-skin="([^"]+)"/g)].map(m => m[1]))];
    });
    const lum = c => { const a = [c[0], c[1], c[2]].map(v => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); }); return .2126 * a[0] + .7152 * a[1] + .0722 * a[2]; };
    const low = [];
    for (const sk of skins) {
      await p.evaluate(x => document.documentElement.setAttribute("data-skin", x), sk);
      await p.waitForTimeout(80);
      const box = await p.evaluate(() => { const e = document.querySelector("#stack .chip.tag"); e.scrollIntoView({ block: "center" }); const b = e.getBoundingClientRect(); return { x: b.left, y: b.top, w: b.width, h: b.height }; });
      const png = await p.screenshot({ clip: { x: box.x, y: box.y, width: box.w, height: box.h } });
      const got = await p.evaluate(async b64 => {
        const img = new Image(); img.src = "data:image/png;base64," + b64; await img.decode();
        const cv = document.createElement("canvas"); cv.width = img.width; cv.height = img.height;
        const cx = cv.getContext("2d"); cx.drawImage(img, 0, 0);
        const px = cx.getImageData(3, Math.floor(img.height / 2), 1, 1).data;
        const t = document.createElement("canvas").getContext("2d"); t.fillStyle = "#000"; t.fillStyle = getComputedStyle(document.querySelector("#stack .chip.tag")).color;
        t.fillRect(0, 0, 1, 1); const fg = t.getImageData(0, 0, 1, 1).data;
        return { bg: [px[0], px[1], px[2]], fg: [fg[0], fg[1], fg[2]] };
      }, png.toString("base64"));
      const l1 = lum(got.fg), l2 = lum(got.bg), ratio = (Math.max(l1, l2) + .05) / (Math.min(l1, l2) + .05);
      if (ratio < 4.5) low.push(sk + " " + ratio.toFixed(2));
    }
    await p.evaluate(() => document.documentElement.removeAttribute("data-skin"));
    if (low.length) fail(tag + "tag chip text under 4.5:1 in " + low.join(", "));
    // a card is short: two or three to a screen
    const ch = await p.evaluate(() => [...document.querySelectorAll("#stack .stackrow, #stack .card")].map(e => Math.round(e.getBoundingClientRect().height)));
    if (!ch.length || Math.max(...ch) >= 170) fail(tag + "cards are too tall: " + ch.join(","));
    console.log("phoneBoardCompact: first card " + ch[0] + "px, " + skins.length + " skins");
    for (const v of ["board", "terms"]) {
      await p.evaluate(x => { const t = document.querySelector('header nav .tab[data-view="' + x + '"]'); if (t) t.click(); }, v);
      await p.waitForTimeout(500);
      await shot(v);
      await hint(v);
    }
    // opening the button brings the rows back
    await p.evaluate(() => document.querySelector('header nav .tab[data-view="stack"]').click());
    await p.waitForTimeout(300);
    await p.tap("#stack .filtersbtn");
    await p.waitForTimeout(200);
    const open = await p.evaluate(() => !document.querySelector("#stack .fpanel").inert && ["stack-seg", "stack-sort", "stack-group"].every(id => document.getElementById(id).getBoundingClientRect().height > 0) && document.querySelector("#stack .filtersbtn").getAttribute("aria-expanded") === "true");
    if (!open) fail(tag + "the button did not open the rows");
    await p.tap('#stack-seg button:not([data-v=""]):not([data-v="subagents"])');
    await p.waitForTimeout(200);
    await shot("stack-open");
    await p.tap("#stack .filtersbtn");
    await p.waitForTimeout(200);
    if (await p.evaluate(() => document.documentElement.scrollWidth > innerWidth)) fail(tag + "the page scrolls sideways");
    if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { mock.tasksMode = was; }
  if (!bad) console.log("phoneBoardCompact ok");
}

// The desktop board's files tab, the hub file drop. Hidden on a board with no /_hub/files.
async function boardFilesSection(browser, base) {
  const was = mock.tasksMode, wasDocs = mock.boardDocs;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  try {
    for (const on of [false, true]) {
      mock.boardDocs = on;
      const tag = "boardFiles " + (on ? "with" : "without") + " a hub: ";
      const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
      await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
      const p = await ctx.newPage();
      const errors = [];
      p.on("pageerror", e => errors.push(String(e)));
      await p.goto(base, { waitUntil: "domcontentloaded" });
      await p.waitForSelector('header nav .tab[data-view="stack"]', { timeout: slow(15000) });
      await p.waitForTimeout(800);
      const shown = await p.evaluate(() => { const t = document.querySelector('.tab[data-view="files"]'); return !!t && !t.hidden; });
      if (shown !== on) fail(tag + "the files tab is " + (shown ? "shown" : "hidden"));
      if (on) {
        await p.evaluate(() => document.querySelector('.tab[data-view="files"]').click());
        await p.waitForSelector("#m-files .f-row:not(.f-h)", { timeout: slow(5000) });
        const rows = await p.evaluate(() => [...document.querySelectorAll("#m-files .f-row:not(.f-h)")].map(r => ({ soon: r.classList.contains("soon"), href: r.querySelector("a.f-dl").getAttribute("href"), text: r.textContent })));
        if (rows.length !== 2) fail(tag + "expected two rows, got " + rows.length);
        else {
          if (rows[0].href !== "/_hub/files/report.pdf/raw") fail(tag + "the download link is " + rows[0].href);
          if (rows[1].href !== "/_hub/files/old%20log.txt/raw") fail(tag + "the download link of a spaced name is " + rows[1].href);
          if (rows[0].soon || !rows[1].soon) fail(tag + "only the file going within a day is marked: " + JSON.stringify(rows.map(r => r.soon)));
          if (!/the numbers/.test(rows[0].text) || !/card-a@box/.test(rows[0].text)) fail(tag + "the note or the origin is not drawn: " + rows[0].text);
        }
        if (!/used/.test(await p.textContent("#m-files .d-usage"))) fail(tag + "no usage line");
        // delete asks in the page first, and keeping it asks nothing of the hub
        await p.click("#m-files .f-row:not(.f-h) .f-act button");
        await p.waitForSelector("#m-files .d-sure", { timeout: slow(3000) });
        await p.click("#m-files .d-sure button:last-child");
        if (mock.filesDeleted.length) fail(tag + "keep it still deleted something");
        await p.click("#m-files .f-row:not(.f-h) .f-act button");
        await p.click("#m-files .d-sure .d-warn");
        await p.waitForFunction(() => true, null, { timeout: slow(1000) });
        await p.waitForTimeout(400);
        if (mock.filesDeleted[0] !== "report.pdf") fail(tag + "delete asked for " + JSON.stringify(mock.filesDeleted));
        await p.click("#m-files .d-back");
        await p.waitForFunction(() => document.getElementById("m-files").hidden, null, { timeout: slow(3000) });
      }
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      await ctx.close();
    }
  } finally { mock.tasksMode = was; mock.boardDocs = wasDocs; mock.filesDeleted.length = 0; }
  if (!bad) console.log("boardFiles ok");
}

// The desktop board's documents tab and panel, shared with /m. Off on a board with no /_hub/docs.
async function boardDocsSection(browser, base) {
  const was = mock.tasksMode, wasDocs = mock.boardDocs;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  try {
    for (const on of [false, true]) {
      mock.boardDocs = on;
      const tag = "boardDocs " + (on ? "with" : "without") + " documents: ";
      const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
      await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
      const p = await ctx.newPage();
      const errors = [];
      p.on("pageerror", e => errors.push(String(e)));
      await p.goto(base, { waitUntil: "domcontentloaded" });
      await p.waitForSelector('header nav .tab[data-view="stack"]', { timeout: slow(15000) });
      await p.waitForTimeout(800);
      const shown = await p.evaluate(() => { const t = document.querySelector('.tab[data-view="docs"]'); return !!t && !t.hidden; });
      if (shown !== on) fail(tag + "the documents tab is " + (shown ? "shown" : "hidden"));
      if (on) {
        await p.evaluate(() => document.querySelector('.tab[data-view="docs"]').click());
        await p.waitForSelector("#m-docs .d-row", { timeout: slow(5000) });
        if (await p.evaluate(() => document.querySelector(".tab.on").dataset.view) === "docs") fail(tag + "the tab took over a board view instead of opening the panel");
        await p.click("#m-docs .d-main");
        await p.waitForSelector("#m-docs .d-content .md", { timeout: slow(5000) });
        if (!/hello/.test(await p.textContent("#m-docs .d-content"))) fail(tag + "the document is not drawn");
        if (await p.evaluate(() => location.pathname) !== "/") fail(tag + "the board's address changed");
        // back from a document is back to the list it was opened from, the panel stays open, and back again closes it
        await p.click("#m-docs .d-back");
        await p.waitForSelector("#m-docs .d-row", { timeout: slow(3000) });
        if (await p.evaluate(() => document.getElementById("m-docs").hidden)) fail(tag + "back from a document closed the panel instead of showing the list");
        await p.click("#m-docs .d-back");
        await p.waitForFunction(() => document.getElementById("m-docs").hidden, null, { timeout: slow(3000) });
        // a /d/ link anywhere on the board opens the panel and does not navigate
        let loads = 0;
        p.on("load", () => { loads++; });
        await p.evaluate(() => { const a = document.createElement("a"); a.href = "/d/board-doc"; a.id = "probe-link"; a.textContent = "a doc"; a.style.cssText = "position:fixed;top:60px;left:10px;z-index:99999"; document.body.appendChild(a); });
        await p.click("#probe-link");
        await p.waitForSelector("#m-docs .d-content .md", { timeout: slow(5000) });
        if (loads) fail(tag + "a /d/ link navigated the board away");
      }
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      await ctx.close();
    }
  } finally { mock.tasksMode = was; mock.boardDocs = wasDocs; }
  if (!bad) console.log("boardDocs ok");
}

// THE SWITCHER'S RANKING AND ITS ROWS. Typing a name finds the card, and once a card matches as a real substring the cards
// whose directory only holds the letters scattered in order are gone. A row says the card's title first and the short path
// second, so two cards of one repo can be told apart. SWITCHER_SHOTS and SWITCHER_TAG write the picture.
async function switcherRankSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  const card = (id, title, wt, branch, tags) => Object.assign({}, T1, { id, display_title: title, title, supervised: true,
    worktree: wt, repo: "ziti-console", display_repo: "ziti-console", branch, tags: tags || [] });
  const cards = [
    card("sw-a", "Config screens", "/w/github/openziti/ziti-console", "ui-for-config"),
    card("sw-b", "Router list", "/w/github/openziti/ziti-console", "router-list"),
    card("sw-c", "Fips transition", "/work/ui-fix/or-tools/cfg-on-fig", "e2e"),
  ];
  const shots = process.env.SWITCHER_SHOTS || "", tag = process.env.SWITCHER_TAG || "after";
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  try {
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.waitForSelector('header nav .tab[data-view="stack"]', { timeout: slow(15000) });
    await p.evaluate(() => openSwitcher());
    await p.waitForFunction(() => document.getElementById("switcher").open, null, { timeout: slow(5000) });
    await p.waitForTimeout(500);
    const rows = async q => p.evaluate(([cs, q]) => {
      swTasks = cs;
      swSetQuery(q);
      return [...document.querySelectorAll("#sw-list .swrow[data-id]")].map(r => ({ id: r.dataset.id,
        name: r.querySelector(".swname").textContent, dir: r.querySelector(".swdir").textContent }));
    }, [cards, q]);
    const sub = await rows("ui-for-config");
    if (sub.map(r => r.id).join() !== "sw-a") fail("switcherRank: ui-for-config should find only sw-a, got " + sub.map(r => r.id).join());
    if (sub[0] && sub[0].name !== "Config screens") fail("switcherRank: the row's main text is " + JSON.stringify(sub[0].name) + ", want the card's title");
    if (sub[0] && !/ziti-console/.test(sub[0].dir)) fail("switcherRank: the dim text is " + JSON.stringify(sub[0].dir) + ", want the short path");
    if (shots) { fs.mkdirSync(shots, { recursive: true }); await p.screenshot({ path: path.join(shots, "switcher-" + tag + ".png") }); }
    // With no real match, the scattered one is all there is and stays.
    const scatter = await rows("uixtlsfig");
    if (scatter.map(r => r.id).join() !== "sw-c") fail("switcherRank: a scattered query with no real match should keep sw-c, got " + scatter.map(r => r.id).join());
    // Two cards of one repo are told apart by their titles.
    const both = await rows("ziti-console");
    if (new Set(both.map(r => r.name)).size !== 2) fail("switcherRank: two cards of one repo read alike: " + JSON.stringify(both));
    if (errors.length) fail("switcherRank: page errors: " + errors.join(" | "));
  } finally { mock.tasksMode = was; await ctx.close(); }
  if (!bad) console.log("switcherRank ok");
}

// GOING TO A CARD OPENS EVERY FOLD IT SITS IN, except the terminals list's headings. Its heading path, its project group
// and its column on the board are all folded, then the switcher goes to it: the board's are open afterwards and the
// list's stay shut, carrying the bridge.
async function revealFoldsSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "untagged";
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  try {
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.evaluate(() => document.querySelector('.tab[data-view="terms"]').click());
    const row = '#term-list .card.tab[data-id="u-disc"]';
    await p.waitForSelector(row, { state: "visible", timeout: slow(15000) });
    // Fold everything that holds the card, the way a person would, through the stores the folds write.
    const folded = await p.evaluate(() => {
      const t = lastTasks.find(x => x.id === "u-disc");
      const segs = termPathOf(t).segs;
      const termKeys = segs.map((_, i) => segs.slice(0, i + 1).join("/"));
      const col = COLUMNS.find(c => c.statuses.includes(t.status));
      const keys = [col.id].concat(col.statuses.length > 1 ? ["group:" + t.status] : []);
      localStorage.setItem("atrium.termfolded", JSON.stringify(termKeys));
      localStorage.setItem("atrium.folded", JSON.stringify(keys));
      repaintLists();
      return { termKeys, keys };
    });
    if (!folded.termKeys.length) fail("revealFolds: the card sits under no heading, so nothing is tested");
    await p.waitForFunction(r => !document.querySelector(r), row, { timeout: slow(5000) })
      .catch(() => fail("revealFolds: folding the headings did not hide the row"));
    const shots = process.env.REVEAL_SHOTS || "";
    if (shots) { fs.mkdirSync(shots, { recursive: true }); await p.screenshot({ path: path.join(shots, "reveal-folded.png") }); }
    await p.evaluate(() => openSwitcher());
    await p.waitForFunction(() => document.getElementById("switcher").open, null, { timeout: slow(5000) });
    await p.fill("#sw-q", "discourse-6101");
    await p.waitForSelector('#sw-list .swrow[data-id="u-disc"]', { timeout: slow(5000) });
    await p.press("#sw-q", "Enter");
    // The terminals list's headings are left as the operator set them: the heading carries the bridge instead.
    await p.waitForSelector("#term-list .tgroup.carries", { state: "attached", timeout: slow(5000) })
      .catch(() => fail("revealFolds: going to the card did not leave its shut group carrying the bridge"));
    if (await p.$(row)) fail("revealFolds: going to the card opened a heading in the terminals list");
    const after = await p.evaluate(() => ({
      termfolded: JSON.parse(localStorage.getItem("atrium.termfolded") || "[]"), folded: JSON.parse(localStorage.getItem("atrium.folded") || "[]") }));
    if (shots) await p.screenshot({ path: path.join(shots, "reveal-" + (process.env.REVEAL_TAG || "after") + ".png") });
    for (const k of folded.termKeys) if (!after.termfolded.includes(k)) fail("revealFolds: the heading " + k + " was opened");
    for (const k of folded.keys) if (after.folded.includes(k)) fail("revealFolds: " + k + " is still recorded as folded");
    // The board's column is open too, so the card is there.
    await p.evaluate(() => document.querySelector('.tab[data-view="board"]').click());
    await p.waitForSelector('#board [data-id="u-disc"]', { state: "visible", timeout: slow(5000) })
      .catch(() => fail("revealFolds: the card is not visible on the board"));
    if (errors.length) fail("revealFolds: page errors: " + errors.join(" | "));
  } finally { mock.tasksMode = was; await ctx.close(); }
  if (!bad) console.log("revealFolds ok");
}

// GOING TO A CARD TURNS ON THE CHIP THAT HIDES IT, in the view on screen and no other chip. The board's column chip for
// the card is off (and one more column is off for company), the stack's column chip is off: `revealCard` turns on the
// card's own and leaves the other alone.
async function revealChipSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "untagged";
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  try {
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.waitForFunction(() => typeof revealCard === "function" && lastTasks.some(x => x.id === "u-disc"), null, { timeout: slow(15000) });
    const setup = await p.evaluate(() => {
      const t = lastTasks.find(x => x.id === "u-disc");
      const mine = boardColumnOf(t);
      const other = BOARD_COLUMNS.map(c => c.id).filter(id => id !== mine)[0];
      const keep = BOARD_COLUMNS.map(c => c.id).filter(id => id !== mine && id !== other);
      localStorage.setItem("atrium.board.show", JSON.stringify(keep));
      const col = COLUMNS.find(c => c.statuses.includes(t.status));
      const stackOther = COLUMNS.map(c => c.id).find(id => id !== col.id);
      localStorage.setItem("atrium.stack.show", JSON.stringify([stackOther]));
      return { mine, other, stackOther, stackMine: col.id };
    });
    await p.evaluate(() => document.querySelector('.tab[data-view="board"]').click());
    await p.waitForFunction(() => !document.querySelector('#board [data-id="u-disc"]'), null, { timeout: slow(5000) })
      .catch(() => fail("revealChip: the board still draws the card with its column chip off"));
    await p.evaluate(() => revealCard("u-disc"));
    await p.waitForSelector('#board [data-id="u-disc"]', { state: "visible", timeout: slow(5000) })
      .catch(() => fail("revealChip: going to the card did not bring it back on the board"));
    const b = await p.evaluate(() => ({ on: [...boardShow()], stack: JSON.parse(localStorage.getItem("atrium.stack.show") || "[]") }));
    if (!b.on.includes(setup.mine)) fail("revealChip: the card's column chip is still off");
    if (b.on.includes(setup.other)) fail("revealChip: an unrelated column chip was turned on: " + JSON.stringify(b));
    if (b.stack.join() !== setup.stackOther) fail("revealChip: the stack's chips changed while on the board: " + JSON.stringify(b));
    await p.evaluate(() => document.querySelector('.tab[data-view="stack"]').click());
    await p.waitForFunction(() => !document.querySelector('#stack-list [data-id="u-disc"]'), null, { timeout: slow(5000) })
      .catch(() => fail("revealChip: the stack still draws the card with its column chip off"));
    await p.evaluate(() => revealCard("u-disc"));
    await p.waitForSelector('#stack-list [data-id="u-disc"]', { state: "visible", timeout: slow(5000) })
      .catch(() => fail("revealChip: going to the card did not bring it back on the stack"));
    const s = await p.evaluate(() => [...stackShow()]);
    if (!s.includes(setup.stackMine) || !s.includes(setup.stackOther)) fail("revealChip: the stack chips are wrong: " + JSON.stringify(s));
    if (errors.length) fail("revealChip: page errors: " + errors.join(" | "));
  } finally { mock.tasksMode = was; await ctx.close(); }
  if (!bad) console.log("revealChip ok");
}

// THE BRIDGE RUNS FROM A SHUT GROUP. The attached card sits in a group the operator left shut: the group stays shut, the
// bridge is level with its heading and the heading wears the attached frame. Opening the group moves the bridge to the
// card's row and shutting it again moves it back to the heading.
async function groupBridgeSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "untagged";
  // The card has to wear its repo's colour: a plain card keeps a hairline frame while its group's heading wears the
  // attached frame, and that is not what this unit measures. An earlier unit can leave the colours emptied, and the
  // serial run keeps what each one leaves.
  const colorsWas = mock.cardColorsMock;
  mock.cardColorsMock = { default: "", repos: Object.assign({}, colorsWas.repos, { "github/openziti/ziti": "teal-dusk" }) };
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  try {
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.evaluate(() => document.querySelector('.tab[data-view="terms"]').click());
    const row = '#term-list .card.tab[data-id="u-disc"]';
    await p.waitForSelector(row, { state: "visible", timeout: slow(15000) });
    const settle = () => p.evaluate(() => new Promise(r => {
      const box = () => [...document.querySelectorAll("#term-list .tgroup.carries, #term-list .card.on, #term-layout")]
        .map(e => { const x = e.getBoundingClientRect(); return [x.top, x.bottom, x.left, x.right].join(); }).join("|");
      let last = null, same = 0;
      const tick = () => {
        const now = box();
        same = now === last && !document.getAnimations().length ? same + 1 : 0;
        last = now;
        if (same >= 2) { placeTabBridge(); r(); } else requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    }));
    const read = () => p.evaluate(() => {
      placeTabBridge();
      const bridges = [...document.querySelectorAll("#term-layout .tabbridge")].filter(b => !b.hidden)
        .map(b => b.getBoundingClientRect());
      const mid = r => (r.top + r.bottom) / 2;
      const head = document.querySelector("#term-list .tgroup.carries");
      const card = document.querySelector("#term-list .card.on");
      const at = el => { if (!el) return null; const r = el.getBoundingClientRect(); return { top: r.top, bottom: r.bottom }; };
      return { bridges: bridges.map(r => ({ top: r.top, bottom: r.bottom, mid: mid(r) })), head: at(head), card: at(card),
        folded: JSON.parse(localStorage.getItem("atrium.termfolded") || "[]"), shotHead: head && head.textContent.trim() };
    });
    const shots = process.env.GROUP_BRIDGE_SHOTS || "";
    const shot = async name => { if (shots) { fs.mkdirSync(shots, { recursive: true }); await p.screenshot({ path: path.join(shots, name + ".png") }); } };
    const level = (g, el, what) => {
      const flare = el === "head" ? 8 : 0;   // a shut group's bridge flares toward the pane
      if (!g[el]) return fail("groupBridge: " + what + " is not drawn");
      if (g.bridges.length !== 1) return fail("groupBridge: want one bridge " + what + ", got " + g.bridges.length);
      if (g.bridges[0].top < g[el].top - 2 - flare || g.bridges[0].bottom > g[el].bottom + 2 + flare) {
        fail("groupBridge: the bridge " + JSON.stringify(g.bridges[0]) + " is not level with " + what + " " + JSON.stringify(g[el]));
      }
    };
    const top = await p.evaluate(() => {
      const t = lastTasks.find(x => x.id === "u-disc");
      termTask = t; term = term || { options: {}, dispose() {} };
      return termPathOf(t).segs[0];
    });
    if (!top) fail("groupBridge: the card sits under no heading, so nothing is tested");
    await p.evaluate(() => repaintTermList());
    await settle();
    await p.waitForSelector("#term-list .card.on", { state: "attached", timeout: slow(5000) });
    level(await read(), "card", "the row");
    // The boot's restore switches to the remembered view a moment after the first poll. The rows are `.card.tab`, so
    // a switch that marks the nav's tabs must leave them alone: the repaint after it is skipped for unchanged markup.
    const kept = await p.evaluate(() => { switchView("terms"); return document.querySelectorAll("#term-list .card.on").length; });
    if (kept !== 1) fail("groupBridge: switching to the terminals view took the attached row's mark off (" + kept + " rows on)");
    const cardFrame = await p.evaluate(() => getComputedStyle(document.querySelector("#term-list .card.on")).borderTopColor);
    await shot("group-bridge-before");
    // Shut the outermost group: the bridge moves to its heading and the group stays as it is left.
    await p.evaluate(t => toggleTermGroup(t), top);
    await p.waitForSelector("#term-list .tgroup.carries", { state: "attached", timeout: slow(5000) })
      .catch(() => fail("groupBridge: the shut group does not carry the bridge"));
    await settle();
    let g = await read();
    if (await p.$(row)) fail("groupBridge: the row is drawn inside a shut group");
    if (!g.folded.includes(top)) fail("groupBridge: the group was opened");
    level(g, "head", "the shut group's heading");
    // The heading wears the attached card's frame, and the bridge is a funnel: taller at the pane than at the heading.
    await p.evaluate(() => document.fonts.ready);
    await settle();
    const fun = await p.evaluate(() => {
      const h = document.querySelector("#term-list .tgroup.carries"), hr = h.getBoundingClientRect();
      const b = [...document.querySelectorAll("#term-layout .tabbridge")].find(x => !x.hidden), br = b.getBoundingClientRect();
      const path = b.querySelector("svg path");
      const ys = path ? path.getAttribute("d").match(/[ML]([\d.]+),([\d.]+)/g).map(m => parseFloat(m.split(",")[1])) : [];
      return { frame: getComputedStyle(h).borderTopColor, bridge: br.height, head: hr.height, funnel: b.classList.contains("funnel"), ys };
    });
    if (fun.frame !== cardFrame) fail("groupBridge: the heading frame " + fun.frame + " is not the attached card's " + cardFrame);
    if (!fun.funnel || fun.bridge <= fun.head + 2) fail("groupBridge: the bridge is not a funnel " + JSON.stringify(fun));
    await shot("group-bridge-after");
    // Attaching again, which is what going to the card does, leaves it shut.
    await p.evaluate(() => revealCard("u-disc"));
    await settle();
    g = await read();
    if (!g.folded.includes(top)) fail("groupBridge: going to the card opened the group");
    level(g, "head", "the shut group's heading");
    // Open it: back at the row.
    await p.evaluate(t => toggleTermGroup(t), top);
    await p.waitForSelector(row, { state: "visible", timeout: slow(5000) });
    await settle();
    g = await read();
    if (g.head) fail("groupBridge: an open group still carries the bridge");
    level(g, "card", "the row");
    // And shut again: the heading.
    await p.evaluate(t => toggleTermGroup(t), top);
    await settle();
    level(await read(), "head", "the heading, shut again");
    if (errors.length) fail("groupBridge: page errors: " + errors.join(" | "));
  } finally { mock.tasksMode = was; mock.cardColorsMock = colorsWas; await ctx.close(); }
  if (!bad) console.log("groupBridge ok");
}

// THE BRIDGE RUNS FROM A COLLAPSED PARENT. The attached card is a hidden child of a folded row, one level down and two:
// the folded row carries a funnel in the attached card's frame and nothing is opened. Expanded, the child's own row
// carries the ordinary bridge. COLLAPSED_BRIDGE_SHOTS and COLLAPSED_BRIDGE_TAG write the pictures.
async function collapsedBridgeSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  try {
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base + "/", { waitUntil: "domcontentloaded" });
    await p.waitForFunction(() => typeof setTermSortMode === "function" && typeof renderTermList === "function",
      null, { timeout: slow(15000) });
    await p.evaluate(() => {
      const card = (id, at, extra) => ({ id, status: "running", supervised: true, pinned: false, title: id,
        display_title: id, tags: [], created_at: at, worktree: "/r/p", ...extra });
      const sub = (id, at, by) => card(id, at, { tags: ["atrium:subagent"], spawned_by_id: by });
      const cards = [card("par", "2026-09-01T10:00:00Z"), sub("mid", "2026-09-02T10:00:00Z", "par"),
        sub("leaf", "2026-09-03T10:00:00Z", "mid"), card("lone", "2026-09-27T10:00:00Z")];
      boardCards = async () => cards;
      if (!termSubsOn()) toggleTermShow("subagents");
      switchView("terms");
    });
    const settle = () => p.evaluate(async () => { await renderTermList(); await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(() => {
      placeTabBridge(); r();
    }))); });
    const read = () => p.evaluate(() => {
      const at = el => { if (!el) return null; const r = el.getBoundingClientRect(); return { top: r.top, bottom: r.bottom }; };
      const bridges = [...document.querySelectorAll("#term-layout .tabbridge")].filter(b => !b.hidden);
      const b = bridges[0];
      return { n: bridges.length, funnel: !!b && b.classList.contains("funnel"), bridge: b && at(b),
        carries: [...document.querySelectorAll("#term-list .card.carries")].map(c => c.dataset.id),
        on: [...document.querySelectorAll("#term-list .card.on")].map(c => c.dataset.id),
        carrier: at(document.querySelector("#term-list .card.carries")), onRow: at(document.querySelector("#term-list .card.on")),
        shut: ["par", "mid"].filter(id => termKidsShut({ id })), frame: (() => {
          const c = document.querySelector("#term-list .card.carries"); return c ? getComputedStyle(c).borderTopColor : "";
        })() };
    });
    const shots = process.env.COLLAPSED_BRIDGE_SHOTS || "";
    const shot = async name => { if (shots) { fs.mkdirSync(shots, { recursive: true }); await p.screenshot({ path: path.join(shots, name + ".png") }); } };
    const tag = process.env.COLLAPSED_BRIDGE_TAG || "after";
    const attach = id => p.evaluate(id => { termTask = lastTasks.find(x => x.id === id) || termTask; }, id);
    const setShut = (id, shut) => p.evaluate(([id, shut]) => {
      const key = termKidsKey({ id }), list = foldedColumns().filter(k => k !== key);
      // On the chip's side of the default, an entry means folded.
      if (shut === termSubsOn()) list.push(key);
      localStorage.setItem("atrium.folded", JSON.stringify(list));
      repaintLists();
    }, [id, shut]);
    const level = (g, what) => {
      if (g.n !== 1) return fail("collapsedBridge: want one bridge " + what + ", got " + g.n);
      if (!g.carrier) return fail("collapsedBridge: " + what + ": no row carries it");
      if (g.bridge.top < g.carrier.top - 10 || g.bridge.bottom > g.carrier.bottom + 10) {
        fail("collapsedBridge: " + what + ": the bridge " + JSON.stringify(g.bridge) + " is not level with " + JSON.stringify(g.carrier));
      }
    };
    await p.evaluate(() => { term = term || { options: {}, dispose() {} }; });
    // The leaf is attached, two levels under "par". Expanded, its own row carries the ordinary bridge.
    await p.evaluate(async () => { termTask = (await boardCards()).find(c => c.id === "leaf"); });
    await setShut("par", false); await setShut("mid", false);
    await settle();
    let g = await read();
    if (g.on.join() !== "leaf" || g.carries.length || g.n !== 1 || g.funnel) fail("collapsedBridge: expanded: " + JSON.stringify(g));
    await shot("collapsed-bridge-expanded-" + tag);
    // One level folded: "mid" carries, "leaf" is not drawn.
    await setShut("mid", true);
    await settle();
    g = await read();
    if (g.carries.join() !== "mid" || g.on.length || !g.funnel) fail("collapsedBridge: mid folded: " + JSON.stringify(g));
    level(g, "mid folded");
    // Two deep: folding "par" too leaves the outermost visible row carrying it.
    await setShut("par", true);
    await settle();
    g = await read();
    if (g.carries.join() !== "par" || g.on.length || !g.funnel) fail("collapsedBridge: par folded: " + JSON.stringify(g));
    await p.waitForTimeout(500);   // the row eases its border in
    await shot("collapsed-bridge-" + tag);
    level(g, "par folded, two deep");
    const frame = await p.evaluate(() => getComputedStyle(document.querySelector("#term-list .card.carries")).borderTopColor);
    if (/transparent|rgba\(0, 0, 0, 0\)/.test(frame)) fail("collapsedBridge: the folded row wears no frame: " + frame);
    if (g.shut.join() !== "par,mid") fail("collapsedBridge: a fold was opened: " + JSON.stringify(g.shut));
    // Attached a card that is not under it: the folded row carries nothing.
    await p.evaluate(async () => { termTask = (await boardCards()).find(c => c.id === "lone"); });
    await settle();
    g = await read();
    if (g.carries.length || g.on.join() !== "lone") fail("collapsedBridge: an unrelated attach: " + JSON.stringify(g));
    if (errors.length) fail("collapsedBridge: page errors: " + errors.join(" | "));
  } finally { await ctx.close(); }
  if (!bad) console.log("collapsedBridge ok");
}

// THE DOCUMENTS PAGE, laid out: one centred column, a header row with the count, the card-or-every switch and a search,
// upload as the one primary control with its title inside it, deleted as a quiet toggle, roomy rows, a usage meter at the
// foot. Several documents are mocked at the route. DOCSPAGE_SHOTS and DOCSPAGE_TAG write the pictures.
async function docsPageSection(browser, base) {
  const was = mock.tasksMode, wasDocs = mock.boardDocs;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  mock.boardDocs = true;
  const at = "2026-10-09T08:00:00Z";
  const mk = (slug, title, kind, versions, by) => ({ slug, title, created: at, updated: at, versions, deleted: null,
    latest: { n: versions, kind, name: slug + ".md", size: 1200, at, by, origin: "card" } });
  const docs = [
    mk("a", "Interview: forge access, paste-open, private repos (2026-10-09)", "markdown", 1, "orchestrator-sg4-control@sg4-control"),
    mk("b", "Usage report for the week", "markdown", 4, "r-031@sg4"),
    mk("c", "Trace of the stuck terminal", "text", 2, "u-docs-peek-switcher@sg4"),
    mk("d", "Board screenshot", "image", 1, "r-typing-fixes@sg4"),
  ];
  const shots = process.env.DOCSPAGE_SHOTS || "", tag = process.env.DOCSPAGE_TAG || "after";
  try {
    for (const vp of [{ width: 1565, height: 536, name: "desktop" }, { width: 390, height: 844, name: "phone" }]) {
      const ctx = await browser.newContext({ viewport: { width: vp.width, height: vp.height } });
      await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
      await ctx.route(/\/_hub\/docs(\?.*)?$/, route => route.request().method() === "GET"
        ? route.fulfill({ json: { docs, usage: { bytes: 211000, cap: 2147483648 } } }) : route.fallback());
      const p = await ctx.newPage();
      const errors = [];
      p.on("pageerror", e => errors.push(String(e)));
      const t = "docsPage " + vp.name + ": ";
      await p.goto(base, { waitUntil: "domcontentloaded" });
      await p.waitForSelector('header nav .tab[data-view="stack"]', { timeout: slow(15000) });
      await p.waitForFunction(() => window.mDocs && window.mDocs.available(), null, { timeout: slow(8000) });
      await p.evaluate(() => window.mDocs.openList({ card: "land-live" }));
      await p.waitForSelector("#m-docs .d-row", { timeout: slow(5000) });
      await p.waitForTimeout(300);
      const m = await p.evaluate(() => {
        const r = s => { const e = document.querySelector(s); if (!e) return null; const b = e.getBoundingClientRect(); return { x: b.x, y: b.y, w: b.width, h: b.height, r: b.right }; };
        return { body: r("#m-docs .d-list-view"), head: r(".d-lhead"), seg: r(".d-seg"), q: r(".d-q"), up: r(".d-upload"), tin: r(".d-tin"),
          tinShown: !!document.querySelector(".d-tin") && getComputedStyle(document.querySelector(".d-tin")).display !== "none",
          del: r(".d-chip"), row: r(".d-row"), meter: r(".d-meter"), foot: r(".d-usage"), rows: document.querySelectorAll(".d-row").length,
          count: (document.querySelector(".d-count") || {}).textContent, bits: document.querySelectorAll(".d-row:first-child .d-bit").length,
          scrollW: document.querySelector(".d-scroll").scrollWidth, clientW: document.querySelector(".d-scroll").clientWidth, vw: innerWidth };
      });
      if (!m.body || !m.seg || !m.up || !m.meter) { fail(t + "the page is missing a part: " + JSON.stringify(m)); }
      else {
        const left = m.body.x, right = m.vw - m.body.r;
        if (Math.abs(left - right) > 14) fail(t + "the column is not centred, " + Math.round(left) + "px left and " + Math.round(right) + "px right");
        if (vp.name === "desktop" && m.body.w > 900) fail(t + "the column is " + Math.round(m.body.w) + "px wide, past 900");
        if (m.rows !== docs.length || m.count !== String(docs.length)) fail(t + "rows " + m.rows + " count " + m.count);
        if (m.bits < 4) fail(t + "a row does not carry kind, versions, age and author: " + m.bits);
        if (m.scrollW > m.clientW + 1) fail(t + "the page scrolls sideways: " + m.scrollW + " over " + m.clientW);
        if (m.meter.h > 6) fail(t + "the usage meter is not thin: " + m.meter.h + "px");
        if (m.row.h < 56) fail(t + "the rows are not roomy: " + m.row.h + "px");
      }
      if (shots) { fs.mkdirSync(shots, { recursive: true }); await p.screenshot({ path: path.join(shots, "docs-" + vp.name + "-" + tag + ".png") }); }
      if (errors.length) fail(t + "page errors: " + errors.join(" | "));
      await ctx.close();
    }
  } finally { mock.tasksMode = was; mock.boardDocs = wasDocs; }
  if (!bad) console.log("docsPage ok");
}

async function soundPhoneSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  try {
    const tag = "soundPhone: ";
    const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
    await ctx.addInitScript(SOUND_POLICY);
    await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base + "/raw", { waitUntil: "load" });
    await p.waitForFunction(() => typeof alerting !== "undefined", null, { timeout: slow(15000) });
    await p.waitForTimeout(500);
    const shown = sel => p.evaluate(s => { const e = document.querySelector(s); return !!e && !e.hidden && e.getClientRects().length > 0; }, sel);
    if (!(await shown("#sound-hint"))) fail(tag + "no tap-to-enable hint while sound is locked");
    // one touch is enough
    await p.tap("body", { position: { x: 195, y: 400 } });
    await p.waitForTimeout(200);
    if (await shown("#sound-hint")) fail(tag + "the hint is still up after a touch");
    await p.evaluate(() => alerting.play("waiting"));
    if ((await p.evaluate(() => window.__osc)) < 1) fail(tag + "the sound did not play after one touch");
    // a page the operator cannot see is not one they are reading, whatever hasFocus says
    const hidden = await p.evaluate(() => {
      const f = Object.getOwnPropertyDescriptor(Document.prototype, "visibilityState");
      Object.defineProperty(document, "visibilityState", { configurable: true, get: () => "hidden" });
      const was = document.hasFocus; document.hasFocus = () => true;
      const out = focusIsHere();
      delete document.visibilityState; document.hasFocus = was;
      return out;
    });
    if (hidden) fail(tag + "a hidden page counted as the window being looked at");
    if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { mock.tasksMode = was; }
  if (!bad) console.log("soundPhone ok");
}

// ── the bell on the phone board, in every view ───────────────────────────
async function phoneBellSection(browser, base) {
}

// ── a phone's board root lands on /m ─────────────────────────────────────
// A coarse pointer and a short side under 600px is a phone. A tablet, a desktop, a pop-out window and a phone that opted
// out are left alone, and the card paths map to their /m twins.
async function phoneRedirectSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  landCard("land-a", { alias: "rnd", room: "claude-sg4", wire_name: "sparta/rnd-director", supervised: true });
  const raw = fs.readFileSync(path.join(WEB_ROOT, "index.html"));
  try {
    for (const at of ["/raw", "/raw#term=land-a", "/alias/rnd"]) {
      const tag = "phoneBell " + at + ": ";
      const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
      await ctx.addInitScript(SOUND_POLICY);
      await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
      const p = await ctx.newPage();
      const errors = [];
      p.on("pageerror", e => errors.push(String(e)));
      await p.route("**/*", route => {
        const rq = route.request();
        const u = new URL(rq.url());
        if (u.pathname === "/alias/rnd" && rq.resourceType() === "document") return route.fulfill({ status: 200, contentType: "text/html", body: raw });
        if (u.pathname === "/v1/tasks/rnd") return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(mock.LAND["land-a"]) });
        return route.continue();
      });
      try {
        await p.goto(base + at, { waitUntil: "load" });
        await p.waitForTimeout(1200);
        await p.evaluate(() => recordToLog("a thing", "it happened", "", "", ""));
        const bell = await p.evaluate(() => [...document.querySelectorAll("#toastlog-open, #phone-bell")].find(e => e.getClientRects().length > 0 && !e.hidden) ? true : false);
        if (!bell) { fail(tag + "no bell is on screen"); continue; }
        const count = await p.evaluate(() => [...document.querySelectorAll("#toastlog-open .count, #phone-bell .pb-n")].map(e => e.textContent).join("|"));
        if (!/1/.test(count)) fail(tag + "the bell shows no unread count: " + count);
        await p.evaluate(() => openToastLog());
        await p.waitForSelector("#toastlog[open]", { timeout: slow(3000) });
        const t = () => p.evaluate(() => ({ label: document.getElementById("toastlog-sound").textContent, muted: JSON.parse(localStorage.getItem(/^#term=|^\/alias\//.test(location.hash) || location.pathname.startsWith("/alias/") ? "atrium.sound.card:land-a" : "atrium.sound") || "{}").muted === true }));
        const a = await t();
        await p.tap("#toastlog-sound");
        const b = await t();
        if (a.muted || !b.muted || b.label !== "sound off") fail(tag + "the mute toggle did not flip the sound state: " + JSON.stringify([a, b]));
        await p.tap("#toastlog-sound");
        if ((await t()).muted) fail(tag + "the mute toggle did not flip back");
      } finally { await ctx.close(); }
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    }
  } finally { mock.tasksMode = was; }
  if (!bad) console.log("phoneBell ok");
}

// ── the bell and the sound on /m ─────────────────────────────────────────
// ── The phone page picks up a new build ──────────────────────────────────
// `/v1/health` carries the build id. A change reloads /m once, not while a draft, a focused box or a selection is up (an
// "update ready" button shows instead, and the reload comes when it clears), and never twice for the same build.
async function mReloadSection(browser) {
  const st = mServer({});
  st.tasks = [mCard("r-1", { alias: "alpha", display_title: "alpha", status: "running", last_reply: "hello there, a line to select" })];
  await st.open();
  try {
    const ctx = await browser.newContext({ viewport: M_VIEWS[0], hasTouch: true, isMobile: true });
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    let loads = 0;
    p.on("load", () => loads++);
    await p.goto(st.url + "/m/", { waitUntil: "load" });
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    await p.evaluate(() => window.mBuild.check());
    const base = loads;
    const settle = ms => p.waitForTimeout(ms);
    const tag = "mReload: ";

    // same id: nothing
    await p.evaluate(() => window.mBuild.check());
    await settle(400);
    if (loads !== base) fail(tag + "the same build reloaded the page");

    // a draft holds it, with the cue up
    await p.evaluate(() => { const t = document.createElement("textarea"); t.id = "fake-draft"; t.value = "half a thought"; document.body.appendChild(t); });
    st.build = "build-2";
    await p.evaluate(() => window.mBuild.check());
    await settle(600);
    if (loads !== base) fail(tag + "a draft did not hold the reload");
    if (!(await p.evaluate(() => { const c = document.querySelector(".m-update"); return !!c && c.getClientRects().length > 0; }))) fail(tag + "no cue while it waits");
    // the hub answers with the id this page runs again: the wait and its cue are dropped, with no reload
    st.build = "build-1";
    await p.evaluate(() => window.mBuild.check());
    await settle(400);
    if (await p.evaluate(() => !!document.querySelector(".m-update"))) fail(tag + "the cue stayed after the id came back to the one this page runs");
    if (loads !== base) fail(tag + "reloaded though the id went back");
    st.build = "build-2";
    await p.evaluate(() => window.mBuild.check());
    await settle(400);
    if (!(await p.evaluate(() => !!document.querySelector(".m-update")))) fail(tag + "the cue did not come back for the new id");
    await p.evaluate(() => { document.getElementById("fake-draft").value = ""; });
    await p.waitForEvent("load", { timeout: slow(6000) }).catch(() => fail(tag + "the reload did not come once the draft cleared"));
    await settle(300);
    if (loads !== base + 1) fail(tag + "expected one reload, saw " + (loads - base));

    // the reloaded page learned the new id, so it does not reload again, and the guard stops a flapping hub
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    await p.evaluate(() => window.mBuild.check());
    await settle(500);
    if (loads !== base + 1) fail(tag + "reloaded again for a build it already has");
    st.build = "build-3";
    await p.evaluate(() => window.mBuild.check());
    await settle(500);
    const afterThree = loads;
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    st.build = "build-2";
    await p.evaluate(() => window.mBuild.check());
    await settle(500);
    st.build = "build-3";
    await p.evaluate(() => window.mBuild.check());
    await settle(800);
    if (loads > afterThree) fail(tag + "a flapping hub made " + (loads - afterThree) + " reloads in a row");

    // a live selection holds it too
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    await p.evaluate(() => { sessionStorage.removeItem("atrium.m.reloaded"); });
    const b4 = loads;
    await p.evaluate(() => {
      const d = document.createElement("p"); d.id = "fake-sel"; d.textContent = "select this text please"; document.body.appendChild(d);
      const r = document.createRange(); r.selectNodeContents(d); const s = getSelection(); s.removeAllRanges(); s.addRange(r);
    });
    st.build = "build-9";
    await p.evaluate(() => window.mBuild.check());
    await settle(600);
    if (loads !== b4) fail(tag + "a selection did not hold the reload");
    await p.evaluate(() => getSelection().removeAllRanges());
    await p.waitForEvent("load", { timeout: slow(6000) }).catch(() => fail(tag + "the reload did not come once the selection cleared"));
    // two restarts back to back while a draft holds: one reload, for the newest build, and the page then rests on it
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    await p.evaluate(() => { sessionStorage.removeItem("atrium.m.reloaded"); const t = document.createElement("textarea"); t.id = "fake-draft2"; t.value = "still typing"; document.body.appendChild(t); });
    const b5 = loads;
    st.build = "build-10";
    await p.evaluate(() => window.mBuild.check());
    st.build = "build-11";
    await p.evaluate(() => window.mBuild.check());
    await settle(600);
    if (loads !== b5) fail(tag + "back to back restarts reloaded under a draft");
    await p.evaluate(() => { document.getElementById("fake-draft2").value = ""; });
    await p.waitForEvent("load", { timeout: slow(6000) }).catch(() => fail(tag + "no reload after the draft cleared"));
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    await p.evaluate(() => window.mBuild.check());
    await settle(2500);
    if (loads !== b5 + 1) fail(tag + "back to back restarts made " + (loads - b5) + " reloads, not 1");

    // a review-comment chip with an empty box is something a reload loses and nothing saves: it holds the reload too
    await p.waitForFunction(() => window.mNet.loaded() && window.mBuild, null, { timeout: slow(10000) });
    await p.evaluate(() => { sessionStorage.removeItem("atrium.m.reloaded"); window.mCard.open("r-1"); });
    await p.waitForSelector("#m-compose .mc-box", { timeout: slow(8000) });
    const added = await p.evaluate(() => { const ok = window.mCompose.addComment({ path: "a/b.js", line: 3, kind: "+", text: "" }); document.activeElement && document.activeElement.blur && document.activeElement.blur(); return ok; });
    if (!added) fail(tag + "the comment chip was not added");
    if ((await p.$eval("#m-compose .mc-box", t => t.value)) !== "") fail(tag + "the box is not empty for the chip case");
    const b6 = loads;
    st.build = "build-20";
    await p.evaluate(() => window.mBuild.check());
    await settle(700);
    if (loads !== b6) fail(tag + "a comment chip did not hold the reload");
    if (!(await p.evaluate(() => !!document.querySelector(".m-update")))) fail(tag + "no cue while a chip holds it");
    await p.click("#m-compose .mc-cmt .mc-fx");
    await p.waitForEvent("load", { timeout: slow(6000) }).catch(() => fail(tag + "the reload did not come once the chip was removed"));
    if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { await st.close(); }
  if (!bad) console.log("mReload ok");
}

// ── The phone page after a hub restart ──────────────────────────────────
// The stream drops and the hub is down for a few connects, then answers, and its first read of the cards fails because
// the room is not up yet. The page must reconnect on its backoff, read again until it gets an answer (not wait 60s for the
// resync), and read the open card's thread, which no event announces.
async function mReconnectSection(browser) {
  const st = mServer({});
  st.tasks = [mCard("r-1", { alias: "alpha", display_title: "alpha", status: "running" })];
  st.replies["r-1"] = { source: "transcript", replies: [{ at: mIso(9 * M_MIN), text: "the first reply" }] };
  await st.open();
  const tag = "mReconnect: ";
  try {
    const ctx = await browser.newContext({ viewport: M_VIEWS[0], hasTouch: true, isMobile: true });
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
    await p.waitForFunction(() => window.mNet.loaded() && window.mNet.live(), null, { timeout: slow(10000) });
    await p.evaluate(() => window.mCard.open("r-1"));
    await p.waitForFunction(() => /the first reply/.test(document.getElementById("m-replies").textContent), null, { timeout: slow(8000) })
      .catch(() => fail(tag + "the card did not show its reply"));
    const hits0 = st.eventHits;
    // the hub goes down: the stream ends, two connects are refused, the first read after it fails, and meanwhile things moved
    st.eventsFail = 2;
    st.tasksFail = 1;
    st.tasks = [st.tasks[0], mCard("r-2", { alias: "beta", display_title: "beta", status: "running" })];
    st.perms = [{ id: "pm1", task_id: "r-1", tool: "Bash", command: "ls", requested_at: mIso(0) }];
    st.replies["r-1"] = { source: "transcript", replies: [{ at: mIso(9 * M_MIN), text: "the first reply" }, { at: mIso(M_MIN), text: "the second reply" }] };
    st.streams.forEach(r => r.end());
    await p.waitForFunction(() => !window.mNet.live(), null, { timeout: slow(4000) }).catch(() => fail(tag + "the page did not notice the stream drop"));
    await p.waitForFunction(() => window.mNet.live(), null, { timeout: slow(20000) }).catch(() => fail(tag + "the page never reconnected"));
    if (st.eventHits - hits0 < 3) fail(tag + "expected a backoff through the refused connects, saw " + (st.eventHits - hits0) + " connects");
    await p.waitForFunction(() => window.mStore.cards().length === 2 && window.mStore.perms().length === 1, null, { timeout: slow(12000) })
      .catch(async () => fail(tag + "the cards and permissions missed while down were not read: " + JSON.stringify(await p.evaluate(() => ({ c: window.mStore.cards().length, p: window.mStore.perms().length })))));
    await p.waitForFunction(() => /the second reply/.test(document.getElementById("m-replies").textContent), null, { timeout: slow(8000) })
      .catch(() => fail(tag + "the open card did not read the reply that landed while down"));
    if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { await st.close(); }
  if (!bad) console.log("mReconnect ok");
}

// ── The open card reads its thread when the row's activity moves ─────────
// A room that reports no `output_at` still moves `last_activity_at`. The read is throttled to one per 5s with the last
// change always read, and a row that did not change reads nothing.
async function mActivityReadSection(browser) {
  const st = mServer({});
  const T0 = mIso(10 * M_MIN), created = mIso(3600000);
  const row = over => mCard("a-1", Object.assign({ alias: "alpha", display_title: "alpha", status: "running", output_at: null, created_at: created, last_activity_at: T0 }, over || {}));
  st.tasks = [row()];
  st.replies["a-1"] = { source: "transcript", replies: [{ at: mIso(9 * M_MIN), text: "a reply" }] };
  await st.open();
  const tag = "mActivityRead: ";
  const reads = () => st.hits.filter(h => h.indexOf("a-1?") === 0).length;
  // The 5s throttle runs on the page's fake clock. `tick` moves it, and real time only carries the event and the read.
  let p;
  const tick = ms => p.clock.runFor(ms);
  const push = async r => {
    st.tasks = [r]; st.send("task", Object.assign({ row: 1 }, r));
    const want = JSON.stringify([r.last_activity_at, r.prompted_at, r.output_at]);
    await p.waitForFunction(w => { const c = window.mStore.cards()[0]; return c && JSON.stringify([c.last_activity_at, c.prompted_at, c.output_at]) === w; }, want, { timeout: slow(4000) }).catch(() => {});
  };
  const readsReach = async n => { const end = Date.now() + slow(3000); while (reads() < n && Date.now() < end) await new Promise(r => setTimeout(r, 20)); return reads(); };
  const readsSettle = async () => { await new Promise(r => setTimeout(r, slow(300))); return reads(); };
  try {
    const ctx = await browser.newContext({ viewport: M_VIEWS[0], hasTouch: true, isMobile: true });
    p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.clock.install();
    await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
    await p.waitForFunction(() => window.mNet.loaded() && window.mNet.live(), null, { timeout: slow(10000) });
    await p.evaluate(() => window.mCard.open("a-1"));
    await p.waitForFunction(() => /a reply/.test(document.getElementById("m-replies").textContent), null, { timeout: slow(8000) });
    await tick(300);
    const r0 = await readsSettle();
    // nothing changed, and the last read is more than 5s old so the throttle cannot be what holds it: no read
    await tick(5300);
    await push(row());
    await tick(1200);
    if (await readsSettle() !== r0) fail(tag + "an unchanged row made a read");
    // last_activity_at moved with output_at still null: one read, a moment later at most
    await push(row({ last_activity_at: mIso(5 * M_MIN) }));
    await tick(800);
    await readsReach(r0 + 1);
    if (await readsSettle() !== r0 + 1) fail(tag + "a moved last_activity_at made " + (reads() - r0) + " reads, not 1");
    // ten changes in about a second: held, then one trailing read
    for (let i = 0; i < 10; i++) { await push(row({ last_activity_at: mIso(4 * M_MIN - i * 1000) })); await tick(100); }
    if (await readsSettle() !== r0 + 1) fail(tag + "the throttle let a read through inside 5s: " + (reads() - r0));
    await tick(5500);
    await readsReach(r0 + 2);
    if (await readsSettle() !== r0 + 2) fail(tag + "ten changes made " + (reads() - r0 - 1) + " reads after the first, not 1");
    // prompted_at counts too
    const T = mIso(2 * M_MIN);
    await tick(5200);
    await push(row({ last_activity_at: T }));
    await tick(800);
    if (await readsReach(r0 + 3) !== r0 + 3) fail(tag + "a moved last_activity_at after a quiet spell did not read");
    await tick(5200);
    await push(row({ last_activity_at: T, prompted_at: mIso(M_MIN) }));
    await tick(800);
    if (await readsReach(r0 + 4) !== r0 + 4) fail(tag + "a moved prompted_at alone did not read");
    // a turn end on a row with no output_at moves the turn and the activity together: one read, not a second one 5s later
    await tick(5200);
    await push(row({ last_activity_at: mIso(M_MIN * 2), seen: { turn_ended_at: mIso(M_MIN * 2) } }));
    await tick(800);
    await readsReach(r0 + 5);
    await tick(5700);
    if (await readsSettle() !== r0 + 5) fail(tag + "a turn end made " + (reads() - r0 - 4) + " reads, not 1");
    // the same with output_at reported
    await tick(200);
    const OUT = mIso(M_MIN), PR = mIso(M_MIN);
    await push(row({ last_activity_at: mIso(M_MIN), prompted_at: PR, output_at: OUT }));
    await tick(800);
    await readsReach(r0 + 6);
    await tick(5700);
    if (await readsSettle() !== r0 + 6) fail(tag + "a turn end with output_at made " + (reads() - r0 - 5) + " reads, not 1");
    // a room that reports output_at: activity alone is not a reason to read
    await push(row({ last_activity_at: mIso(30000), prompted_at: PR, output_at: OUT }));
    await tick(6500);
    if (await readsSettle() !== r0 + 6) fail(tag + "activity alone read though the row reports output_at");
    if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { await st.close(); }
  if (!bad) console.log("mActivityRead ok");
}

// ── Failed reads back off on their own and stop on a refusal ────────────
// ── review 3c1e46d6: the phone's list read, the phone's reopen, the board's all-rooms approve ─────────────────
// Finding 3: a `task` row or a `task-removed` that lands while `/v1/tasks` is in flight is not undone by that read's
// older answer. Finding 4: a tap on a card while the sheet slides out opens it. And the review's open question: an
// approve on the desktop board in the all-rooms view names its room in the header on a hub, and on no hub keeps the
// `/v1/rooms/` path.
async function mReviewSection(browser, base) {
  const tag = "mReview: ";
  const st = mServer({});
  st.tasks = [mCard("a-1", { alias: "alpha", display_title: "alpha", status: "running" }), mCard("b-1", { alias: "beta", display_title: "beta" })];
  await st.open();
  try {
    const { ctx, p, errors } = await mPage(browser, st, M_VIEWS[0], "");
    await p.waitForFunction(() => window.mNet.loaded(), null, { timeout: slow(10000) });
    await p.waitForSelector("#m-seg-all", { timeout: slow(10000) });
    await p.tap("#m-seg-all");
    await p.waitForSelector("#m-list .row", { timeout: slow(10000) });
    // 3. The read starts on a bare `task` event, and is answered 900ms later with what the list was when it began.
    st.tasksSlow = 900;
    st.send("task", {});
    await p.waitForTimeout(450);
    st.send("task", Object.assign({}, st.tasks[0], { row: 1, status: "done" }));
    st.send("task-removed", { id: "b-1" });
    await p.waitForTimeout(1300);
    const got = await p.evaluate(() => ({ a: (window.mStore.card("a-1") || {}).status, b: !!window.mStore.card("b-1") }));
    if (got.a !== "done") fail(tag + "an older read put the card back to " + got.a);
    if (got.b) fail(tag + "an older read brought a removed card back");
    st.tasksSlow = 0;
    // 4. Close, and open the card again inside the slide-out, for the same card and for another one.
    for (const [first, second] of [["a-1", "a-1"], ["a-1", "z-1"]]) {
      st.tasks = [mCard("a-1", { alias: "alpha", display_title: "alpha" }), mCard("z-1", { alias: "zulu", display_title: "zulu" })];
      st.send("task", {});
      await p.waitForSelector('#m-list .row[data-id="z-1"]', { timeout: slow(5000) });
      await p.tap('#m-list .row[data-id="' + first + '"]');
      await p.waitForSelector("#m-card.on", { timeout: slow(5000) });
      await p.waitForTimeout(500);
      // Right after the back button's popstate, which starts the slide-out, and before it can have finished.
      await p.evaluate(([id, again]) => new Promise(done => {
        addEventListener("popstate", () => { window.mCard.open(again); done(); }, { once: true });
        window.mCard.close();
      }), [first, second]);
      await p.waitForTimeout(700);
      const now = await p.evaluate(() => ({ cur: window.mCard.current(), on: document.getElementById("m-card").classList.contains("on"), hidden: document.getElementById("m-card").hidden }));
      if (now.cur !== second || !now.on || now.hidden) fail(tag + "a tap on " + second + " just after closing " + first + " did nothing: " + JSON.stringify(now));
      await p.evaluate(() => window.mCard.close());
      await p.waitForFunction(() => !document.getElementById("m-card").classList.contains("on"), null, { timeout: slow(2000) });
      await p.waitForTimeout(600);
      if (await p.evaluate(() => !document.getElementById("m-card").hidden)) fail(tag + "the sheet stayed up after a close");
    }
    if (errors.length) fail(tag + "the page threw: " + errors.join(" | "));
    await ctx.close();
  } finally { await st.close(); }

  // The board. `decide` reads its room off the card's own `data-room` and `data-perm`.
  const ctx = await browser.newContext();
  const seen = [];
  await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
  await ctx.route("**/v1/permissions/*/decide", route => { const r = route.request(); seen.push(new URL(r.url()).pathname + " " + (r.headers()["x-atrium-room"] || "")); return route.fulfill({ status: 200, contentType: "application/json", body: "{}" }); });
  await ctx.route("**/v1/rooms/*/permissions/*/decide", route => { const r = route.request(); seen.push(new URL(r.url()).pathname + " " + (r.headers()["x-atrium-room"] || "")); return route.fulfill({ status: 200, contentType: "application/json", body: "{}" }); });
  try {
    const p = await ctx.newPage();
    const errs = [];
    p.on("pageerror", e => errs.push(String(e)));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    for (const hub of [true, false]) {
      await p.evaluate(h => {
        hubIsHub = h;
        let list = document.getElementById("perms-list");
        if (!list) { list = document.createElement("div"); list.id = "perms-list"; document.body.appendChild(list); }
        list.innerHTML = '<div class="perm" data-id="alpha~p1" data-room="alpha" data-perm="p1"></div>';
      }, hub);
      await p.evaluate(() => decide("alpha~p1", "approve", false));
    }
    const want = ["/v1/permissions/p1/decide alpha", "/v1/rooms/alpha/permissions/p1/decide "];
    if (JSON.stringify(seen) !== JSON.stringify(want)) fail(tag + "desktop all-rooms approve sent " + JSON.stringify(seen) + ", want " + JSON.stringify(want));
    if (errs.length) fail(tag + "the board threw: " + errs.join(" | "));
  } finally { await ctx.close(); }
  // The pictures for the item: two rooms attached, the phone's permission rows, and an approve tapped on each.
  // `REVIEW_SHOTS=<dir>` and `REVIEW_SHOT_NAME=before|after`. Not a check.
  if (process.env.REVIEW_SHOTS) {
    const hub = mServer({});
    hub.hubRooms = ["alpha", "beta"];
    hub.tasks = [mCard("alpha~a-1", { room: "alpha", alias: "builder", display_title: "the builder", status: "needs-permission", waiting_since: mIso(2 * M_MIN) }),
      mCard("beta~b-1", { room: "beta", alias: "tester", display_title: "the tester", status: "needs-permission", waiting_since: mIso(3 * M_MIN) })];
    hub.perms = [
      { id: "alpha~p1", room: "alpha", task_id: "alpha~a-1", tool: "Bash", command: "go test ./internal/...", agent: "builder", requested_at: mIso(2 * M_MIN) },
      { id: "beta~p7", room: "beta", task_id: "beta~b-1", tool: "Edit", command: "internal/api/web/m/js/perms.js", agent: "tester", requested_at: mIso(3 * M_MIN) }];
    await hub.open();
    try {
      const { ctx, p } = await mPage(browser, hub, { width: 390, height: 844 }, "");
      await p.waitForSelector("#m-seg-all", { timeout: slow(10000) });
      await p.tap("#m-seg-all");
      await p.waitForSelector('#m-list .row[data-id="alpha~a-1"]', { timeout: slow(10000) });
      await p.tap('#m-list .row[data-id="alpha~a-1"]');
      await p.waitForSelector("#m-card.on .mp-row", { timeout: slow(10000) });
      await p.waitForTimeout(700);
      fs.mkdirSync(process.env.REVIEW_SHOTS, { recursive: true });
      const nm = process.env.REVIEW_SHOT_NAME || "shot";
      await p.screenshot({ path: path.join(process.env.REVIEW_SHOTS, nm + "-rows-390.png") });
      await p.tap('.mp-row[data-id="alpha~p1"] .mp-btn.approve');
      await p.waitForTimeout(900);
      await p.screenshot({ path: path.join(process.env.REVIEW_SHOTS, nm + "-approve-390.png") });
      console.log("review shots " + nm + ": decides " + JSON.stringify(hub.decides));
      await ctx.close();
    } finally { await hub.close(); }
  }
  if (!bad) console.log("mReview ok");
}

async function mReadRetrySection(browser) {
  const tag = "mReadRetry: ";
  for (const status of [0, 401, 403]) {
    const st = mServer({});
    st.tasks = [mCard("q-1", { alias: "alpha", display_title: "alpha" })];
    st.permsStatus = status || 503;
    await st.open();
    try {
      const ctx = await browser.newContext({ viewport: M_VIEWS[0], hasTouch: true, isMobile: true });
      const p = await ctx.newPage();
      // 6.5s of backoff on the page's fake clock, a step at a time so each failed read lands before the next step.
      await p.clock.install();
      await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
      await p.waitForFunction(() => window.mNet.loaded(), null, { timeout: slow(10000) });
      for (let t = 0; t < 6500; t += 100) { await p.clock.runFor(100); await new Promise(r => setTimeout(r, 10)); }
      const n = st.permsHits;
      if (!status && (n < 3 || n > 5)) fail(tag + "a 503 on permissions was read " + n + " times in 6.5s; backoff wants 3 to 5");
      if (status && n > 2) fail(tag + "a " + status + " was retried: " + n + " reads");
      await ctx.close();
    } finally { await st.close(); }
  }
  if (!bad) console.log("mReadRetry ok");
}

async function mBellSection(browser) {
  const st = mServer({});
  st.tasks = [mCard("b-1", { alias: "alpha", display_title: "alpha", status: "running" })];
  await st.open();
  try {
    for (const vp of M_VIEWS) {
      const tag = "mBell " + vp.width + ": ";
      const ctx = await browser.newContext({ viewport: vp, hasTouch: true, isMobile: true });
      await ctx.addInitScript(SOUND_POLICY);
      const p = await ctx.newPage();
      const errors = [];
      p.on("pageerror", e => errors.push(String(e)));
      await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
      await p.waitForSelector("#m-list .row, #m-seg-all", { timeout: slow(10000) });
      await p.waitForFunction(() => window.mNet.loaded(), null, { timeout: slow(8000) });
      const vis = sel => p.evaluate(s => { const e = document.querySelector(s); return !!e && !e.hidden && e.getClientRects().length > 0; }, sel);
      if (!(await vis("#m-bell"))) fail(tag + "no bell in the header");
      if (!(await vis("#m-sound-hint"))) fail(tag + "no tap-to-enable hint while sound is locked");
      await p.tap("#m-seg-all");
      await p.waitForTimeout(150);
      if (await vis("#m-sound-hint")) fail(tag + "the hint is still up after a touch");
      // a request arrives: the sound plays and the bell counts it
      st.perms = [{ id: "px" + vp.width, task_id: "b-1", tool: "Bash", command: "ls", requested_at: mIso(0) }];
      st.send("permission", {});
      await p.waitForFunction(() => window.__osc > 0, null, { timeout: slow(8000) }).catch(() => fail(tag + "no sound for a new request"));
      await p.waitForFunction(() => document.getElementById("m-bell-n").textContent === "1", null, { timeout: slow(3000) })
        .catch(() => fail(tag + "the bell count is " + "not 1"));
      await p.tap("#m-bell");
      await p.waitForSelector("#m-log:not([hidden]) .bl-row", { timeout: slow(3000) });
      if (!/permission needed/.test(await p.textContent("#m-log-list"))) fail(tag + "the log does not list the request");
      if ((await p.textContent("#m-bell-n")) !== "") fail(tag + "the count did not clear on open");
      // the mute is the board's own switch, and a muted page stays quiet
      await p.tap("#m-log-mute");
      if (!(await p.evaluate(() => JSON.parse(localStorage.getItem("atrium.sound") || "{}").muted === true))) fail(tag + "the mute did not write the shared sound state");
      const before = await p.evaluate(() => window.__osc);
      st.perms = [{ id: "py" + vp.width, task_id: "b-1", tool: "Bash", command: "pwd", requested_at: mIso(0) }];
      st.send("permission", {});
      await p.waitForFunction(() => document.getElementById("m-log-list") && true, null, { timeout: slow(1000) });
      await p.waitForTimeout(500);
      if ((await p.evaluate(() => window.__osc)) !== before) fail(tag + "a muted page made a sound");
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      await ctx.close();
    }
  } finally { await st.close(); }
  if (!bad) console.log("mBell ok");
}

// The gear's hub hosts row: the list, add and remove, ignored with why, $ATRIUM_HOSTS read-only, a 403 PUT makes it
// read-only, and a board with no /_hub/hosts draws no row.
async function gearHostsSection(browser, base) {
  const tag = "gearHosts: ";
  const open = async (mode) => {
    const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
    const st = { hosts: ["*.shares.zrok.io", "*.duckdns.org"], puts: [], gets: 0 };
    await ctx.route("**/_hub/hosts", route => {
      const req = route.request();
      if (mode === "none") return route.fulfill({ status: 404, body: "" });
      if (req.method() === "PUT") {
        if (mode === "remote") return route.fulfill({ status: 403, contentType: "application/json", body: JSON.stringify({ error: "only from the hub's machine" }) });
        const b = JSON.parse(req.postData());
        st.puts.push(b.hosts);
        st.hosts = b.hosts;
      } else st.gets++;
      return route.fulfill({ contentType: "application/json", body: JSON.stringify({
        hosts: st.hosts,
        ignored: st.hosts.includes("*.duckdns.org") ? [{ name: "*.duckdns.org", why: "dynamic DNS" }] : [],
        env: ["envhost.example.com"]
      }) });
    });
    const errors = [];
    const p = await ctx.newPage();
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(base, { waitUntil: "domcontentloaded" });
    await p.waitForSelector("#stack-list .stackrow, #term-list .card.tab", { state: "attached", timeout: slow(15000) });
    await p.waitForFunction(() => new Promise(r => requestAnimationFrame(() => r(!!document.getElementById("gear").onclick))),
      null, { timeout: slow(20000), polling: 10 });
    return { ctx, p, st, errors };
  };
  let h = await open("hub");
  try {
    const { p, st } = h;
    await p.click("#gear");
    await p.evaluate(() => showSettingsPane("expose the board"));
    await p.waitForFunction(() => !document.getElementById("s-hh-row").hidden, null, { timeout: slow(10000) });
    const a = await p.evaluate(() => ({
      items: [...document.querySelectorAll("#s-hh-list .hh-item code")].map(c => c.textContent),
      why: document.getElementById("s-hh-list").textContent,
      env: document.getElementById("s-hh-env").textContent,
      help: document.getElementById("s-hh-row").textContent
    }));
    if (a.items.join("|") !== "*.shares.zrok.io|*.duckdns.org") fail(tag + "the list was " + JSON.stringify(a.items));
    if (!/dynamic DNS/.test(a.why)) fail(tag + "an ignored entry shows no reason: " + a.why);
    if (!/envhost\.example\.com/.test(a.env)) fail(tag + "the env names are missing: " + a.env);
    if (await p.$("#s-hh-env button")) fail(tag + "the env names are editable.");
    if (!/HUB's names/.test(a.help) || !/Rooms do not read them/.test(a.help) || !/wildcard is safe only for a\s+domain one operator controls/.test(a.help)) fail(tag + "the row does not say whose names and when a wildcard is safe.");
    await p.fill("#s-hh-name", "box.example.org");
    await p.click("#s-hh-add button");
    await p.waitForFunction(() => document.querySelectorAll("#s-hh-list .hh-item").length === 3, null, { timeout: slow(5000) })
      .catch(() => fail(tag + "an added name did not appear."));
    if (JSON.stringify(st.puts[0]) !== JSON.stringify(["*.shares.zrok.io", "*.duckdns.org", "box.example.org"])) fail(tag + "add PUT " + JSON.stringify(st.puts));
    await p.click('#s-hh-list button[data-remove="*.duckdns.org"]');
    await p.waitForFunction(() => document.querySelectorAll("#s-hh-list .hh-item").length === 2, null, { timeout: slow(5000) })
      .catch(() => fail(tag + "a removed name stayed."));
    if (JSON.stringify(st.puts[1]) !== JSON.stringify(["*.shares.zrok.io", "box.example.org"])) fail(tag + "remove PUT " + JSON.stringify(st.puts));
    if (/dynamic DNS/.test((await p.textContent("#s-hh-list")) + (await p.textContent("#s-hh-ignored")))) fail(tag + "the reason stayed after the entry went.");
    const gets = st.gets;
    await p.evaluate(() => document.getElementById("settings").close());
    await p.click("#gear");
    await p.evaluate(() => showSettingsPane("expose the board"));
    await p.waitForTimeout(400);
    if (st.gets <= gets) fail(tag + "opening the gear did not read the hosts again.");
    if (h.errors.length) fail(tag + "page errors: " + h.errors.join(" | "));
  } finally { await h.ctx.close(); }

  h = await open("remote");
  try {
    const { p } = h;
    await p.click("#gear");
    await p.evaluate(() => showSettingsPane("expose the board"));
    await p.waitForFunction(() => !document.getElementById("s-hh-row").hidden, null, { timeout: slow(10000) });
    await p.fill("#s-hh-name", "x.example.org");
    await p.click("#s-hh-add button");
    await p.waitForFunction(() => !document.getElementById("s-hh-ro").hidden, null, { timeout: slow(5000) })
      .catch(() => fail(tag + "a 403 did not make the row read-only."));
    const r = await p.evaluate(() => ({
      add: getComputedStyle(document.getElementById("s-hh-add")).display,
      removes: document.querySelectorAll("#s-hh-list button").length,
      said: document.getElementById("s-hh-ro").textContent
    }));
    if (r.add !== "none" || r.removes || !/hub's machine/.test(r.said)) fail(tag + "the read-only row is wrong: " + JSON.stringify(r));
  } finally { await h.ctx.close(); }

  h = await open("none");
  try {
    const { p } = h;
    await p.click("#gear");
    await p.evaluate(() => showSettingsPane("expose the board"));
    await p.waitForTimeout(600);
    const hidden = await p.evaluate(() => { const r = document.getElementById("s-hh-row"); return r.hidden || r.offsetParent === null; });
    if (!hidden) fail(tag + "a board with no hub draws the row.");
  } finally { await h.ctx.close(); }
  if (!bad) console.log("gearHosts ok");
}

// ── a phone's board root lands on /m ─────────────────────────────────────
// A coarse pointer and a short side under 600px is a phone. A tablet, a desktop, a pop-out window and a phone that opted
// out are left alone, and the card paths map to their /m twins.
async function phoneRedirectSection(browser, base) {
  const was = mock.tasksMode;
  mock.tasksMode = "land";
  mock.landList = [];
  mock.landPerms = [];
  landCard("land-a", { alias: "rnd", room: "claude-sg4", wire_name: "sparta/rnd-director", supervised: true });
  const raw = fs.readFileSync(path.join(WEB_ROOT, "index.html"));
  const open = async (view, at, setup, fakeClock) => {
    const ctx = await browser.newContext(view, { redirect: true });
    if (fakeClock) await ctx.clock.install();
    await ctx.addInitScript(() => localStorage.setItem("atrium.skipconfirm", JSON.stringify({ "width-floor": true })));
    if (setup) await ctx.addInitScript(setup);
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.route("**/*", route => {
      const rq = route.request();
      const u = new URL(rq.url());
      if (/^\/m\//.test(u.pathname) && rq.resourceType() === "document") return route.fulfill({ status: 200, contentType: "text/html", body: "<!doctype html><title>m</title>phone page" });
      if (/^\/(alias|room)\//.test(u.pathname) && rq.resourceType() === "document") return route.fulfill({ status: 200, contentType: "text/html", body: raw });
      if (u.pathname === "/v1/tasks/rnd") return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(mock.LAND["land-a"]) });
      return route.continue();
    });
    await p.goto(base + at, { waitUntil: "load" });
    await p.waitForTimeout(400);
    const u = new URL(p.url());
    return { ctx, p, errors, where: u.pathname + u.hash, search: u.search };
  };
  const phone = { viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true };
  try {
    const cases = [["/?land=land-a&view=stack&key=k1", "/m/#term=land-a"], ["/?land=a%20b", "/m/#term=a%20b"], ["/?view=perms&key=k2", "/m/"], ["/?land=land-a&x=1", "/m/?x=1#term=land-a"],
      ["/", "/m/"], ["/alias/rnd", "/m/alias/rnd"], ["/room/claude-sg4/rnd", "/m/room/claude-sg4/rnd"], ["/#term=land-a", "/m/#term=land-a"], ["/room/claude-sg4", "/m/"]];
    // Each case is its own context and only reads the mock, so they load at once.
    const opened = await Promise.all(cases.map(([from]) => open(phone, from)));
    for (const [i, [from, to]] of cases.entries()) {
      const r = opened[i];
      if (r.where !== to && !(r.where === to.replace("?x=1", "") && /x=1/.test(r.search))) fail("phoneRedirect: a phone at " + from + " ended on " + r.where + ", not " + to);
      if (from === "/room/claude-sg4" && (await r.p.evaluate(() => localStorage.getItem("atrium.room"))) !== "claude-sg4") fail("phoneRedirect: the room scope was lost");
      if (r.errors.length) fail("phoneRedirect " + from + ": " + r.errors.join(" | "));
      await r.ctx.close();
    }
    // a phone at 412, and a phone turned on its side (its short side is still under 600)
    const turned = [{ viewport: { width: 412, height: 915 }, hasTouch: true, isMobile: true }, { viewport: { width: 844, height: 390 }, hasTouch: true, isMobile: true }];
    for (const [i, r] of (await Promise.all(turned.map(v => open(v, "/")))).entries()) {
      const v = turned[i];
      if (r.where !== "/m/") fail("phoneRedirect: a phone " + v.viewport.width + "x" + v.viewport.height + " ended on " + r.where);
      await r.ctx.close();
    }
    // the opt-out keeps the board, shows the way back, and the way back clears it
    let r = await open(phone, "/", () => { if (!sessionStorage.getItem("seeded")) { sessionStorage.setItem("seeded", "1"); sessionStorage.setItem("atrium.m.desktop", "1"); } });
    if (r.where !== "/") fail("phoneRedirect: an opted-out phone was sent to " + r.where);
    await r.p.evaluate(() => openToastLog());
    if (!(await r.p.isVisible("#toastlog-phone"))) fail("phoneRedirect: no way back to the phone view");
    else {
      await r.p.tap("#toastlog-phone");
      await r.p.waitForFunction(() => location.pathname === "/m/", null, { timeout: slow(5000) }).catch(() => fail("phoneRedirect: phone view did not go to /m"));
      if (await r.p.evaluate(() => sessionStorage.getItem("atrium.m.desktop"))) fail("phoneRedirect: phone view did not clear the opt-out");
    }
    await r.ctx.close();
    // a pop-out window by its name, and by its opener
    r = await open(phone, "/#term=land-a", () => { window.name = "atrium-term-land-a"; });
    if (r.where !== "/#term=land-a") fail("phoneRedirect: a pop-out was sent to " + r.where);
    await r.ctx.close();
    // the opt-out belongs to the tab: another tab goes to /m again, and an old localStorage value is ignored and removed
    {
      const ctx = await browser.newContext(phone, { redirect: true });
      await ctx.addInitScript(() => { try { if (!localStorage.getItem("seen-old")) { localStorage.setItem("seen-old", "1"); localStorage.setItem("atrium.m.desktop", "1"); } } catch (e) {} });
      const route = async p => p.route("**/*", rt => /^\/m\//.test(new URL(rt.request().url()).pathname) && rt.request().resourceType() === "document"
        ? rt.fulfill({ status: 200, contentType: "text/html", body: "<!doctype html><title>m</title>phone page" }) : rt.continue());
      const a = await ctx.newPage();
      await route(a);
      await a.goto(base + "/", { waitUntil: "load" });
      await a.waitForTimeout(300);
      if (new URL(a.url()).pathname !== "/m/") fail("phoneRedirect: an old localStorage opt-out was obeyed");
      if (await a.evaluate(() => localStorage.getItem("atrium.m.desktop"))) fail("phoneRedirect: the old localStorage opt-out was not removed");
      await a.evaluate(() => sessionStorage.setItem("atrium.m.desktop", "1"));
      await a.goto(base + "/", { waitUntil: "load" });
      await a.waitForTimeout(300);
      if (new URL(a.url()).pathname !== "/") fail("phoneRedirect: the tab's own opt-out was not kept");
      const b = await ctx.newPage();
      await route(b);
      await b.goto(base + "/", { waitUntil: "load" });
      await b.waitForTimeout(300);
      if (new URL(b.url()).pathname !== "/m/") fail("phoneRedirect: a new tab did not go to /m after another tab opted out");
      await ctx.close();
    }
    // a touch laptop with a small window on a big screen is not a phone, and a 412x915 phone is
    {
      const lap = await open({ viewport: { width: 500, height: 800 }, screen: { width: 1920, height: 1080 }, hasTouch: true }, "/");
      if (lap.where !== "/") fail("phoneRedirect: a touch laptop with a 500px window was sent to " + lap.where);
      await lap.ctx.close();
      const ph = await open({ viewport: { width: 412, height: 915 }, screen: { width: 412, height: 915 }, hasTouch: true, isMobile: true }, "/");
      if (ph.where !== "/m/") fail("phoneRedirect: a 412x915 phone was sent to " + ph.where);
      await ph.ctx.close();
    }
    // touch points alone make a phone, when the media queries do not say coarse
    {
      const x = await open({ viewport: { width: 390, height: 844 }, hasTouch: true }, "/");
      if (x.where !== "/m/") fail("phoneRedirect: a touch screen with no coarse pointer ended on " + x.where);
      await x.ctx.close();
    }
    // ?why=1 says what happened on every path
    const reason = async (view, at, setup, expect) => {
      const x = await open(view, at, setup);
      const said = await x.p.evaluate(() => { const d = document.getElementById("redirect-why"); return d ? d.textContent : ""; });
      if (!expect.test(said)) fail("phoneRedirect: " + at + " said " + JSON.stringify(said) + ", wanted " + expect);
      await x.ctx.close();
      return x;
    };
    await Promise.all([
      reason({ viewport: { width: 1400, height: 900 } }, "/?why=1", null, /^redirect: not redirected, not a phone \(coarse=false any-coarse=false touch-points=0 shortest-side=900\)/),
      reason(phone, "/?why=1#term=land-a", () => { window.name = "atrium-term-land-a"; }, /^redirect: not redirected, a pop-out window \(atrium-term-land-a\)/),
      reason(phone, "/?why=1", () => { if (!sessionStorage.getItem("seeded")) { sessionStorage.setItem("seeded", "1"); sessionStorage.setItem("atrium.m.desktop", "1"); } }, /^redirect: not redirected, this tab chose the desktop board/),
      reason(phone, "/raw?why=1", null, /^redirect: not redirected, no \/m page for \/raw/)]);
    {
      // The redirect waits 4s so the reason can be read: a fake clock moves through it.
      const x = await open(phone, "/?why=1", null, true);
      const said = await x.p.evaluate(() => (document.getElementById("redirect-why") || {}).textContent || "");
      if (!/^redirect: going to \/m\/ \(coarse=true/.test(said)) fail("phoneRedirect: a redirect said " + JSON.stringify(said));
      await x.p.clock.runFor(4000);
      await x.p.waitForURL(u => new URL(u).pathname === "/m/", { timeout: slow(5000) }).catch(() => fail("phoneRedirect: the redirect with ?why=1 never happened"));
      await x.ctx.close();
    }
    {
      // an opener: a window opened by a page of ours
      const ctx = await browser.newContext(phone, { redirect: true });
      const parent = await ctx.newPage();
      await parent.route("**/*", rt => rt.continue());
      await parent.goto(base + "/raw", { waitUntil: "load" });
      const [pop] = await Promise.all([ctx.waitForEvent("page"), parent.evaluate(b => window.open(b + "/?why=1"), base)]);
      await pop.waitForLoadState("load");
      await pop.waitForTimeout(300);
      const said = await pop.evaluate(() => (document.getElementById("redirect-why") || {}).textContent || "");
      if (!/^redirect: not redirected, this window has an opener/.test(said)) fail("phoneRedirect: a window with an opener said " + JSON.stringify(said));
      if (new URL(pop.url()).pathname !== "/") fail("phoneRedirect: a window with an opener was sent to " + pop.url());
      await ctx.close();
    }
    // a desktop and a tablet are untouched, and so is a desktop browser window made narrow
    await Promise.all([["desktop", { viewport: { width: 1400, height: 900 } }], ["tablet", { viewport: { width: 820, height: 1180 }, hasTouch: true, isMobile: true }],
      ["narrow desktop", { viewport: { width: 400, height: 800 } }]].map(async ([name, v]) => {
      const [x, y] = await Promise.all([open(v, "/"), open(v, "/alias/rnd")]);
      if (x.where !== "/") fail("phoneRedirect: a " + name + " was sent to " + x.where);
      if (y.where !== "/alias/rnd") fail("phoneRedirect: a " + name + " card address was sent to " + y.where);
      await x.ctx.close();
      await y.ctx.close();
    }));
  } finally { mock.tasksMode = was; }
  // the link on /m sets the opt-out and does not bounce back
  const st = mServer({});
  st.tasks = [mCard("r-1", { alias: "a", display_title: "a" })];
  await st.open();
  try {
    const ctx = await browser.newContext({ viewport: M_VIEWS[0], hasTouch: true, isMobile: true }, { redirect: true });
    const p = await ctx.newPage();
    await p.route(st.url + "/", route => route.fulfill({ status: 200, contentType: "text/html", body: raw }));
    await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
    await p.waitForSelector("#m-desktop", { timeout: slow(8000) });
    if (new URL(p.url()).pathname !== "/m/") fail("phoneRedirect: /m left itself for " + p.url());
    await p.tap("#m-desktop");
    await p.waitForFunction(() => location.pathname === "/", null, { timeout: slow(8000) }).catch(() => fail("phoneRedirect: the desktop board link did not leave /m"));
    await p.waitForTimeout(400);
    if (new URL(p.url()).pathname !== "/") fail("phoneRedirect: the desktop board link bounced back to " + p.url());
    if ((await p.evaluate(() => sessionStorage.getItem("atrium.m.desktop"))) !== "1") fail("phoneRedirect: the link did not set the opt-out");
    // a card the board knew only by id opens on /m from the fragment
    const q = await ctx.newPage();
    await q.goto(st.url + "/m/#term=r-1", { waitUntil: "domcontentloaded" });
    await q.waitForSelector("#m-card.on", { timeout: slow(8000) }).catch(() => fail("phoneRedirect: /m/#term=<id> did not open the card"));
    await ctx.close();
  } finally { await st.close(); }
  if (!bad) console.log("phoneRedirect ok");
}

// ── the cards a /m home does not show, and why ───────────────────────────
// A room the page is scoped to is said on the page and can be left. Filters that hide rows say how many, and a tap shows
// them. Hide subagents keeps a running card that has an alias.
async function mHiddenSection(browser) {
  const st = mServer({});
  st.tasks = [
    mCard("orch-1", { alias: "orchestrator", display_title: "orchestrator", status: "running", room: "sg4-control", tags: ["atrium:hold-notices", "atrium:subagent", "orchestrators", "origin:agent"] }),
    mCard("help-1", { display_title: "helper", status: "running", room: "sg4-control", tags: ["origin:agent", "atrium:subagent"] }),
    mCard("done-1", { display_title: "finished", status: "done", room: "sg4-control" }),
    mCard("far-1", { alias: "far", display_title: "far", status: "running", room: "other" }),
  ];
  await st.open();
  try {
    for (const vp of M_VIEWS) {
      const tag = "mHidden " + vp.width + ": ";
      const names = p => p.$$eval("#m-list .row .name b", e => e.map(x => x.textContent).sort());
      const vis = (p, sel) => p.evaluate(s => { const e = document.querySelector(s); return !!e && !e.hidden && e.getClientRects().length > 0; }, sel);
      // (1) scoped to a room
      let ctx = await browser.newContext({ viewport: vp, hasTouch: true, isMobile: true });
      await ctx.addInitScript(() => { if (!sessionStorage.getItem("seeded")) { sessionStorage.setItem("seeded", "1"); localStorage.setItem("atrium.room", "other"); } });
      let p = await ctx.newPage();
      const errors = [];
      p.on("pageerror", e => errors.push(String(e)));
      await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
      await p.tap("#m-seg-all");
      await p.waitForSelector("#m-list .row", { timeout: slow(10000) });
      if ((await names(p)).join() !== "far") fail(tag + "a scoped page lists " + (await names(p)).join());
      if (!(await vis(p, "#m-room-chip")) || !/room: other/.test(await p.textContent("#m-room-chip"))) fail(tag + "the scope is not said on the page");
      await p.tap("#m-room-all");
      await p.waitForFunction(() => document.querySelectorAll("#m-list .row").length === 4, null, { timeout: slow(8000) })
        .catch(async () => fail(tag + "all rooms did not list every card: " + (await names(p)).join()));
      if (await vis(p, "#m-room-chip")) fail(tag + "the room chip stayed after all rooms");
      if (await p.evaluate(() => localStorage.getItem("atrium.room"))) fail(tag + "all rooms did not clear the stored room");
      await ctx.close();
      // (2) and (3) filters
      ctx = await browser.newContext({ viewport: vp, hasTouch: true, isMobile: true });
      await ctx.addInitScript(() => localStorage.setItem("atrium.m.homeopts", JSON.stringify({ order: "newest", group: "none", needsMe: false, hideDone: true, hideSubs: true })));
      p = await ctx.newPage();
      p.on("pageerror", e => errors.push(String(e)));
      await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
      await p.tap("#m-seg-all");
      await p.waitForSelector("#m-list .row", { timeout: slow(10000) });
      const n = await names(p);
      if (n.indexOf("orchestrator") < 0) fail(tag + "hide subagents hid a running card that has an alias: " + n.join());
      if (n.indexOf("helper") >= 0 || n.indexOf("finished") >= 0) fail(tag + "the filters did not hide what they name: " + n.join());
      if (!/^2 hidden by filters/.test(await p.textContent("#m-hidden"))) fail(tag + "the hidden line says " + await p.textContent("#m-hidden"));
      await p.tap("#m-hidden");
      await p.waitForFunction(() => document.querySelectorAll("#m-list .row").length === 4, null, { timeout: slow(5000) })
        .catch(async () => fail(tag + "the tap did not show the hidden rows: " + (await names(p)).join()));
      await p.tap("#m-hidden");
      await p.waitForFunction(() => document.querySelectorAll("#m-list .row").length === 2, null, { timeout: slow(5000) })
        .catch(() => fail(tag + "the second tap did not hide them again"));
      if (await mNoSideways(p)) fail(tag + "the home scrolls sideways");
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      await ctx.close();
    }
  } finally { await st.close(); }
  if (!bad) console.log("mHidden ok");
}

// ── the file viewer on /m ────────────────────────────────────────────────
async function mViewerSection(browser) {
  const st = mServer({});
  const c = mCard("vw-1", { alias: "viewer", display_title: "viewer", worktree: "/w/card", status: "needs-input", waiting_since: mIso(2 * M_MIN), seen: { turn_ended_at: mIso(20 * M_MIN) } });
  st.tasks = [c];
  const big = Buffer.from("line of text that repeats\n".repeat(100000));
  // a multibyte character straddles the megabyte the range read stops at
  const cutme = Buffer.concat([Buffer.from("a"), Buffer.from("\u00e9".repeat(1300000))]);
  st.files = {
    "/w/card/notes/plan.md": Buffer.from("# The plan\n\n## Steps\n\n- one\n- see [other](/w/card/a.txt)\n\n<script>window.__pwn = 1</script>\n"),
    "/w/card/a.txt": Buffer.from("plain text\n  indented <b>not bold</b>\n"),
    "/w/card/empty.txt": Buffer.alloc(0),
    "/w/card/data.json": Buffer.from('{"a":1,"b":[1,2]}'),
    "notes/shot.png": M_PNG,
    "/w/card/big.log": big,
    "/w/card/mid.log": Buffer.from("line of text that repeats\n".repeat(60000)),
    "/w/card/accent.txt": cutme,
    "/w/card/ignores.log": Buffer.from("line of text that repeats\n".repeat(480000)),
    "notes/huge.png": Buffer.concat([M_PNG, Buffer.alloc(25 * 1048576)]),
    "/w/card/latin.txt": Buffer.from([0x63, 0x61, 0x66, 0xe9, 0x0a]),
    "/w/card/pack.zip": Buffer.concat([Buffer.from([80, 75, 3, 4, 0, 0]), Buffer.alloc(3000, 7)]),
    "/w/card/bin.log": Buffer.concat([Buffer.from("text then "), Buffer.from([0, 1, 2]), Buffer.from(" binary")]),
    "/w/card/code.html": Buffer.from("<script>window.__pwn = 2</script><p>hi</p>"),
  };
  st.missing = ["notes/missing.md"];
  st.noRange = ["/w/card/ignores.log"];
  st.noSize = ["notes/huge.png"];
  const filler = Array.from({ length: 40 }, (_, i) => "Filler paragraph " + i + " so that the thread scrolls.").join("\n\n");
  const text = filler + "\n\nFiles: /w/card/notes/plan.md and /w/card/a.txt and /w/card/data.json and [a shot](notes/shot.png) and /w/card/big.log and /w/card/mid.log and /w/card/accent.txt and /w/card/latin.txt and /w/card/ignores.log and [huge](notes/huge.png) and " +
    "/w/card/pack.zip and /w/card/bin.log and /w/card/code.html and /w/card/empty.txt and [gone](notes/gone.md) and [missing](notes/missing.md).";
  st.replies["vw-1"] = { source: "transcript", replies: [{ at: mIso(10 * M_MIN), text }] };
  await st.open();
  try {
    for (const vp of M_VIEWS) {
      const tag = "mViewer " + vp.width + ": ";
      const { ctx, p, errors } = await mReplyPage(browser, st, vp, "vw-1");
      await p.waitForSelector("#m-replies .md-file", { timeout: slow(8000) });
      const file = name => '#m-replies .md-file[data-path$="' + name + '"]';
      const viewer = () => p.evaluate(() => { const v = document.getElementById("m-viewer"); return { open: !v.hidden, title: document.getElementById("m-viewer-title").textContent,
        text: document.getElementById("m-viewer-body").textContent, state: history.state && history.state.mview || "" }; });
      const openFile = async sel => { await p.evaluate(s => document.querySelector(s).scrollIntoView({ block: "center" }), sel); await p.tap(sel); await p.waitForFunction(() => !document.getElementById("m-viewer").hidden, null, { timeout: slow(5000) }); };
      const settle = () => p.waitForFunction(() => !/^loading$/.test(document.getElementById("m-viewer-body").textContent), null, { timeout: slow(8000) });
      const back = async () => { await p.goBack(); await p.waitForFunction(() => document.getElementById("m-viewer").hidden, null, { timeout: slow(5000) }); };
      // What the mock server saw of a streamed file: it waits for the read to be cut, or for the server to finish it.
      const streamEnd = async key => {
        for (let t = 0; t < slow(10000); t += 50) {
          const r = (st.streamed || {})[key] || {};
          if (r.aborted) return r;
          await p.waitForTimeout(50);
        }
        return (st.streamed || {})[key] || {};
      };
      // markdown, through the safe renderer, and Back restores the thread's scroll
      await p.evaluate(() => { const sc = document.getElementById("m-card-scroll"); sc.dispatchEvent(new Event("wheel")); sc.scrollTop = 300; });
      await p.waitForTimeout(150);
      const before = await p.evaluate(() => document.getElementById("m-card-scroll").scrollTop);
      await p.evaluate(s => document.querySelector(s).click(), file("plan.md"));
      await settle();
      let v = await viewer();
      if (!v.open || v.title !== "plan.md" || v.state !== "/w/card/notes/plan.md") fail(tag + "the markdown file did not open as an entry: " + JSON.stringify(v));
      if (!(await p.$("#m-viewer-body .md h3"))) fail(tag + "markdown was not rendered: " + await p.evaluate(() => document.getElementById("m-viewer-body").innerHTML.slice(0, 300)));
      if ((await p.evaluate(() => window.__pwn)) !== undefined || await p.$("#m-viewer-body script")) fail(tag + "script in a file ran");
      if (!/<script>window.__pwn = 1<\/script>/.test(v.text)) fail(tag + "script in markdown is not shown as text");
      // a file named in a file opens in turn, and Back steps through them
      await p.evaluate(() => document.querySelector("#m-viewer-body .md-file").click());
      await p.waitForFunction(() => document.getElementById("m-viewer-title").textContent === "a.txt", null, { timeout: slow(5000) }).catch(() => fail(tag + "a file named in a file did not open"));
      await settle();
      if (!/indented <b>not bold<\/b>/.test((await viewer()).text)) fail(tag + "text is not shown as text");
      await p.goBack();
      await p.waitForFunction(() => document.getElementById("m-viewer-title").textContent === "plan.md", null, { timeout: slow(5000) }).catch(() => fail(tag + "Back did not return to the file before"));
      await back();
      const after = await p.evaluate(() => document.getElementById("m-card-scroll").scrollTop);
      if (Math.abs(after - before) > 2) fail(tag + "Back did not restore the thread's scroll: " + before + " then " + after);
      // json, pretty
      await p.evaluate(s => document.querySelector(s).click(), file("data.json"));
      await settle();
      if (!/\{\n  "a": 1/.test((await viewer()).text)) fail(tag + "json is not pretty printed");
      // text size follows the thread's variable
      await p.evaluate(() => document.getElementById("m-card").style.setProperty("--m-fs", "20px"));
      const fs = await p.evaluate(() => parseFloat(getComputedStyle(document.querySelector("#m-viewer-body pre")).fontSize));
      if (Math.abs(fs - 20) > 1) fail(tag + "the text size does not follow --m-fs: " + fs);
      if (await mNoSideways(p)) fail(tag + "the viewer scrolls the page sideways");
      await back();
      // an image, and its object URL is let go when the sheet closes
      await p.evaluate(() => { window.__revoked = 0; const r = URL.revokeObjectURL; URL.revokeObjectURL = u => { window.__revoked++; return r.call(URL, u); }; });
      await p.evaluate(s => document.querySelector(s).click(), file("notes/shot.png"));
      await p.waitForSelector("#m-viewer-body img.v-img", { timeout: slow(5000) }).catch(() => fail(tag + "the image did not show"));
      if (!(await p.evaluate(() => document.querySelector("#m-viewer-body img.v-img").naturalWidth > 0))) fail(tag + "the image is broken");
      await back();
      if ((await p.evaluate(() => window.__revoked)) < 1) fail(tag + "closing the viewer did not revoke the image");
      // up to 2 MiB the daemon's text route reads it whole
      st.fileReqs = [];
      await p.evaluate(s => document.querySelector(s).click(), file("mid.log"));
      await settle();
      v = await viewer();
      if (/download the rest/.test(v.text) || v.text.length < 1400000) fail(tag + "a 1.5 MB log was cut: " + v.text.length);
      if (!st.fileReqs.some(r => r.method === "GET text" && r.path.endsWith("mid.log")) || st.fileReqs.some(r => r.method === "GET")) fail(tag + "a text file under 2 MiB was not read through the text route");
      await back();
      // a file not in UTF-8 is an unknown type, not garbage
      await p.evaluate(s => document.querySelector(s).click(), file("latin.txt"));
      await settle();
      if (!/Can't preview latin\.txt/.test((await viewer()).text)) fail(tag + "a Latin-1 file was shown as text");
      await back();
      // past 2 MiB it stops at the cap, with a range tied to the file the size came from
      st.fileReqs = [];
      st.ifRanges = [];
      await p.evaluate(s => document.querySelector(s).click(), file("big.log"));
      await settle();
      v = await viewer();
      if (!/showing the first 1(\.0)? MB of 2\.5 MB/.test(v.text) || !/download the rest/.test(v.text)) fail(tag + "the cap line says: " + v.text.slice(-80));
      if (v.text.length > 1048576 + 200) fail(tag + "more than the cap was shown: " + v.text.length);
      if (!(st.fileReqs || []).some(r => r.path.endsWith("big.log") && /^bytes=0-1048575$/.test(r.range))) fail(tag + "the long file was not read with a range");
      if (!st.ifRanges.length) fail(tag + "the range was not tied to the file with If-Range");
      await back();
      // a server that ignores Range answers the whole file, and the read stops at the cap
      st.streamed = {};
      await p.evaluate(s => document.querySelector(s).click(), file("ignores.log"));
      await settle();
      v = await viewer();
      if (!/showing the first 1(\.0)? MB of 12 MB/.test(v.text) || v.text.length > 1048576 + 200) fail(tag + "a 200 to a range read is shown as " + v.text.slice(-60));
      const ig = await streamEnd("/w/card/ignores.log");
      if (!ig.aborted) fail(tag + "a 200 that ignores Range was read to the end: " + JSON.stringify(ig));
      await back();
      // an image with no size is capped too, and asked about
      await p.evaluate(s => document.querySelector(s).click(), file("notes/huge.png"));
      await settle();
      if (!/Can't preview huge\.png/.test((await viewer()).text)) fail(tag + "an over-cap image of unknown size said " + (await viewer()).text);
      const hg = await streamEnd("notes/huge.png");
      if (!hg.aborted) fail(tag + "an image of unknown size was read to the end: " + JSON.stringify(hg));
      await back();
      // a cut inside a character leaves no replacement mark
      await p.evaluate(s => document.querySelector(s).click(), file("accent.txt"));
      await settle();
      v = await viewer();
      if (/\uFFFD/.test(v.text.slice(-4)) || !/download the rest/.test(v.text)) fail(tag + "the cut left a broken character: " + JSON.stringify(v.text.slice(-12)));
      await back();
      // an unknown type is asked about and not downloaded
      st.fileReqs = [];
      await p.evaluate(s => document.querySelector(s).click(), file("pack.zip"));
      await settle();
      v = await viewer();
      if (!/Can't preview pack\.zip \(2\.9 KB\)\. Download\?/.test(v.text)) fail(tag + "the question says: " + v.text);
      await p.waitForTimeout(200);
      if (st.fileReqs.some(r => r.method === "GET")) fail(tag + "the file was read before the question was answered");
      const dl = p.waitForEvent("download", { timeout: slow(5000) });
      await p.tap("#m-viewer-body .v-btn");
      const d = await dl.catch(() => null);
      if (!d || d.suggestedFilename() !== "pack.zip") fail(tag + "yes did not download the file");
      await back();
      // a binary named as text is asked about too
      await p.evaluate(s => document.querySelector(s).click(), file("bin.log"));
      await settle();
      if (!/Can't preview bin\.log/.test((await viewer()).text)) fail(tag + "a binary named .log was shown as text");
      await back();
      // html is shown as text, never run
      await p.evaluate(s => document.querySelector(s).click(), file("code.html"));
      await settle();
      if ((await p.evaluate(() => window.__pwn)) !== undefined || !/<script>window.__pwn = 2<\/script>/.test((await viewer()).text)) fail(tag + "html was not shown as text");
      await back();
      // the two refusals
      await p.evaluate(() => [...document.querySelectorAll("#m-replies .md-file")].find(b => /gone/.test(b.textContent)).click());
      await settle();
      if (!/not in this card's folder, or not readable/.test((await viewer()).text)) fail(tag + "outside the card says " + (await viewer()).text);
      await back();
      await p.evaluate(s => document.querySelector(s).click(), file("empty.txt"));
      await settle();
      if (!/empty file/.test((await viewer()).text) || await p.$("#m-viewer-body pre")) fail(tag + "an empty file shows " + JSON.stringify((await viewer()).text));
      await back();
      await p.evaluate(() => [...document.querySelectorAll("#m-replies .md-file")].find(b => /missing/.test(b.textContent)).click());
      await settle();
      if (!/no such file/.test((await viewer()).text)) fail(tag + "a missing file says " + (await viewer()).text);
      // the chevron leaves the same way
      await p.tap("#m-viewer-back");
      await p.waitForFunction(() => document.getElementById("m-viewer").hidden, null, { timeout: slow(5000) }).catch(() => fail(tag + "the chevron did not close the viewer"));
      if (!(await p.evaluate(() => !document.getElementById("m-card").hidden))) fail(tag + "closing the viewer closed the card");
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      await ctx.close();
    }
  } finally { await st.close(); }
  if (!bad) console.log("mViewer ok");
}

// ── the /m home on the live card list ────────────────────────────────────
// A sanitized snapshot of the real list (scripts/fixtures/live-tasks-0930.json, 183 cards) served through the mock, at 412px,
// with every control used and the rows checked against an independent sort written here from the rules in the brief and
// not from the page's own comparator. HOMEFIX_SHOTS=<dir> writes a JPEG of each state.
async function mHomeLiveSection(browser) {
  const live = JSON.parse(fs.readFileSync(path.join(__dirname, "fixtures", "live-tasks-0930.json"), "utf8"));
  const st = mServer({});
  st.tasks = live;
  await st.open();
  // ── the expectations ──
  const ms = x => Date.parse(x);
  const agentIdleOf = t => (t.status === "needs-input" || t.status === "needs-permission") && t.supervised === false && !t.starting && !t.offline && !(t.pid > 0);
  const needSince = t => {
    const s = t.seen || {};
    const out = [];
    const idle = agentIdleOf(t);
    if (s.answered === false && ((s.open_questions || []).length || s.questions_unparsed)) out.push(ms(s.questions_at) || ms(s.turn_ended_at) || 0);
    if (s.unseen && s.turn_ended_at && !idle) out.push(ms(s.turn_ended_at));
    if (t.status === "needs-input" && !out.length && !idle) out.push(ms(t.waiting_since) || 0);
    return out.length ? Math.min(...out.filter(Boolean).concat(out.some(Boolean) ? [] : [Infinity])) : null;
  };
  const NOT_SUB = ["atrium:director", "atrium:orchestrator", "orchestrators", "atrium:hold-notices", "atrium:context-ceiling"];
  const isSub = t => t.tags.includes("atrium:subagent") && !(t.alias && t.status !== "done" && t.status !== "dead") && !t.tags.some(x => NOT_SUB.includes(x));
  const project = t => {
    const w = (t.worktree || "").replace(/\\/g, "/");
    if (!w) return "";
    const m = /\/(?:github|gitlab|bitbucket)[^/]*\/([^/]+)\/([^/]+)/i.exec(w);
    if (m) return m[1] + "/" + m[2];
    const parts = w.split("/").filter(Boolean);
    return parts.length >= 2 ? parts.slice(-2).join("/") : parts[0] || "";
  };
  // newest first by when the card last did anything, ties by creation then id, and oldest is that whole order reversed
  const newest = (a, b) => ms(b.last_activity_at) - ms(a.last_activity_at) || (a.created_at || "").localeCompare(b.created_at || "") || a.id.localeCompare(b.id);
  const needSet = live.filter(t => needSince(t) !== null);
  const needIds = new Set(needSet.map(t => t.id));
  const cls = t => t.status === "running" ? 0 : agentIdleOf(t) ? 2 : (t.status === "needs-input" || t.status === "needs-permission") ? 1 : 2;
  const expected = state => {
    const all = state.mode === "all";
    const listed = all ? live.slice() : needSet.slice();
    const kept = listed.filter(t => !(all && state.needsMe && !needIds.has(t.id)) && !(state.hideDone && (t.status === "done" || t.status === "dead")) && !(state.hideSubs && isSub(t)));
    let rows;
    if (all) { rows = kept.sort(newest); if (state.order === "oldest") rows.reverse(); }
    else { rows = kept.sort((a, b) => needSince(a) - needSince(b) || a.id.localeCompare(b.id)); if (state.order === "newest") rows.reverse(); }
    let secs;
    if (state.group === "none") secs = all ? [0, 1, 2].map(c => ({ label: ["Working", "Waiting", "Idle"][c], rows: rows.filter(t => cls(t) === c) })).filter(x => x.rows.length) : [{ label: "", rows }];
    else {
      const key = state.group === "room" ? t => t.room : project;
      const by = new Map();
      rows.forEach(t => { const k = key(t); if (!by.has(k)) by.set(k, []); by.get(k).push(t); });
      const names = [...by.keys()].sort((a, b) => !a ? 1 : !b ? -1 : a.localeCompare(b));
      secs = names.map(k => ({ label: k || (state.group === "room" ? "no room" : "no project"), rows: by.get(k) }));
    }
    return { rows, secs, hidden: listed.length - kept.length, listed: listed.length };
  };
  try {
    const vp = { width: 412, height: 915 };
    const ctx = await browser.newContext({ viewport: vp, hasTouch: true, isMobile: true, deviceScaleFactor: 1 });
    const p = await ctx.newPage();
    const errors = [];
    p.on("pageerror", e => errors.push(String(e)));
    await p.goto(st.url + "/m/", { waitUntil: "domcontentloaded" });
    await p.waitForSelector("#m-list .row", { timeout: slow(15000) });
    await p.waitForFunction(n => /\d/.test(document.getElementById("m-seg-all").textContent) && document.getElementById("m-seg-all").textContent.includes(n), String(live.length), { timeout: slow(10000) });
    const shots = process.env.HOMEFIX_SHOTS;
    if (shots) fs.mkdirSync(shots, { recursive: true });
    const cur = () => p.evaluate(() => ({ mode: window.mHome.mode(), o: window.mHome.opts() }));
    // each control by tapping it, only the ones that are not already as wanted
    const apply = async state => {
      let c = await cur();
      if (c.mode !== state.mode) { await p.tap(state.mode === "all" ? "#m-seg-all" : "#m-seg-needs"); c = await cur(); }
      if (await p.$eval("#m-opts", e => e.hidden)) await p.tap("#m-opts-btn");
      const key = state.mode === "all" ? "order" : "orderNeeds";
      if (c.o[key] !== state.order) await p.tap('[data-opt="order"][data-val="' + state.order + '"]');
      if (c.o.group !== state.group) await p.tap('[data-opt="group"][data-val="' + state.group + '"]');
      for (const f of ["needsMe", "hideDone", "hideSubs"]) { c = await cur(); if (!!c.o[f] !== !!state[f]) await p.tap('[data-opt="' + f + '"]'); }
      await p.waitForTimeout(120);
    };
    const check = async (name, state) => {
      const tag = "mHomeLive " + name + ": ";
      await apply(state);
      const exp = expected(state);
      const got = await p.evaluate(() => [...document.querySelectorAll("#m-list > .rw:not(.leaving)")].map(w => w.classList.contains("head")
        ? { head: w.textContent.replace(/\s+/g, " ").trim() } : { id: w.querySelector(".row").dataset.id }));
      const gotIds = got.filter(x => x.id).map(x => x.id);
      const wantIds = exp.secs.flatMap(sx => sx.rows.map(t => t.id));
      if (gotIds.length !== wantIds.length) fail(tag + "the page lists " + gotIds.length + " rows, the independent sort " + wantIds.length);
      const first = wantIds.findIndex((id, i) => gotIds[i] !== id);
      if (first >= 0) fail(tag + "row " + first + " is " + gotIds[first] + ", the independent sort says " + wantIds[first]);
      const wantHeads = exp.secs.filter(sx => sx.label).map(sx => sx.label + " " + sx.rows.length);
      const gotHeads = got.filter(x => x.head).map(x => x.head);
      if (wantHeads.join("|") !== gotHeads.join("|")) fail(tag + "headings are " + gotHeads.slice(0, 4).join("|") + ", wanted " + wantHeads.slice(0, 4).join("|"));
      const counts = await p.evaluate(() => [document.getElementById("m-seg-needs").textContent, document.getElementById("m-seg-all").textContent, (document.getElementById("m-hidden").hidden ? "" : document.getElementById("m-hidden").textContent)]);
      if (!counts[0].includes(String(needSet.length)) || !counts[1].includes(String(live.length))) fail(tag + "the counts say " + counts.slice(0, 2).join(" / ") + ", wanted " + needSet.length + " / " + live.length);
      if (exp.hidden && !new RegExp("^" + exp.hidden + " hidden by filters").test(counts[2])) fail(tag + "the hidden line says '" + counts[2] + "', wanted " + exp.hidden);
      if (!exp.hidden && counts[2]) fail(tag + "a hidden line shows with nothing hidden: " + counts[2]);
      if (state.mode === "all" && state.hideSubs && !state.needsMe && !gotIds.includes("sg4-control~01a0f2da-2455-7345-a4f5-629b06f7c109")) fail(tag + "the orchestrator is hidden by hide subagents");
      if (state.mode === "all" && state.hideSubs && gotIds.some(id => isSub(live.find(t => t.id === id)))) fail(tag + "a subagent is listed with hide subagents on");
      if (await mNoSideways(p)) fail(tag + "the home scrolls sideways");
      if (shots) {
        await p.evaluate(() => { document.getElementById("m-opts").hidden = false; window.scrollTo(0, 0); });
        await p.screenshot({ path: path.join(shots, name + ".jpg"), type: "jpeg", quality: 55 });
      }
    };
    const F = { needsMe: false, hideDone: false, hideSubs: false };
    const states = [];
    for (const mode of ["needs", "all"]) {
      const dflt = mode === "needs" ? "oldest" : "newest", other = mode === "needs" ? "newest" : "oldest";
      states.push([mode + "-default", Object.assign({ mode, order: dflt, group: "none" }, F)]);
      states.push([mode + "-" + other, Object.assign({ mode, order: other, group: "none" }, F)]);
      for (const g of ["room", "project"]) {
        states.push([mode + "-" + dflt + "-by-" + g, Object.assign({ mode, order: dflt, group: g }, F)]);
        states.push([mode + "-" + other + "-by-" + g, Object.assign({ mode, order: other, group: g }, F)]);
      }
      states.push([mode + "-hide-done", Object.assign({ mode, order: dflt, group: "none" }, F, { hideDone: true })]);
      states.push([mode + "-hide-subagents", Object.assign({ mode, order: dflt, group: "none" }, F, { hideSubs: true })]);
      states.push([mode + "-hide-done-and-subagents-" + other, Object.assign({ mode, order: other, group: "none" }, F, { hideDone: true, hideSubs: true })]);
      states.push([mode + "-room-hide-subagents-" + other, Object.assign({ mode, order: other, group: "room" }, F, { hideSubs: true })]);
    }
    states.push(["all-needs-me-only", Object.assign({ mode: "all", order: "newest", group: "none" }, F, { needsMe: true })]);
    states.push(["all-needs-me-and-hide-subagents", Object.assign({ mode: "all", order: "oldest", group: "project" }, F, { needsMe: true, hideSubs: true })]);
    states.push(["all-everything-on", { mode: "all", order: "oldest", group: "room", needsMe: false, hideDone: true, hideSubs: true }]);
    for (const [name, state] of states) await check(name, state);
    // the fixture's own truth, so a changed fixture is noticed here and not as a puzzling row
    if (live.length !== 183 || needSet.length < 20) fail("mHomeLive: the fixture is not the 183-card snapshot: " + live.length + " cards, " + needSet.length + " needing");
    if (errors.length) fail("mHomeLive: page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { await st.close(); }
  if (!bad) console.log("mHomeLive ok");
}

// ── the /m changes sheet ─────────────────────────────────────────────────
// The chip on a reply (from `edited`, no git number, no per-reply fetch), one ?turn= call when it is tapped, the list and a
// file's hunks as two history entries, a tapped line as a chip in the composer and as a quoted block in the sent message, and
// every limit said. The endpoint is a room's, so it is a mock here, in the shape internal/daemon/changes.go answers.
async function mChangesSection(browser) {
  const st = mServer({});
  const c1 = mCard("cg-1", { alias: "coder", display_title: "coder", runner: "claude", worktree: "/w/card", status: "needs-input", waiting_since: mIso(2 * M_MIN), seen: { turn_ended_at: mIso(20 * M_MIN) } });
  const c2 = mCard("cg-2", { alias: "plain", display_title: "plain", worktree: "/w/plain", status: "needs-input", waiting_since: mIso(3 * M_MIN), seen: { turn_ended_at: mIso(20 * M_MIN) } });
  st.tasks = [c1, c2];
  const at1 = new Date(Date.now() - 30 * 60000).toISOString(), at2 = new Date(Date.now() - 20 * 60000).toISOString(), at3 = new Date(Date.now() - 10 * 60000).toISOString();
  st.replies["cg-1"] = { source: "transcript", replies: [{ at: at3, text: "third", edited: 1 }, { at: at2, text: "second" }, { at: at1, text: Array.from({ length: 30 }, (_, i) => "Filler paragraph " + i + " so the thread scrolls.").join("\n\n"), edited: 2 }] };
  st.replies["cg-2"] = { source: "transcript", replies: [{ at: at1, text: "plain card" }] };
  const hunk = "diff --git a/x b/x\n--- a/x\n+++ b/x\n@@ -10,7 +10,7 @@ function f() {\n const U = window.mUtil;\n const MD = window.mMd;\n-const REPLIES_N = 3;\n+const REPLIES_N = 10;\n let openId = \"\";\n let els = null;\n let seq = 0;\n";
  const longHunk = "@@ -1,60 +1,60 @@\n" + Array.from({ length: 60 }, (_, i) => " line " + (i + 1)).join("\n") + "\n";
  const files = [
    { path: "internal/api/web/m/js/card.js", status: "modified", added: 1, removed: 1, hunks: hunk, via: "edits", cumulative: true },
    { path: "docs/shot.png", status: "binary", added: 0, removed: 0, hunks: "" },
    { path: "src/big.js", status: "modified", added: 900, removed: 3, hunks: "", hunks_cut: true },
    { path: "notes/new.txt", status: "added", added: 2, removed: 0, hunks: "@@ -0,0 +1,2 @@\n+one\n+two\n" },
    { path: "old/gone.go", status: "deleted", added: 0, removed: 3, hunks: "@@ -1,3 +0,0 @@\n-a\n-b\n-c\n" },
    { path: "src/long.txt", status: "modified", added: 0, removed: 0, hunks: longHunk },
    // a name with a newline and an ESC, and lines that hold an ESC that ends a paste, a ^C, a NEL, a line separator and a bidi control
    { path: "evil\nname\u001b[201~.txt", status: "modified", added: 1, removed: 1, hunks: "@@ -1,2 +1,2 @@\n-old\u001b[201~\u001b[Z\u0003 \u0085\u2028 end\n+new \u202eevil\u2066 text\n ctx\n" },
  ];
  st.changesFor = (card, q) => {
    if (card !== "cg-1") return { status: 404, body: { error: "this card's directory is not a git worktree" } };
    if (q.get("turn")) return { status: 200, body: { against: "turn", base: "aaaaaaa1", head: "1a2b3c4d5e", dirty: true, total: files.length, files, partial: true, why: "changes made by a shell command are not included; a commit in the turn's window has an author date outside it, so commits may be missing", outside: 2 } };
    if (q.get("against") === "base") return { status: 200, body: { against: "base", base: "bbbbbbb2", head: "1a2b3c4d5e", dirty: false, total: 1, files: [files[3]], cut: { files: 0, hunks: 1, why: "a file over 256 KB is not sent" } } };
    return { status: 200, body: { against: "head", base: "aaaaaaa1", head: "1a2b3c4d5e", dirty: true, total: 403, files: files.slice(0, 2), cut: { files: 401, hunks: 2, why: "over 400 files" } } };
  };
  st.files = { "docs/shot.png": M_PNG, "src/big.js": Buffer.from("x\n") };
  await st.open();
  try {
    for (const vp of M_VIEWS) {
      const tag = "mChanges " + vp.width + ": ";
      const { ctx, p, errors } = await mReplyPage(browser, st, vp, "cg-1");
      const posted = [];
      await p.route("**/v1/tasks/cg-1/message", r => { posted.push(JSON.parse(r.request().postData() || "{}")); return r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ delivered: "terminal" }) }); });
      st.changeReqs = [];
      await p.waitForSelector(".chg-chip", { timeout: slow(8000) });
      // the chip: from `edited`, no git numbers, and no call until it is tapped
      const chips = await p.$$eval(".chg-chip", e => e.map(x => x.textContent));
      if (chips.slice().sort().join("|") !== "1 file edited|2 files edited") fail(tag + "the chips read " + chips.join("|"));
      if (chips.some(t => /[+-]\d/.test(t))) fail(tag + "a chip carries git counts: " + chips.join("|"));
      if (await p.$$eval(".reply", e => e.length) !== 3 || st.changeReqs.length) fail(tag + "the thread asked for changes before a tap: " + st.changeReqs.length);
      const sheet = () => p.evaluate(() => { const s = document.getElementById("m-changes"); return { open: !s.hidden, title: document.getElementById("m-changes-title").textContent, text: document.getElementById("m-changes-body").textContent, state: history.state && history.state.mchg || "" }; });
      const wait = fn => p.waitForFunction(fn, null, { timeout: slow(6000) });
      const back = async () => { await p.goBack(); await p.waitForTimeout(150); };
      await p.evaluate(() => { const sc = document.getElementById("m-card-scroll"); sc.dispatchEvent(new Event("wheel")); sc.scrollTop = 120; });
      await p.waitForTimeout(150);
      const before = await p.evaluate(() => document.getElementById("m-card-scroll").scrollTop);
      // the turn
      const chipFor = at => '.chg-chip[data-at="' + at + '"]';
      await p.evaluate(s => document.querySelector(s).click(), chipFor(at1));
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 7);
      if (st.changeReqs.length !== 1 || st.changeReqs[0].search !== "?turn=" + encodeURIComponent(at1)) fail(tag + "the chip made " + JSON.stringify(st.changeReqs));
      let sh = await sheet();
      if (!sh.open || sh.state !== "list" || !/^Turn \d\d:\d\d$/.test(sh.title)) fail(tag + "the sheet is " + JSON.stringify({ open: sh.open, state: sh.state, title: sh.title }));
      if (!/^7 files edited \+904 -8/.test(sh.text)) fail(tag + "the totals say " + sh.text.slice(0, 40));
      if (/may miss changes made by commands/.test(sh.text) || (sh.text.match(/shell command/g) || []).length !== 1) fail(tag + "the partial fact is not said exactly once: " + sh.text.slice(0, 300));
      // 5f: a file that dwarfs the rest leaves the small ones a visible bar, and the numbers stay exact
      const bars = await p.$$eval("#m-changes-body .cg-file", e => e.map(r => ({ p: r.dataset.path, w: [...r.querySelectorAll(".cg-bar i")].reduce((a, i) => a + parseFloat(i.style.width || 0), 0), s: r.querySelector(".cg-stat").textContent })));
      const small = bars.filter(b => /card\.js|new\.txt|gone\.go/.test(b.p));
      if (small.length !== 3 || small.some(b => b.w < 5)) fail(tag + "a small file has no visible bar next to a big one: " + JSON.stringify(bars));
      if (!bars.some(b => /big\.js/.test(b.p) && b.s === "+900 -3") || !bars.some(b => /card\.js/.test(b.p) && b.s === "+1 -1")) fail(tag + "the counts are not exact: " + JSON.stringify(bars));
      if (!/2 edits outside this card's folder are not shown/.test(sh.text)) fail(tag + "outside is not said");
      if (/all uncommitted edits/.test(sh.text)) fail(tag + "cumulative shows in the list");
      if ((sh.text.match(/commits may be missing/g) || []).length !== 1) fail(tag + "the room's why is not shown once: " + sh.text.slice(0, 200));
      if (await mNoSideways(p)) fail(tag + "the list scrolls sideways");
      // back from the list leaves for the thread at its scroll, and the chip opens it again with one more call
      await back();
      await wait(() => document.getElementById("m-changes").hidden);
      const after = await p.evaluate(() => document.getElementById("m-card-scroll").scrollTop);
      if (Math.abs(after - before) > 2) fail(tag + "Back did not restore the thread's scroll: " + before + " then " + after);
      await p.evaluate(s => document.querySelector(s).click(), chipFor(at1));
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 7);
      // a file: its own entry, cumulative on its header, a gutter that numbers new on + and context and old on -
      await p.evaluate(() => document.querySelector('#m-changes-body .cg-file[data-path$="card.js"]').click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-row").length > 0);
      sh = await sheet();
      if (sh.state !== "file" || !/all uncommitted edits to this file, not only this turn/.test(sh.text)) fail(tag + "the file header says " + sh.text.slice(0, 120));
      const rows = await p.$$eval("#m-changes-body .cg-row", e => e.map(r => r.querySelector(".cg-ln").textContent + r.querySelector(".cg-sg").textContent));
      if (rows.join(",") !== "10,11,12-,12+,13,14,15") fail(tag + "the gutter reads " + rows.join(","));
      if (!(await p.$("#m-changes-body mark"))) fail(tag + "the changed words are not marked");
      // tapping lines: chips in the composer, then the message
      await p.evaluate(() => { const r = [...document.querySelectorAll("#m-changes-body .cg-row")]; r[2].click(); r[3].click(); r[0].click(); });
      const labels = await p.$$eval("#m-compose .mc-cmt .mc-fname", e => e.map(x => x.textContent));
      if (labels.join("|") !== "card.js:12 removed|card.js:12|card.js:10") fail(tag + "the chips read " + labels.join("|"));
      if ((await p.$$eval("#m-changes-body .cg-row.on", e => e.length)) !== 3) fail(tag + "tapped lines are not marked");
      // a second tap takes a line off, and so does its chip
      await p.evaluate(() => document.querySelectorAll("#m-changes-body .cg-row")[0].click());
      if ((await p.$$eval("#m-compose .mc-cmt", e => e.length)) !== 2) fail(tag + "tapping a line twice did not take its chip off");
      // 5l: and the line is unmarked, so the marks say what will be sent, and a third tap quotes it again
      if ((await p.$$eval("#m-changes-body .cg-row.on", e => e.length)) !== 2 || (await p.$eval("#m-changes-body .cg-row", e => e.classList.contains("on")))) fail(tag + "the line stayed marked after its second tap");
      await p.evaluate(() => document.querySelectorAll("#m-changes-body .cg-row")[0].click());
      if ((await p.$$eval("#m-compose .mc-cmt", e => e.length)) !== 3 || (await p.$$eval("#m-changes-body .cg-row.on", e => e.length)) !== 3) fail(tag + "the third tap did not quote the line again and mark it");
      await p.evaluate(() => document.querySelectorAll("#m-changes-body .cg-row")[0].click());
      await p.fill("#m-compose textarea", "why 10?");
      await p.evaluate(() => document.querySelector("#m-compose textarea").dispatchEvent(new Event("input", { bubbles: true })));
      await p.tap("#m-compose .mc-send");
      await p.waitForFunction(() => true);
      await p.waitForTimeout(300);
      const hh = new Date(at1).getHours().toString().padStart(2, "0") + ":" + new Date(at1).getMinutes().toString().padStart(2, "0");
      const want = "review comment on internal/api/web/m/js/card.js line 12, removed (turn " + hh + ", head 1a2b3c4):\n    -const REPLIES_N = 3;\n" +
        "review comment on internal/api/web/m/js/card.js line 12 (turn " + hh + ", head 1a2b3c4):\n    +const REPLIES_N = 10;\nwhy 10?";
      if (posted.length !== 1 || posted[0].text !== want) fail(tag + "the message was " + JSON.stringify(posted));
      if ((await p.$$eval("#m-compose .mc-cmt", e => e.length)) !== 0 || (await p.$$eval("#m-changes-body .cg-row.on", e => e.length)) !== 0) fail(tag + "chips or marks stayed after the send");
      // a context line quotes with a space where the sign is
      await p.evaluate(() => document.querySelectorAll("#m-changes-body .cg-row")[0].click());
      await p.fill("#m-compose textarea", "ok");
      await p.evaluate(() => document.querySelector("#m-compose textarea").dispatchEvent(new Event("input", { bubbles: true })));
      await p.tap("#m-compose .mc-send");
      await p.waitForTimeout(300);
      if (posted.length !== 2 || !posted[1].text.includes("line 10 (turn " + hh + ", head 1a2b3c4):\n     const U = window.mUtil;\nok")) fail(tag + "a context line was quoted as " + JSON.stringify(posted[1]));
      // text size
      await p.evaluate(() => document.getElementById("m-card").style.setProperty("--m-fs", "20px"));
      if (Math.abs(await p.evaluate(() => parseFloat(getComputedStyle(document.querySelector("#m-changes-body .cg-row")).fontSize)) - 20) > 1) fail(tag + "the text size does not follow --m-fs");
      if (await mNoSideways(p)) fail(tag + "the hunks scroll the page sideways");
      // All files is history.back
      await p.evaluate(() => document.querySelector(".cg-all").click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 7);
      sh = await sheet();
      if (sh.state !== "list") fail(tag + "All files left the state at " + sh.state);
      // binary: not shown, and open goes to the viewer
      await p.evaluate(() => document.querySelector('#m-changes-body .cg-file[data-path$="shot.png"]').click());
      await wait(() => /binary, not shown/.test(document.getElementById("m-changes-body").textContent));
      await p.evaluate(() => document.querySelector("#m-changes-body .cg-open").click());
      await wait(() => !document.getElementById("m-viewer").hidden);
      await wait(() => document.querySelector("#m-viewer-body img.v-img"));
      await back();
      await wait(() => document.getElementById("m-viewer").hidden);
      if (!/binary, not shown/.test((await sheet()).text)) fail(tag + "Back from the viewer did not return to the file");
      await back();
      // too large, and deleted has no open
      await p.evaluate(() => document.querySelector('#m-changes-body .cg-file[data-path$="big.js"]').click());
      await wait(() => /too large to show here/.test(document.getElementById("m-changes-body").textContent));
      if (!/\+900 -3, too large to show here/.test((await sheet()).text) || !(await p.$("#m-changes-body .cg-open"))) fail(tag + "a file over the bound is not offered to open: " + (await sheet()).text);
      await back();
      await p.evaluate(() => document.querySelector('#m-changes-body .cg-file[data-path$="gone.go"]').click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-row").length === 3);
      if (await p.$("#m-changes-body .cg-open")) fail(tag + "a deleted file can be opened");
      await back();
      // a long hunk is folded
      await p.evaluate(() => document.querySelector('#m-changes-body .cg-file[data-path$="long.txt"]').click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-row").length === 40);
      await p.evaluate(() => document.querySelector("#m-changes-body .cg-more").click());
      if ((await p.$$eval("#m-changes-body .cg-row", e => e.length)) !== 60) fail(tag + "show full hunk did not show the rest");
      await back();
      // a hostile name and hostile lines: shown as text, and quoted into the message as visible forms, never raw
      await p.evaluate(() => document.querySelector('#m-changes-body .cg-file[data-path^="evil"]').click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-row").length === 3);
      const shown = await p.evaluate(() => ({ ctl: [...document.querySelectorAll("#m-changes-body .cg-ctl")].map(e => e.textContent), raw: /[\u202a-\u202e\u2066-\u2069]/.test(document.getElementById("m-changes-body").textContent) }));
      if (shown.ctl.join() !== "<U+202E>,<U+2066>" || shown.raw) fail(tag + "bidi controls are not marked: " + JSON.stringify(shown));
      posted.length = 0;
      await p.evaluate(() => document.querySelectorAll("#m-changes-body .cg-row")[0].click());
      await p.fill("#m-compose textarea", "danger");
      await p.evaluate(() => document.querySelector("#m-compose textarea").dispatchEvent(new Event("input", { bubbles: true })));
      await p.tap("#m-compose .mc-send");
      await p.waitForTimeout(300);
      const evil = (posted[0] || {}).text || "";
      if (/[\u0000-\u0009\u000b-\u001f\u007f-\u009f\u2028\u2029]/.test(evil)) fail(tag + "a control character reached the message: " + JSON.stringify(evil));
      if (evil.split("\n").length !== 3) fail(tag + "the message split into " + evil.split("\n").length + " lines: " + JSON.stringify(evil));
      if (!evil.includes("evil\u240aname\u241b[201~.txt") || !evil.includes("-old\u241b[201~\u241b[Z\u2403 \\x85\u23ce end")) fail(tag + "the quote is not the visible form: " + JSON.stringify(evil));
      await p.evaluate(() => document.querySelector(".cg-all").click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 7);
      // back from the list leaves for the thread
      await back();
      await wait(() => document.getElementById("m-changes").hidden);
      // the card's own changes: uncommitted, a toggle, what was cut said
      st.changeReqs = [];
      await p.tap("#m-card-changes");
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 2);
      sh = await sheet();
      if (st.changeReqs.length !== 1 || st.changeReqs[0].search !== "?against=head" || sh.title !== "Changes") fail(tag + "the card's changes asked " + JSON.stringify(st.changeReqs));
      if (!/401 more files not listed, 2 files show counts only \(over 400 files\)/.test(sh.text) || (sh.text.match(/over 400 files/g) || []).length !== 1) fail(tag + "what was cut is not said once: " + sh.text);
      if (/may miss changes/.test(sh.text)) fail(tag + "the card view carries the turn's partial line");
      await p.evaluate(() => [...document.querySelectorAll(".cg-toggle button")].find(b => /since base/.test(b.textContent)).click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 1);
      if (st.changeReqs.length !== 2 || st.changeReqs[1].search !== "?against=base") fail(tag + "since base asked " + JSON.stringify(st.changeReqs));
      // 5g: one file cut reads "1 file shows counts only", the reason once and no count inside it
      if (!/1 file shows counts only \(a file over 256 KB is not sent\)/.test((await sheet()).text) || /1 files/.test((await sheet()).text)) fail(tag + "the singular cut note reads " + (await sheet()).text);
      // refreshed when the card stops, and said while it works
      st.tasks[0] = Object.assign({}, c1, { status: "running", activity: { what: "tool", tool: "Edit", seconds: 1 } });
      st.send("task", Object.assign({ row: 1 }, st.tasks[0]));
      await wait(() => /the agent is still working/.test(document.getElementById("m-changes-body").textContent));
      const n = st.changeReqs.length;
      await p.waitForTimeout(300);
      if (st.changeReqs.length !== n) fail(tag + "the sheet asked again while the card was running");
      st.tasks[0] = Object.assign({}, c1, { status: "needs-input", seen: { turn_ended_at: new Date().toISOString() } });
      st.send("task", Object.assign({ row: 1 }, st.tasks[0]));
      await wait(() => !/the agent is still working/.test(document.getElementById("m-changes-body").textContent));
      await p.waitForTimeout(200);
      if (st.changeReqs.length !== n + 1) fail(tag + "the card's Stop made " + (st.changeReqs.length - n) + " reads, not one");
      await back();
      if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      await ctx.close();
      // a card that is not a git worktree says so, and shows no empty diff
      const w = await mReplyPage(browser, st, vp, "cg-2");
      await w.p.tap("#m-card-changes");
      await w.p.waitForFunction(() => /not a git worktree/.test(document.getElementById("m-changes-body").textContent), null, { timeout: slow(6000) })
        .catch(() => fail(tag + "a non-git card did not say so"));
      if (await w.p.$("#m-changes-body .cg-file") || /no changes/.test(await w.p.textContent("#m-changes-body"))) fail(tag + "a non-git card shows an empty diff");
      await w.ctx.close();
    }
  } finally { await st.close(); }
  if (!bad) console.log("mChanges ok");
}

// ── the changes sheet on a real answer ───────────────────────────────────
// A /changes answer taken from the live room (docs/backlog/ui/img/u-m-code-review/real-changes.json), with its real `hunks` text:
// diff --git, new file mode, --- and +++ headers, an empty added file named NUL, a modified file. Served as the card-level answer
// and, with via, cumulative and partial set, as a turn's. REAL_SHOTS=<dir> writes the 412px PNGs of the states.
async function mChangesRealSection(browser) {
  const real = JSON.parse(fs.readFileSync(path.join(WEB_ROOT, "..", "..", "..", "docs", "backlog", "ui", "img", "u-m-code-review", "real-changes.json"), "utf8"));
  const st = mServer({});
  const c1 = mCard("cr-1", { alias: "real", display_title: "real", runner: "claude", worktree: "/w/card", status: "needs-input", waiting_since: mIso(2 * M_MIN), seen: { turn_ended_at: mIso(20 * M_MIN) } });
  st.tasks = [c1];
  const at = new Date(Date.now() - 15 * 60000).toISOString();
  st.replies["cr-1"] = { source: "transcript", replies: [{ at, text: Array.from({ length: 12 }, (_, i) => "Paragraph " + i + " of the reply.").join("\n\n"), edited: real.files.length }] };
  const turn = Object.assign({}, real, { against: "turn", partial: true, why: "edit calls only", outside: 0,
    files: real.files.map(f => Object.assign({}, f, { via: f.path === "NUL" ? "commits" : "edits", cumulative: f.path.endsWith("QUEUE.md") })) });
  st.changesFor = (card, q) => ({ status: 200, body: q.get("turn") ? turn : real });
  await st.open();
  // what the gutter should say for a file, worked out here from the hunk text and not from the page
  const gutter = text => {
    const out = [];
    let o = 0, n = 0, inH = false;
    for (const line of text.replace(/\r/g, "").split("\n")) {
      const m = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/.exec(line);
      if (m) { o = +m[1]; n = +m[2]; inH = true; continue; }
      if (!inH || line === "" || line[0] === "\\") continue;
      if (line[0] === "+") out.push(n++ + "+"); else if (line[0] === "-") out.push(o++ + "-"); else { out.push(n + " "); n++; o++; }
    }
    return out;
  };
  const shots = process.env.REAL_SHOTS;
  if (shots) fs.mkdirSync(shots, { recursive: true });
  try {
    const vp = { width: 412, height: 915 };
    const tag = "mChangesReal: ";
    const { ctx, p, errors } = await mReplyPage(browser, st, vp, "cr-1");
    await p.waitForSelector(".chg-chip", { timeout: slow(8000) });
    const wait = fn => p.waitForFunction(fn, null, { timeout: slow(6000) });
    const body = () => p.evaluate(() => document.getElementById("m-changes-body").textContent);
    const shot = async name => { if (shots) { await p.evaluate(() => { document.getElementById("m-changes-scroll").scrollTop = 0; }); await p.screenshot({ path: path.join(shots, "real-" + name + ".png"), type: "png" }); } };
    const openFile = async name => { await p.evaluate(n => document.querySelector('#m-changes-body .cg-file[data-path="' + n + '"]').click(), name); await wait(() => document.querySelector("#m-changes-body .cg-all")); };
    const rowsOf = () => p.$$eval("#m-changes-body .cg-row", e => e.map(r => r.querySelector(".cg-ln").textContent + (r.querySelector(".cg-sg").textContent || " ")));
    // the card's own changes
    await p.tap("#m-card-changes");
    await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 4);
    if (!/^4 files changed \+109 -0/.test(await body())) fail(tag + "the totals say " + (await body()).slice(0, 40));
    const names = await p.$$eval("#m-changes-body .cg-file .cg-path", e => e.map(x => x.textContent));
    if (names.join("|") !== "BRIEF.md|DIRECTOR.md|NUL|docs/backlog/runtime/QUEUE.md") fail(tag + "the files are " + names.join("|"));
    await shot("list");
    for (const f of real.files) {
      if (!f.hunks) continue;
      await openFile(f.path);
      if (f.path === "BRIEF.md") { await shot("hunks"); }
      // a long hunk is folded at 40 lines, so the whole of it is asked for before the gutter is read
      while (await p.$("#m-changes-body .cg-more")) await p.evaluate(() => document.querySelector("#m-changes-body .cg-more").click());
      const got = await rowsOf();
      const want = gutter(f.hunks);
      { const at = want.findIndex((w, i) => got[i] !== w); if (got.length !== want.length || at >= 0) fail(tag + f.path + " gutter has " + got.length + " rows, wanted " + want.length + ", first difference at " + at + ": " + JSON.stringify(got[at]) + " against " + JSON.stringify(want[at])); }
      if (/diff --git|new file mode|^---|\+\+\+ b\//m.test(await p.evaluate(() => [...document.querySelectorAll("#m-changes-body .cg-row")].map(r => r.textContent).join("\n")))) fail(tag + f.path + ": a header line is drawn as code");
      if (f.path.endsWith("QUEUE.md")) await shot("modified");
      await p.evaluate(() => document.querySelector(".cg-all").click());
      await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 4);
    }
    // the empty file named NUL
    await openFile("NUL");
    const nul = await body();
    if (!/empty file, added/.test(nul) || /nothing to show/.test(nul)) fail(tag + "the empty NUL file says " + JSON.stringify(nul));
    if (await p.$("#m-changes-body .cg-row")) fail(tag + "the empty file draws rows");
    await shot("empty-nul");
    await p.evaluate(() => document.querySelector(".cg-all").click());
    await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 4);
    if (await mNoSideways(p)) fail(tag + "the sheet scrolls sideways");
    // the turn's answer from the same files: partial once, cumulative on that file only
    await p.goBack();
    await wait(() => document.getElementById("m-changes").hidden);
    await p.evaluate(a => document.querySelector('.chg-chip[data-at="' + a + '"]').click(), at);
    await wait(() => document.querySelectorAll("#m-changes-body .cg-file").length === 4);
    const tl = await body();
    if (!/^4 files edited/.test(tl) || (tl.match(/may miss changes made by commands/g) || []).length !== 1 || !/edit calls only/.test(tl)) fail(tag + "the turn list says " + tl.slice(0, 160));
    await openFile("BRIEF.md");
    if (/all uncommitted edits/.test(await body())) fail(tag + "cumulative shows on a file that is not cumulative");
    await p.evaluate(() => document.querySelector(".cg-all").click());
    await openFile("docs/backlog/runtime/QUEUE.md");
    if (!/all uncommitted edits to this file, not only this turn/.test(await body())) fail(tag + "cumulative is missing on its file");
    if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
    await ctx.close();
  } finally { await st.close(); }
  if (!bad) console.log("mChangesReal ok");
}

// THE TRAY'S TITLE NEVER TOUCHES ITS FIRST BUTTON. At the narrowest tray the board allows (92vw of a 320px window) the
// head wraps its buttons rather than squeezing the title: nothing in the head overlaps anything else, the title is whole (not
// ellipsised) and on one line, and when the first button shares the title's line a gap of at least 8px stays between.
async function trayHeadSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const p = await ctx.newPage();
  const errors = [];
  p.on("pageerror", e => errors.push(String(e)));
  try {
    await p.goto(base + "/", { waitUntil: "domcontentloaded" });
    await p.waitForFunction(() => typeof alerting !== "undefined" && !!document.getElementById("toastlog"), null, { timeout: slow(15000) });
    for (const w of [320, 360, 901, 1400]) {
      await p.setViewportSize({ width: w, height: 800 });
      await p.evaluate(() => { const d = document.getElementById("toastlog"); if (!d.open) d.showModal(); });
      await p.waitForTimeout(250);
      const v = await p.evaluate(() => {
        const head = document.querySelector("#toastlog .dlg-head");
        const r = e => { const b = e.getBoundingClientRect(); return { l: b.left, r: b.right, t: b.top, b: b.bottom }; };
        const title = document.querySelector("#toastlog .dlg-head h2");
        const tr = r(title);
        if (!title.getClientRects().length) return { hidden: true };
        const kids = [...head.children].filter(e => e.getClientRects().length && !e.classList.contains("grow"));
        const hr = r(head);
        const boxes = kids.map(r);
        let overlap = "";
        const all = [r(head.querySelector(".grow")), ...boxes];
        for (let i = 0; i < all.length; i++) for (let j = i + 1; j < all.length; j++) {
          const a = all[i], b = all[j];
          if (a.l < b.r - 0.5 && b.l < a.r - 0.5 && a.t < b.b - 0.5 && b.t < a.b - 0.5) overlap += i + "/" + j + " ";
        }
        const first = boxes[0];
        const sameLine = first.t < tr.b;
        return {
          overlap, whole: title.scrollWidth <= title.clientWidth, oneLine: tr.b - tr.t < 2 * parseFloat(getComputedStyle(title).lineHeight || 30),
          gap: sameLine ? first.l - tr.r : null, sameLine, spill: boxes.some(b => b.r > hr.r + 0.5 || b.l < hr.l - 0.5), width: hr.r - hr.l,
        };
      });
      const tag = "trayHead " + w + ": ";
      if (v.hidden) fail(tag + "the title is not shown");
      if (v.overlap) fail(tag + "head children overlap (" + v.overlap + "): " + JSON.stringify(v));
      if (!v.whole) fail(tag + "the title is cut: " + JSON.stringify(v));
      if (v.sameLine && v.gap < 8) fail(tag + "the first button sits " + v.gap + "px from the title: " + JSON.stringify(v));
      if (v.spill) fail(tag + "a button spills out of the head: " + JSON.stringify(v));
    }
    if (errors.length) fail("trayHead: page errors: " + errors.join(" | "));
  } finally {
    await ctx.close();
  }
  if (!bad) console.log("trayHead ok");
}

// ── units, and running the suite in shards ────────────────────────────────────────────────────────────────────────
// The default run is a list of UNITS in a fixed order: every section, plus the inline blocks of main() that share one
// page (core, core2) or one mock state (gauto, switches). A unit is the smallest thing that can move to another process.
//   HEADLESS_UNITS=a,b,c      run just those units, in the suite's own order, each one's failure kept to itself
//   HEADLESS_LIST=1           print the units and their pin groups as JSON and stop, with no browser
//   HEADLESS_RESULTS=file     write { unit: { ms, ok, fails } } there when the run ends
//   HEADLESS_TRACE=1          print each page action (click, fill, waitFor...) as it starts, with its unit and line
// scripts/test-board-sharded.js is the caller: it splits the units over several processes of this file and merges what
// they write. With none of these set the run is the plain serial one, one throw ends it, as it always did.
//
// Units that share state stay in one process. A pin group is run together, in suite order, on one shard:
const PIN_GROUPS = {
  // core and core2 drive ONE page (main's `page`) that is left on the view and the mock state the last block set,
  // and history sits between them on the same mock server, so it keeps its place.
  core: { units: ["core", "history", "core2"], why: "one shared page and the mock state each block leaves for the next" },
};
const UNIT_FILTER = process.env.HEADLESS_UNITS ? new Set(process.env.HEADLESS_UNITS.split(",").filter(Boolean)) : null;
const LIST_MODE = !!process.env.HEADLESS_LIST;
const unitOrder = [];
const unitResults = {};
// The mock's own state is `mock` (lib/mock.js): every loose `let` a section sets and every object it mutates in place. A
// unit can leave one set (soloMode "gone" after core2, say) and break whichever unit runs next, so before each unit
// the run puts them all back to how the process started, except between the members of a pin group, which are meant to see
// each other's state. This holds for the serial run and for a shard alike. A new piece of state goes on `mock`, and the
// listing fails on a module-level `let` in this file or in lib/mock.js.
let pristine = null, lastUnit = "";
const pinnedTogether = (a, b) => Object.values(PIN_GROUPS).some(g => g.units.includes(a) && g.units.includes(b));
// What a unit changed on `mock`, field by field, as JSON.
function mockSnapshot() {
  const s = mock.snapshot();
  const out = {};
  for (const k of Object.keys(s)) { try { out[k] = JSON.stringify(s[k]); } catch (e) { out[k] = "?"; } }
  return out;
}
// HEADLESS_LEAKS=1 prints, after each unit, the mock variables it left different from how it found them.
async function unit(name, fn) {
  unitOrder.push(name);
  if (LIST_MODE || (UNIT_FILTER && !UNIT_FILTER.has(name))) return;
  if (!pristine) pristine = mock.snapshot();
  else if (!pinnedTogether(lastUnit, name)) mock.reset(pristine);
  lastUnit = name;
  const before = bad, t0 = Date.now();
  const snap0 = process.env.HEADLESS_LEAKS ? mockSnapshot() : null;
  results.currentUnit = name;
  try { await fn(); }
  catch (e) {
    if (!UNIT_FILTER) throw e;
    fail(name + ": the unit threw: " + threwMessage(e));
  } finally { results.currentUnit = ""; }
  const ms = Date.now() - t0;
  if (snap0) {
    const snap1 = mockSnapshot();
    for (const k of Object.keys(snap1)) if (snap1[k] !== snap0[k]) console.log("LEAK " + name + " " + k + ": " + String(snap0[k]).slice(0, 60) + " -> " + String(snap1[k]).slice(0, 60));
  }
  unitResults[name] = { ms, ok: bad === before, fails: results.unitFails[name] || [] };
  console.log("TIMING " + name + " " + ms);
}
function writeUnitResults() {
  if (!process.env.HEADLESS_RESULTS) return;
  try { fs.writeFileSync(process.env.HEADLESS_RESULTS, JSON.stringify({ units: unitResults, order: unitOrder, bad })); }
  catch (e) { console.error("could not write HEADLESS_RESULTS: " + e.message); }
}

// HOVERING A TERMINAL ROW WARMS ITS CARD, and only that. Resting the mouse on a row for ~100ms fetches
// GET /v1/tasks/<id> once, a pointer that leaves first fetches nothing, a sweep down the list warms nothing, a touch
// pointer never does, and no websocket is opened by any of it (a ws takes one of the hub's warm connections to a room
// for its life). The click then uses what was fetched rather than asking again.
async function switchPrewarmSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const wp = await ctx.newPage();
  const errors = [];
  wp.on("pageerror", e => errors.push(String(e)));
  await wp.addInitScript(() => {
    window.__socks = 0;
    const W = window.WebSocket;
    window.WebSocket = new Proxy(W, { construct(T, a) { window.__socks++; return new T(...a); } });
  });
  const gets = [];
  const flushed = [];
  wp.on("request", r => {
    const m = /\/v1\/tasks\/(sp-[a-z]+)$/.exec(new URL(r.url()).pathname);
    if (m && r.method() === "GET") gets.push(m[1]);
    const fl = new RegExp("/v1/tasks/flush([0-9]+)$").exec(new URL(r.url()).pathname);
    if (fl) flushed.push(+fl[1]);
  });
  const was = mock.tasksMode;
  const live = id => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: true, worktree: "/tmp/sp/" + id });
  try {
    mock.wornTasks = [live("sp-a"), live("sp-b"), live("sp-c"), live("sp-d")];
    mock.tasksMode = "worn";
    await wp.clock.install();
    await wp.goto(base, { waitUntil: "domcontentloaded" });
    await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    await wp.click('.tab[data-view="terms"]');
    await wp.evaluate(async () => { await loadCards().catch(() => {}).then(renderTermList); });
    const row = id => wp.locator('#term-list .card.tab[data-id="' + id + '"]');
    await row("sp-a").waitFor({ timeout: slow(10000) });
    await fakePause(wp);
    let flushSeq = 0;
    const flush = async () => {
      const n = ++flushSeq;
      await wp.evaluate(n => { fetch("/v1/tasks/flush" + n).catch(() => {}); }, n);
      await until(() => flushed.includes(n), 5000, "the flush request " + n);
    };
    const idle = async ms => { await fakeTick(wp, ms); await flush(); };

    // Rest on a row: fetched once, after the dwell.
    await row("sp-a").hover();
    await idle(40);
    if (gets.length) fail("switchPrewarm: the card was fetched before the dwell was up (" + gets.join(",") + ").");
    await idle(250);
    await until(() => gets.length >= 1, 5000, "the rest on sp-a fetched");
    if (gets.join(",") !== "sp-a") fail("switchPrewarm: resting on a row did not fetch its card once (" + gets.join(",") + ").");

    // Resting on the same row again inside the fresh window does not fetch again.
    await wp.mouse.move(5, 5);
    await row("sp-a").hover();
    await idle(250);
    if (gets.length !== 1) fail("switchPrewarm: a second rest on a fresh row fetched again (" + gets.join(",") + ").");

    // A pointer that leaves before the dwell fetches nothing; a sweep warms nothing.
    await wp.mouse.move(5, 5);
    await wp.evaluate(() => {
      const el = id => document.querySelector('#term-list .card.tab[data-id="' + id + '"]');
      const fire = (type, target, related) => target.dispatchEvent(new PointerEvent(type, { bubbles: true, pointerType: "mouse", relatedTarget: related }));
      const b = el("sp-b"), c = el("sp-c");
      fire("pointerover", b, document.body);
      fire("pointerout", b, c);
      fire("pointerover", c, b);
      fire("pointerout", c, document.body);
    });
    await idle(300);
    if (gets.length !== 1) fail("switchPrewarm: leaving before the dwell still fetched (" + gets.join(",") + ").");

    // The peek popover that rests on a row reaches the documents line (mDocs.paintCard) on a desktop board, which
    // has no phone network module, without throwing.
    const painted = await wp.evaluate(async () => {
      let threw = "";
      try { await window.mDocs.paintCard(document.createElement("button"), "sp-a"); } catch (e) { threw = String(e); }
      return { threw, net: typeof window.mNet };
    });
    if (painted.threw || painted.net !== "undefined") fail("switchPrewarm: a desktop peek's documents line threw or the desktop grew a mNet (" + JSON.stringify(painted) + ").");

    // No socket from any of it.
    const socks = await wp.evaluate(() => window.__socks);
    if (socks) fail("switchPrewarm: hovering opened " + socks + " websocket(s); the socket must wait for the click.");

    // A touch pointer never prewarms.
    await wp.evaluate(() => {
      const el = document.querySelector('#term-list .card.tab[data-id="sp-d"]');
      el.dispatchEvent(new PointerEvent("pointerover", { bubbles: true, pointerType: "touch" }));
    });
    await idle(250);
    if (gets.includes("sp-d")) fail("switchPrewarm: a touch pointer prewarmed a card.");

    // The click takes the prewarmed answer: no second GET for sp-a, and it is handed over once.
    const before = gets.length;
    const used = await wp.evaluate(async () => {
      const p = takePrewarmed("sp-a");
      const again = takePrewarmed("sp-a");
      return { had: !!p, again: !!again };
    });
    if (!used.had || used.again) fail("switchPrewarm: the prewarmed card was not handed over exactly once " + JSON.stringify(used));
    if (gets.length !== before) fail("switchPrewarm: taking the prewarm fetched again.");

    // A real click through attachTask: a prewarm under 3s old is used, so the card is fetched exactly once; one older
    // than that is not, so the click fetches again and the card has been fetched twice.
    const getsOf = id => gets.filter(g => g === id).length;
    await wp.mouse.move(5, 5);
    await row("sp-b").hover();
    await idle(250);
    await until(() => getsOf("sp-b") >= 1, 5000, "the rest on sp-b fetched");
    if (getsOf("sp-b") !== 1) fail("switchPrewarm: resting on sp-b did not fetch it once (" + getsOf("sp-b") + ").");
    await wp.evaluate(() => attachTask("sp-b"));
    await idle(200);
    if (getsOf("sp-b") !== 1) fail("switchPrewarm: a click right after the rest fetched sp-b again (" + getsOf("sp-b") + " GETs, one expected).");
    const path = await wp.evaluate(() => (window.__switchMarks.find(m => m[0].startsWith("card:")) || [""])[0]);
    if (path !== "card:list+prewarm") fail("switchPrewarm: the click after a rest took the path " + path + ", not the card from the list with the prewarmed read.");
    await wp.mouse.move(5, 5);
    await row("sp-c").hover();
    await idle(250);
    await until(() => getsOf("sp-c") >= 1, 5000, "the rest on sp-c fetched");
    await idle(3100);
    await wp.evaluate(() => attachTask("sp-c"));
    await until(() => getsOf("sp-c") >= 2, 5000, "the stale click fetched sp-c again");
    await idle(200);
    if (getsOf("sp-c") !== 2) fail("switchPrewarm: a click after the prewarm went stale did not fetch again (" + getsOf("sp-c") + " GETs, two expected).");

    // The cap: more than PREWARM_MAX in flight are not started (the answers are held, so none finishes).
    await wp.route("**/v1/tasks/sp-*", () => {});
    const capFrom = gets.length;
    await wp.evaluate(() => { prewarmFlying = 0; prewarmed.clear(); for (const id of ["sp-a", "sp-b", "sp-c", "sp-d"]) prewarmCard(id); });
    await until(() => gets.length - capFrom >= 2, 5000, "two prewarms started");
    await idle(300);
    const flying = gets.length - capFrom;
    if (flying !== 2) fail("switchPrewarm: " + flying + " prewarms started at once, the cap is 2.");
    if (errors.length) fail("switchPrewarm: page errors " + errors.join("; "));
    if (!bad) console.log("switchPrewarm ok");
  } finally { mock.tasksMode = was; await ctx.close(); }
}

// A CLICK OPENS THE PANE AT ONCE from the card the board's list already holds, and the read of the card that follows
// only refreshes it. With the read held: the pane is up (termTask, a Terminal) before it answers. A late answer that
// differs updates the name without a new Terminal. A late answer after a switch is ignored. A failed read leaves the
// pane open. A card the list does not hold waits for the read, as before.
async function attachAtOnceSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const wp = await ctx.newPage();
  const errors = [];
  wp.on("pageerror", e => errors.push(String(e)));
  const was = mock.tasksMode;
  const live = (id, extra) => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: true,
    worktree: "/tmp/ao/" + id }, extra || {});
  const held = {};
  try {
    mock.wornTasks = [live("ao-a"), live("ao-b"), live("ao-c")];
    mock.tasksMode = "worn";
    await wp.route("**/v1/tasks/ao-*", route => {
      const id = new URL(route.request().url()).pathname.split("/").pop();
      if (route.request().method() !== "GET" || id === "ao-zz-nolist" && false) return route.fallback();
      (held[id] = held[id] || []).push(route);
    });
    const answer = (id, how) => {
      const r = (held[id] || []).shift();
      if (!r) throw new Error("no held read for " + id);
      return how === "fail" ? r.fulfill({ status: 500, body: "boom" })
        : r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(live(id, how || {})) });
    };
    await wp.goto(base, { waitUntil: "domcontentloaded" });
    await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    await wp.click('.tab[data-view="terms"]');
    await wp.evaluate(async () => { await loadCards().catch(() => {}).then(renderTermList); });
    const state = () => wp.evaluate(() => ({ task: termTask && termTask.id, hasTerm: !!term, title: document.getElementById("t-title").textContent,
      termId: term ? (window.__termSeen = window.__termSeen || new WeakMap(), 1) : 0 }));
    const idle = ms => wp.waitForTimeout(ms);

    // At once, with the read held.
    await wp.evaluate(() => { window.__t0 = term; attachTask("ao-a"); });
    await idle(150);
    let st = await state();
    if (st.task !== "ao-a" || !st.hasTerm) fail("attachAtOnce: with the read held the pane was not open (" + JSON.stringify(st) + ").");
    const before = st.title;
    // A late answer that differs: the name moves, the terminal object is the same one.
    await wp.evaluate(() => { window.__termThen = term; });
    await answer("ao-a", { display_title: "renamed late", worktree: "/tmp/ao/renamed-late" });
    await idle(150);
    st = await state();
    const same = await wp.evaluate(() => window.__termThen === term);
    if (!same) fail("attachAtOnce: the late answer rebuilt the terminal.");
    if (st.title === before || !/renamed/.test(st.title + (await wp.evaluate(() => termTask.display_title)))) {
      fail("attachAtOnce: the late answer did not update the name (" + before + " -> " + st.title + ").");
    }

    // A late answer after a switch is ignored.
    await wp.evaluate(() => attachTask("ao-b"));
    await idle(100);
    await wp.evaluate(() => attachTask("ao-c"));
    await idle(100);
    await answer("ao-b", { display_title: "STALE", worktree: "/tmp/ao/STALE" });
    await idle(150);
    const afterSwitch = await wp.evaluate(() => ({ task: termTask && termTask.id, title: document.getElementById("t-title").textContent,
      stale: termTask && /STALE/.test(termTask.display_title + termTask.worktree) }));
    if (afterSwitch.task !== "ao-c" || afterSwitch.stale || /STALE/.test(afterSwitch.title)) {
      fail("attachAtOnce: a late answer for a card that was switched away from was applied (" + JSON.stringify(afterSwitch) + ").");
    }

    // A failed read leaves the pane open.
    await answer("ao-c", "fail");
    await idle(200);
    st = await state();
    if (st.task !== "ao-c" || !st.hasTerm) fail("attachAtOnce: a failed read closed the pane (" + JSON.stringify(st) + ").");

    // A card the list does not hold waits for the read.
    await wp.evaluate(() => { window.__nolist = attachTask("ao-nolist"); });
    await idle(200);
    st = await state();
    if (st.task === "ao-nolist") fail("attachAtOnce: a card not in the list opened before its read answered.");
    // A late read does not repaint a pane that already says it exited.
    await wp.evaluate(() => attachTask("ao-b"));
    await idle(150);
    await wp.evaluate(() => markTermDead());
    await answer("ao-b", { status: "dead", pid: 0, display_title: "row ao-b" });
    await idle(150);
    const dead = await wp.evaluate(() => ({ title: document.getElementById("t-title").textContent,
      chips: document.getElementById("t-chips").textContent, cls: document.getElementById("term-pane").className }));
    if (!/\(exited\)/.test(dead.title) || !/exited/.test(dead.chips) || !/dead/.test(dead.cls)) {
      fail("attachAtOnce: a late read repainted a dead pane (" + JSON.stringify(dead) + ").");
    }
    if (errors.length) fail("attachAtOnce: page errors " + errors.join("; "));
    if (!bad) console.log("attachAtOnce ok");
  } finally { mock.tasksMode = was; await ctx.close(); }
}

// AN OPEN FILE BELONGS TO ITS CARD. Opened on A, hidden on B (whose terminal shows), back on A with the edited text
// and scroll, closed on A only. And the editor reaches down to the footer hint line at two window heights.
// `FILEVIEW_SHOTS=dir` also writes the pictures for the item file.
async function fileViewSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const wp = await ctx.newPage();
  const errors = [];
  wp.on("pageerror", e => errors.push(String(e)));
  const was = mock.tasksMode;
  const live = (id) => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: true,
    worktree: "/tmp/fv/" + id });
  const body = Array.from({ length: 200 }, (_, i) => "line " + i).join("\n");
  const shot = async name => {
    if (process.env.FILEVIEW_SHOTS) await wp.screenshot({ path: process.env.FILEVIEW_SHOTS + "/" + name + ".png" });
  };
  try {
    mock.wornTasks = [live("fv-a"), live("fv-b")];
    mock.tasksMode = "worn";
    await wp.route(/\/v1\/tasks\/fv-[ab]\/files\/text/, route => route.fulfill({ status: 200, contentType: "application/json",
      body: JSON.stringify({ path: "notes/x.md", text: body, hash: "h1", eol: "\n" }) }));
    await wp.route(/\/v1\/tasks\/fv-[ab]\/files(\?|$)/, route => route.fulfill({ status: 200, contentType: "application/json",
      body: JSON.stringify({ path: "notes", entries: [] }) }));
    await wp.goto(base, { waitUntil: "domcontentloaded" });
    await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    await wp.click('.tab[data-view="terms"]');
    await wp.evaluate(async () => { await loadCards().catch(() => {}).then(renderTermList); });
    const idle = ms => wp.waitForTimeout(ms);
    const st = () => wp.evaluate(() => ({
      task: termTask && termTask.id,
      edit: !document.getElementById("t-edit").hidden,
      drawer: !document.getElementById("t-files-panel").hidden,
      screen: getComputedStyle(document.getElementById("t-screen")).display !== "none",
      text: document.getElementById("t-edit-text").value.slice(0, 12),
      top: document.getElementById("t-edit-text").scrollTop,
      state: document.getElementById("t-edit-state").textContent }));

    await wp.evaluate(() => attachTask("fv-a"));
    await idle(300);
    await wp.evaluate(() => openFromTerminal("fv-a", { rel: "notes/x.md", dir: false }));
    await idle(300);
    await wp.evaluate(() => {
      const b = document.getElementById("t-edit-text");
      b.value = "EDITED\n" + b.value; b.dispatchEvent(new Event("input")); b.scrollTop = 300;
    });
    let s = await st();
    if (!s.edit || s.task !== "fv-a" || s.state !== "not saved") fail("fileView: the file did not open on A: " + JSON.stringify(s));
    const top = s.top;
    if (top < 100) fail("fileView: the editor did not scroll, so the scroll check proves nothing: " + top);

    // Both heights: the editor's bottom edge meets the footer hint line.
    for (const h of [900, 620]) {
      await wp.setViewportSize({ width: 1400, height: h });
      await idle(250);
      const gap = await wp.evaluate(() => {
        const e = document.getElementById("t-edit-text").getBoundingClientRect();
        const f = document.querySelector(".term-help").getBoundingClientRect();
        const chain = [];
        for (let n = document.getElementById("t-edit-text"); n && n !== document.body; n = n.parentElement) {
          chain.push((n.id || n.className || n.tagName) + ":" + Math.round(n.getBoundingClientRect().height) +
            ":" + getComputedStyle(n).display);
        }
        chain.push("siblings of the panel: " + [...document.getElementById("term-pane").children].map(c =>
          (c.id || c.className) + ":" + Math.round(c.getBoundingClientRect().height) + ":" + getComputedStyle(c).flexGrow).join(" "));
        return { gap: f.top - e.bottom, h: e.height, scrolls: document.getElementById("t-edit-text").scrollHeight > e.height, chain };
      });
      if (gap.gap > 24 || gap.gap < -2) fail("fileView: at " + h + "px the editor ends " + gap.gap + "px from the footer: " + JSON.stringify(gap));
      if (!gap.scrolls) fail("fileView: at " + h + "px the editor does not scroll inside itself.");
      await shot("after-" + h);
    }
    await wp.setViewportSize({ width: 1400, height: 900 });
    await idle(250);

    await wp.evaluate(() => attachTask("fv-b"));
    await idle(300);
    s = await st();
    await shot("away-on-b");
    if (s.task !== "fv-b" || s.edit || s.drawer || !s.screen) fail("fileView: B shows A's file or lost its terminal: " + JSON.stringify(s));

    await wp.evaluate(() => attachTask("fv-a"));
    await idle(300);
    s = await st();
    await shot("back-on-a");
    if (s.task !== "fv-a" || !s.edit || !s.text.startsWith("EDITED") || s.state !== "not saved" || Math.abs(s.top - top) > 2) {
      fail("fileView: A did not get its file back as left (scroll " + top + "): " + JSON.stringify(s));
    }

    // Closed on A is closed for A only: B still has the file it had, which is none.
    await wp.evaluate(() => closeEditor());
    await wp.evaluate(() => attachTask("fv-b"));
    await idle(300);
    await wp.evaluate(() => attachTask("fv-a"));
    await idle(300);
    s = await st();
    if (s.edit || !s.screen) fail("fileView: a closed file came back on A: " + JSON.stringify(s));

    // A card that goes away drops its file.
    await wp.evaluate(() => openFromTerminal("fv-a", { rel: "notes/x.md", dir: false }));
    await idle(300);
    await wp.evaluate(() => attachTask("fv-b"));
    await idle(300);
    const held = await wp.evaluate(() => fileViews.has("fv-a"));
    if (!held) fail("fileView: the file was not held while away.");
    await wp.evaluate(() => fileViewPrune([{ id: "fv-b", supervised: true }]));
    if (await wp.evaluate(() => fileViews.has("fv-a"))) fail("fileView: a card that went away kept its file.");
    if (errors.length) fail("fileView: page errors " + errors.join("; "));
    if (!bad) console.log("fileView ok");
  } finally { mock.tasksMode = was; await ctx.close(); }
}

// TERMINALS ARE KEPT ALIVE when you switch away. Switching back shows the same terminal with no new socket and no
// replay; a hidden terminal takes frames into its own screen and touches nothing of the pane showing (title, focus,
// size, the ready/seen/scroll helpers); a hidden terminal never sends a resize; the least recently used unpinned ones
// are let go past the setting and pinned ones stay; one let go attaches normally; a close in the background drops it.
// ── pinning is immediate ──────────────────────────────────────────────────
// bug-pin-slow-terminals-tab: the star and the pinned bucket change in the frame of the click, with the PATCH held for
// two seconds, and a refused PATCH puts the star back.
async function pinNowSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const wp = await ctx.newPage();
  const errors = [];
  wp.on("pageerror", e => errors.push(String(e)));
  const was = mock.tasksMode;
  const row = id => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: false,
    worktree: "/tmp/pn/" + id });
  try {
    mock.wornTasks = [row("pn-a"), row("pn-b")];
    mock.tasksMode = "worn";
    let mode = "slow", patches = 0;
    await wp.route(/\/v1\/tasks\/pn-[ab]$/, async route => {
      if (route.request().method() !== "PATCH") return route.continue();
      patches++;
      if (mode !== "fail") { const r = mock.wornTasks.find(x => route.request().url().endsWith("/" + x.id)); if (r) r.pinned = !!JSON.parse(route.request().postData() || "{}").pinned; }
      if (mode === "fail") { await new Promise(r => setTimeout(r, 400)); return route.fulfill({ status: 500, contentType: "application/json", body: JSON.stringify({ error: "no" }) }); }
      await new Promise(r => setTimeout(r, 2000));
      return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(row("pn-a")) });
    });
    await wp.goto(base, { waitUntil: "domcontentloaded" });
    await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    await wp.click('.tab[data-view="terms"]');
    await wp.evaluate(async () => { await loadCards().catch(() => {}).then(renderTermList); });
    const star = id => wp.evaluate(i => { const r = document.querySelector('#term-list .card.tab[data-id="' + i + '"]');
      const s = r && r.querySelector(".pin"); return s ? s.classList.contains("on") : null; }, id);
    if (await star("pn-a") !== false) fail("pinNow: the row did not start with an unpinned star (" + await star("pn-a") + ").");
    // Click, then read the star after two animation frames, with the PATCH still held.
    const t0 = Date.now();
    await wp.evaluate(() => document.querySelector('#term-list .card.tab[data-id="pn-a"] .pin').click());
    const waitStar = async (id, want) => { const end = Date.now() + 1500; while (Date.now() < end && await star(id) !== want) await wp.waitForTimeout(10); };
    await waitStar("pn-a", true);
    const took = Date.now() - t0;
    if (await star("pn-a") !== true) fail("pinNow: the star did not turn on within a frame of the click.");
    if (took > 1500) fail("pinNow: the repaint waited " + took + "ms, behind the PATCH.");
    await wp.waitForTimeout(2300);
    // Refused: the star goes on, then back.
    mode = "fail";
    await wp.evaluate(() => document.querySelector('#term-list .card.tab[data-id="pn-b"] .pin').click());
    await waitStar("pn-b", true);
    if (await star("pn-b") !== true) fail("pinNow: a refused pin was not shown first.");
    for (let i = 0; i < 30 && await star("pn-b") !== false; i++) await wp.waitForTimeout(100);
    if (await star("pn-b") !== false) fail("pinNow: a refused PATCH did not put the star back.");
    if (patches < 2) fail("pinNow: expected two PATCHes, saw " + patches + ".");
    if (errors.length) fail("pinNow: page errors: " + errors.join("; "));
  } finally { mock.tasksMode = was; await ctx.close(); }
}

async function keepAliveSection(browser, base) {
  const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
  const wp = await ctx.newPage();
  const errors = [];
  wp.on("pageerror", e => errors.push(String(e)));
  await wp.addInitScript(() => {
    window.__ka = { socks: [] };
    const Real = window.WebSocket;
    window.WebSocket = function (url, protocols) {
      if (!/\/attach(\?|$)/.test(url)) return new Real(url, protocols);
      const id = /\/tasks\/([^/]+)\/attach/.exec(url)[1];
      const s = { url, id, readyState: 0, binaryType: "arraybuffer", onopen: null, onclose: null, onmessage: null,
        onerror: null, sent: [], send(m) { this.sent.push(m); }, close() { this.readyState = 3; } };
      window.__ka.socks.push(s);
      setTimeout(() => {
        s.readyState = 1;
        if (s.onopen) s.onopen({});
        if (s.onmessage) s.onmessage({ data: new TextEncoder().encode("hist-" + id + "\r\n").buffer });
      }, 0);
      return s;
    };
    Object.assign(window.WebSocket, { CONNECTING: 0, OPEN: 1, CLOSING: 2, CLOSED: 3 });
  });
  const was = mock.tasksMode;
  const live = (id, extra) => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: false,
    worktree: "/tmp/ka/" + id }, extra || {});
  try {
    mock.wornTasks = [live("ka-a"), live("ka-b"), live("ka-c"), live("ka-d"), live("ka-e"), live("ka-p", { pinned: true })];
    mock.tasksMode = "worn";
    await wp.goto(base, { waitUntil: "domcontentloaded" });
    await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
    await wp.click('.tab[data-view="terms"]');
    await wp.evaluate(async () => { localStorage.setItem("atrium.termKeep", "8"); await loadCards().catch(() => {}).then(renderTermList); });
    const idle = ms => wp.waitForTimeout(ms);
    const text = (expr) => wp.evaluate(e => { const t = eval(e); if (!t) return null; const b = t.buffer.active; const o = [];
      for (let i = 0; i < b.length; i++) { const l = b.getLine(i); if (l) o.push(l.translateToString(true)); } return o.join("\n"); }, expr);
    const socksFor = id => wp.evaluate(i => window.__ka.socks.filter(s => s.id === i).length, id);
    const attach = async id => { await wp.evaluate(i => attachTask(i), id); await idle(150); };
    const resizes = id => wp.evaluate(i => window.__ka.socks.filter(s => s.id === i)
      .reduce((n, s) => n + s.sent.filter(m => /"t":"resize"/.test(m)).length, 0), id);

    // Open a, then b: a is kept, its socket still open, its element hidden.
    await attach("ka-a");
    for (let i = 0; i < 40 && !/hist-ka-a/.test(await text("term") || ""); i++) await idle(150);
    if (!/hist-ka-a/.test(await text("term") || "")) fail("keepAlive: the first attach did not replay into the terminal.");
    await wp.evaluate(async () => {
      window.__termA = term;
      await new Promise(r => term.write(Array.from({ length: 150 }, (_, i) => "scroll line " + i).join("\r\n") + "\r\n", r));
    });
    const resizesA = await resizes("ka-a");
    await attach("ka-b");
    const kept = await wp.evaluate(() => { const k = keptTerms.get("ka-a"); return k && { open: k.sock.readyState, hidden: k.el.style.display, live: !!term, task: termTask.id }; });
    if (!kept || kept.open !== 1 || kept.hidden !== "none" || kept.task !== "ka-b") fail("keepAlive: switching away did not keep ka-a hidden and open (" + JSON.stringify(kept) + ").");

    // A frame for the hidden terminal lands in it and touches nothing of the showing pane.
    // The last attach's socket opens a moment after it, and that open clears the wait line, so let it land before counting.
    await idle(500);
    const before = await wp.evaluate(() => {
      window.__calls = {};
      for (const n of ["feedReadyQuiet", "noteScrollAct", "pasteSawOutput", "focusTerm", "sendResize", "termWait", "markTermDead", "toast", "paintTermTitle"]) {
        const real = window[n]; window[n] = function () { window.__calls[n] = (window.__calls[n] || 0) + 1; return real.apply(this, arguments); };
      }
      const b = window.__ka.socks.find(s => s.id === "ka-b");
      return { title: document.getElementById("t-title").textContent, active: document.activeElement && document.activeElement.className,
        sentB: b.sent.length, textB: null };
    });
    const textBBefore = await text("term");
    await wp.evaluate(() => {
      const a = window.__ka.socks.find(s => s.id === "ka-a");
      a.onmessage({ data: new TextEncoder().encode("A-live\r\n").buffer });
      a.onmessage({ data: JSON.stringify({ t: "size", cols: 150, rows: 40 }) });
      a.onmessage({ data: JSON.stringify({ t: "in-refused", why: "x" }) });
      a.onmessage({ data: "A-plain-text\r\n" });
    });
    await idle(200);
    const after = await wp.evaluate(() => {
      const b = window.__ka.socks.find(s => s.id === "ka-b");
      return { title: document.getElementById("t-title").textContent, active: document.activeElement && document.activeElement.className,
        sentB: b.sent.length, calls: window.__calls, termTask: termTask.id, keptCols: keptTerms.get("ka-a").term.cols };
    });
    if (after.title !== before.title || after.active !== before.active || after.sentB !== before.sentB || after.termTask !== "ka-b") {
      fail("keepAlive: a frame for the hidden terminal touched the showing pane " + JSON.stringify({ before, after }));
    }
    if (Object.keys(after.calls).length) fail("keepAlive: a hidden terminal's frame reached the pane's helpers " + JSON.stringify(after.calls));
    if (await text("term") !== textBBefore) fail("keepAlive: a frame for the hidden terminal was written into the showing terminal.");
    const keptText = await text("keptTerms.get('ka-a').term");
    if (!/A-live/.test(keptText)) fail("keepAlive: the hidden terminal did not take its own output.");
    if (!/A-plain-text/.test(keptText)) fail("keepAlive: a non-JSON text frame for the hidden terminal was lost.");
    if (after.keptCols < 150) fail("keepAlive: the hidden terminal did not follow the pty's size (" + after.keptCols + " cols).");

    // A hidden terminal's answers to xterm's queries go back on its OWN socket, never into the showing session.
    const sentOf = id => wp.evaluate(i => window.__ka.socks.filter(s => s.id === i).flatMap(s => s.sent.filter(m => /"t":"in"/.test(m))), id);
    const aInBefore = (await sentOf("ka-a")).length, bInBefore = (await sentOf("ka-b")).length;
    await wp.evaluate(() => new Promise(r => keptTerms.get("ka-a").term.write("\x1b[c\x1b[6n", r)));
    await idle(200);
    const aIn = (await sentOf("ka-a")).slice(aInBefore).join("");
    if (!/1;2c/.test(aIn) || !/R/.test(aIn)) fail("keepAlive: a hidden terminal's query answers did not reach its own runner (" + aIn + ").");
    if ((await sentOf("ka-b")).length !== bInBefore) fail("keepAlive: a hidden terminal's query answers were typed into the showing session.");

    // A hidden terminal sends no resize, even when the window changes size.
    await wp.setViewportSize({ width: 1100, height: 760 });
    await idle(400);
    if (await resizes("ka-a") !== resizesA) fail("keepAlive: a hidden terminal sent a resize.");

    // Back: same terminal object, no new socket, no replay, shown in the same task as the click.
    const back = await wp.evaluate(() => {
      const t0 = window.__termA, n0 = window.__ka.socks.filter(s => s.id === "ka-a").length;
      attachTask("ka-a");
      return { same: term === t0, task: termTask && termTask.id, shown: term && term.element.style.display !== "none",
        n0, n1: window.__ka.socks.filter(s => s.id === "ka-a").length, hid: !!document.querySelector("#t-screen > [data-kept]") };
    });
    if (!back.same || back.task !== "ka-a" || !back.shown || back.n1 !== back.n0) {
      fail("keepAlive: switching back was not an instant show of the same terminal " + JSON.stringify(back));
    }
    await idle(300);
    const t = await text("term");
    if ((t.match(/hist-ka-a/g) || []).length !== 1 || !/A-live/.test(t)) fail("keepAlive: the terminal shown again was replayed or lost its output.");
    if (await socksFor("ka-a") !== 1) fail("keepAlive: switching back dialled a new socket.");
    // The window shrank while it was hidden: it fitted once on return and told the room.
    if (await resizes("ka-a") <= resizesA) fail("keepAlive: a pane whose box changed while hidden did not refit and tell the room on return.");

    // A runner that asked for focus reports is told it lost the focus when its terminal is hidden.
    await wp.evaluate(() => new Promise(r => term.write("\x1b[?1004h", r)));
    const focusBefore = (await sentOf("ka-a")).length;
    await attach("ka-b");
    if (!(await sentOf("ka-a")).slice(focusBefore).some(m => m.includes("\\u001b[O"))) fail("keepAlive: hiding a terminal with focus reports on did not send it the focus-out.");
    await attach("ka-a");

    // The scroll position is kept across a hide and show (the box did not move, so no refit).
    await attach("ka-c");
    const vy = await wp.evaluate(async () => {
      await new Promise(r => term.write(Array.from({ length: 150 }, (_, i) => "scroll line " + i).join("\r\n") + "\r\n", r));
      term.scrollToLine(20);
      return term.buffer.active.viewportY;
    });
    await attach("ka-d");
    await attach("ka-c");

    const scrolled = await wp.evaluate(() => ({ vy: term.buffer.active.viewportY, px: term.element.querySelector(".xterm-viewport").scrollTop }));
    if (scrolled.vy !== vy || scrolled.px <= 0) fail("keepAlive: the scroll position was not kept across the hide and show " + JSON.stringify({ vy, scrolled }));

    // Bounds: N=2 keeps the two most recent unpinned, and a pinned one stays whatever the count.
    const capped = await wp.evaluate(() => { setTermKeep("atrium.termKeep", 16); return termKeepN(); });
    if (capped !== 12) fail("keepAlive: the setting was not held to the hard ceiling of 12 (" + capped + ").");
    await wp.evaluate(() => setTermKeep("atrium.termKeep", 2));
    await attach("ka-p");
    for (const id of ["ka-b", "ka-c", "ka-d", "ka-e"]) await attach(id);
    const keys = await wp.evaluate(() => Array.from(keptTerms.keys()).sort().join(","));
    if (keys !== "ka-d,ka-p,ka-c".split(",").sort().join(",")) fail("keepAlive: with N=2 and a pinned card the kept set was " + keys + ", not the two latest plus the pinned one.");
    // One let go is closed, and attaching it again is an ordinary attach with a new socket.
    const closedA = await wp.evaluate(() => window.__ka.socks.filter(s => s.id === "ka-a").every(s => s.readyState === 3));
    if (!closedA) fail("keepAlive: an evicted terminal's socket was left open.");
    const nBefore = await socksFor("ka-a");
    await attach("ka-a");
    if (await socksFor("ka-a") !== nBefore + 1) fail("keepAlive: an evicted card did not attach with a new socket.");
    if (!/hist-ka-a/.test(await text("term"))) fail("keepAlive: an evicted card did not replay on re-attach.");

    // A close in the background drops the slot and leaves the showing pane alone.
    const titleNow = await wp.evaluate(() => document.getElementById("t-title").textContent);
    await wp.evaluate(() => { const s = window.__ka.socks.filter(x => x.id === "ka-p" && x.readyState === 1).pop(); s.readyState = 3; s.onclose({ code: 1006, reason: "" }); });
    await idle(200);
    const afterClose = await wp.evaluate(() => ({ has: keptTerms.has("ka-p"), title: document.getElementById("t-title").textContent, task: termTask && termTask.id }));
    if (afterClose.has || afterClose.title !== titleNow || afterClose.task !== "ka-a") fail("keepAlive: a background close was not contained " + JSON.stringify(afterClose));

    // Off: nothing is kept.
    await wp.evaluate(() => setTermKeep("atrium.termKeep", 0));
    await attach("ka-b");
    const none = await wp.evaluate(() => keptTerms.size);
    if (none !== 0) fail("keepAlive: with the setting at 0 " + none + " terminals were kept.");
    if (errors.length) fail("keepAlive: page errors " + errors.join("; "));
    if (!bad) console.log("keepAlive ok");
  } finally { mock.tasksMode = was; await ctx.close(); }
}

// NOT IN THE DEFAULT RUN: `REPLAY=/path/replay.json HEADLESS_ONLY=switchBackCost node scripts/test-board-headless.js`.
// What switching away and back costs with terminals kept (atrium.termKeep=8) and without (0), with the room's real
// replay played into the socket (a JSON list of {t, bin, b64} frames, captured from a live attach). Prints a table.
async function switchBackCostSection(browser, base) {
  if (!process.env.REPLAY) return;
  const frames = JSON.parse(fs.readFileSync(process.env.REPLAY, "utf8"));
  const was = mock.tasksMode;
  const live = id => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: false, worktree: "/tmp/sb/" + id });
  try {
    mock.wornTasks = [live("sb-a"), live("sb-b")];
    mock.tasksMode = "worn";
    const rows = [];
    for (const keep of ["0", "8"]) {
      const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
      const wp = await ctx.newPage();
      await wp.addInitScript(([frames, keep]) => {
        localStorage.setItem("atrium.termKeep", keep);
        const Real = window.WebSocket;
        window.__socks = 0;
        window.WebSocket = function (url, protocols) {
          if (!/\/attach(\?|$)/.test(url)) return new Real(url, protocols);
          window.__socks++;
          const id = /\/tasks\/([^/]+)\/attach/.exec(url)[1];
          const s = { url, id, readyState: 0, binaryType: "arraybuffer", onopen: null, onclose: null, onmessage: null, onerror: null,
            send() {}, close() { this.readyState = 3; } };
          setTimeout(() => {
            s.readyState = 1; if (s.onopen) s.onopen({});
            if (id !== "sb-a") return;
            for (const f of frames) {
              const bytes = Uint8Array.from(atob(f.b64), c => c.charCodeAt(0));
              if (s.onmessage) s.onmessage({ data: f.bin ? bytes.buffer : new TextDecoder().decode(bytes) });
            }
          }, 0);
          return s;
        };
        Object.assign(window.WebSocket, { CONNECTING: 0, OPEN: 1, CLOSING: 2, CLOSED: 3 });
      }, [frames, keep]);
      await wp.goto(base, { waitUntil: "domcontentloaded" });
      await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
      await wp.click('.tab[data-view="terms"]');
      await wp.evaluate(async () => { await loadCards().catch(() => {}).then(renderTermList); });
      const sw = id => wp.evaluate(async id => {
        const t0 = performance.now(); let parsed = 0, hooked = null; const n = window.__socks;
        attachTask(id);
        const sync = performance.now() - t0;
        const hook = setInterval(() => { if (term && term !== hooked) { hooked = term; term.onWriteParsed(() => { parsed = performance.now(); }); } }, 1);
        await new Promise(r => requestAnimationFrame(() => requestAnimationFrame(r)));
        const frames2 = performance.now() - t0;
        await new Promise(r => setTimeout(r, 900));
        clearInterval(hook);
        return { sync, frames2, parsed: parsed ? parsed - t0 : 0, newSocks: window.__socks - n, lines: term.buffer.active.length,
          marks: (window.__switchMarks || []).map(m => m[0] + "=" + m[1].toFixed(1)).join(" ") };
      }, id);
      await sw("sb-a"); await wp.waitForTimeout(500);
      await sw("sb-b"); await wp.waitForTimeout(500);
      rows.push({ keep, back: await sw("sb-a") });
      await ctx.close();
    }
    console.log("switch back to a card with a " + Math.round(frames.reduce((n, f) => n + f.b64.length * 0.75, 0) / 1024) + " KB replay (ms from attachTask):");
    for (const r of rows) console.log("  kept=" + r.keep + "  call returns " + r.back.sync.toFixed(1) + "  two frames " + r.back.frames2.toFixed(1) +
      "  last parsed " + (r.back.parsed ? r.back.parsed.toFixed(0) : "-") + "  new sockets " + r.back.newSocks + "  lines " + r.back.lines + "\n    " + r.back.marks);
  } finally { mock.tasksMode = was; }
}

// NOT IN THE DEFAULT RUN: `REPLAY=/path/replay.json HEADLESS_ONLY=keepMemory node scripts/test-board-headless.js`.
// The JS heap with 1, then 9 terminals each given the room's real replay, kept (atrium.termKeep=8, hidden history cut
// to atrium.termKeepLines) and not kept, after a garbage collection. Prints the cost per kept terminal.
async function keepMemorySection(browser, base) {
  if (!process.env.REPLAY) return;
  const frames = JSON.parse(fs.readFileSync(process.env.REPLAY, "utf8"));
  const kb = Math.round(frames.reduce((n, f) => n + f.b64.length * 0.75, 0) / 1024);
  const was = mock.tasksMode;
  const live = id => Object.assign({}, T1, { id, display_title: "row " + id, supervised: true, pinned: false, worktree: "/tmp/km/" + id });
  const ids = Array.from({ length: 9 }, (_, i) => "km-" + i);
  try {
    mock.wornTasks = ids.map(live);
    mock.tasksMode = "worn";
    const out = [];
    for (const [keep, lines] of [["0", "5000"], ["8", "5000"], ["8", "20000"]]) {
      const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
      const wp = await ctx.newPage();
      const cdp = await ctx.newCDPSession(wp);
      await wp.addInitScript(([frames, keep, lines]) => {
        localStorage.setItem("atrium.termKeep", keep);
        localStorage.setItem("atrium.termKeepLines", lines);
        const Real = window.WebSocket;
        window.WebSocket = function (url, protocols) {
          if (!/\/attach(\?|$)/.test(url)) return new Real(url, protocols);
          const s = { url, readyState: 0, binaryType: "arraybuffer", onopen: null, onclose: null, onmessage: null, onerror: null, send() {}, close() { this.readyState = 3; } };
          setTimeout(() => {
            s.readyState = 1; if (s.onopen) s.onopen({});
            for (const f of frames) {
              const bytes = Uint8Array.from(atob(f.b64), c => c.charCodeAt(0));
              if (s.onmessage) s.onmessage({ data: f.bin ? bytes.buffer : new TextDecoder().decode(bytes) });
            }
          }, 0);
          return s;
        };
        Object.assign(window.WebSocket, { CONNECTING: 0, OPEN: 1, CLOSING: 2, CLOSED: 3 });
      }, [frames, keep, lines]);
      await wp.goto(base, { waitUntil: "domcontentloaded" });
      await wp.waitForSelector("#stack-list .stackrow", { timeout: slow(15000) });
      await wp.click('.tab[data-view="terms"]');
      await wp.evaluate(async () => { await loadCards().catch(() => {}).then(renderTermList); });
      // The renderer's resident memory as well as the JS heap: xterm keeps its cells in typed arrays, which the heap
      // number undercounts.
      const bs = await browser.newBrowserCDPSession();
      const heap = async () => {
        await cdp.send("HeapProfiler.collectGarbage"); await cdp.send("HeapProfiler.collectGarbage");
        await wp.waitForTimeout(500);
        const procs = (await bs.send("SystemInfo.getProcessInfo")).processInfo.filter(p => p.type === "renderer");
        const rss = Math.max(...procs.map(p => +require("child_process").execSync("ps -o rss= -p " + p.id).toString().trim() / 1024));
        return { heap: (await cdp.send("Runtime.getHeapUsage")).usedSize / 1048576, rss };
      };
      await wp.evaluate(id => attachTask(id), ids[0]);
      await wp.waitForTimeout(1500);
      const one = await heap();
      for (const id of ids.slice(1)) { await wp.evaluate(i => attachTask(i), id); await wp.waitForTimeout(1200); }
      const nine = await heap();
      const kept = await wp.evaluate(() => keptTerms.size);
      const histLines = await wp.evaluate(() => Array.from(keptTerms.values()).map(s => s.term.buffer.active.length));
      out.push({ keep, lines, one, nine, kept, histLines });
      await ctx.close();
    }
    console.log("heap after GC, replay " + kb + " KB per terminal:");
    for (const r of out) console.log("  kept=" + r.keep + " hidden-lines=" + r.lines + ": 1 terminal heap " + r.one.heap.toFixed(0) + " rss " + r.one.rss.toFixed(0) +
      " MB; 9 visited heap " + r.nine.heap.toFixed(0) + " rss " + r.nine.rss.toFixed(0) + " MB (" + r.kept + " kept hidden, lines each " + (r.histLines[0] || "-") +
      ")  per kept terminal heap " + (r.kept ? ((r.nine.heap - r.one.heap) / r.kept).toFixed(1) : "-") + " rss " + (r.kept ? ((r.nine.rss - r.one.rss) / r.kept).toFixed(1) : "-") + " MB");
  } finally { mock.tasksMode = was; }
}

// Change requests on the desktop board (js/changereq.js, the Requests view of the repos area), against a hub simulated by
// scripts/changereq-fixture.js in @fabric's stage 5 draft shape: the strip for requests into main, the ledger, a page with
// the Pushed line, the operator's three actions, the sha check and the server's 409 text, a read-only board, a branch the
// push log has never seen, an empty hub, an offline hub, an old hub, opening a request, the Ledger's branch rows, text-only
// titles, the swappable mock, the phone's width and 4.5:1 text on every skin.
async function crFixturePage(browser, base, o) {
  o = o || {};
  const fx = require("./hubrepos-fixture.js")(Date.now());
  const hub = require("./changereq-fixture.js")(Date.now());
  if (o.mutate) o.mutate(hub);
  const ctx = await browser.newContext({ viewport: { width: o.w || 2000, height: o.h || 1100 } });
  const errors = [];
  const p = await ctx.newPage();
  p.on("pageerror", e => errors.push(e.message));
  await p.route(/\/_hub\/git\/repos$/, r => r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ repos: fx.repos }) }));
  if (!o.noHub) await hub.route(p, { mode: o.mode || "ok" });
  await p.goto(base + "/" + (o.query || ""), { waitUntil: "domcontentloaded" });
  await p.waitForFunction(() => { const t = document.querySelector('.tab[data-view="hubrepos"]'); return t && !t.hidden; }, null, { timeout: slow(15000) });
  await p.evaluate(({ tasks, view }) => { lastTasks = tasks; localStorage.setItem("atrium.reposView", view); return switchView("hubrepos"); }, { tasks: fx.tasks, view: o.view || "requests" });
  await p.waitForFunction(() => document.querySelector("#hubrepos-list .cr-ledger, #hubrepos-list .cr-offline, #hubrepos-list .hr-hero, #hubrepos-list .hr-ledger"), null, { timeout: slow(10000) });
  // The requests are read once by the view and once more when the repos arrive; both are settled before a test touches the page.
  await p.waitForFunction(() => hubRepos.loaded && !hubRepos.inflight && !cr.inflight, null, { timeout: slow(8000) });
  await frames(p, 2);
  await p.waitForFunction(() => !cr.inflight, null, { timeout: slow(5000) });  return { ctx, p, errors, hub, fx };
}

async function changeReqSection(browser, base) {
  const wasHub = mock.hubMode; mock.hubMode = true;
  try {
    await crContrast(browser, base, "changeReq");
    await crShots(browser, base);
  } finally { mock.hubMode = wasHub; }
}

// 4.5:1 for the text a page draws, on every skin: each element is painted with its text transparent, the pixels under it are
// read from a screenshot, and the worst of them is compared with the text's own colour. Gradients and tints are what is really
// there, not a guess. `before(skin)` may put the page in the state to measure after the skin is set.
async function crInkCheck(p, skins, sels, width, before) {
  const bad = [];
  // A blanked element's children that set their own colour (a label, a <b>) stay drawn, and when the text wraps (a wider font)
  // the range's box reaches under them, so their ink reads as the background. Blank the whole subtree.
  await p.addStyleTag({ content: "[data-crk], [data-crk] * { color: transparent !important; }" });
    for (const skin of skins) {
      await p.evaluate(s => { if (s) document.documentElement.setAttribute("data-skin", s); else document.documentElement.removeAttribute("data-skin"); }, skin);
      if (before) await before(skin);
      await settleStyle(p);
      const passed = await crInkBatch(p, sels, width);
      // the batch's restore restarts colour transitions, and a miss read mid-transition is not a miss
      if (passed.size < sels.length) await settleStyle(p);
      for (const sel of sels) {
        if (passed.has(sel)) continue;
        let box = null, ratio = 99;
        // A repaint under the shot (an event, a late read) shows the text and reads as 1:1, so a miss is measured again before it counts.
        for (let tries = 0; tries < 3 && ratio < 4.5 || tries === 0; tries++) {
          ratio = 99;
          box = await p.evaluate(s => { const e = document.querySelector(s); if (!e) return null; e.scrollIntoView({ block: "center" }); const tn = [...e.childNodes].find(n => n.nodeType === 3 && n.textContent.trim()) || (e.firstElementChild && [...e.firstElementChild.childNodes].find(n => n.nodeType === 3 && n.textContent.trim())) || e;
          const rg = document.createRange(); rg.selectNodeContents(tn); const r = tn === e ? e.getBoundingClientRect() : rg.getBoundingClientRect(), col = getComputedStyle(tn === e ? e : tn.parentElement).color;
          const kill = (tn === e ? e : tn.parentElement); kill.dataset.crk = "1"; kill.style.transition = "none"; kill.style.color = "transparent"; return { x: r.x, y: r.y, w: r.width, h: r.height, c: col, dbg: process_dbg(kill) };
          function process_dbg(k) { const c = getComputedStyle(k); return c.backgroundColor + " " + c.backgroundImage.slice(0, 40); } }, sel);
          if (!box || box.w < 2 || box.h < 2) break;
          const png = await p.screenshot({ clip: { x: Math.max(0, box.x), y: Math.max(0, box.y), width: Math.min(box.w, width - Math.max(0, box.x)), height: box.h } });
          await p.evaluate(() => { document.querySelectorAll("[data-crk]").forEach(k => { k.style.color = ""; k.style.transition = ""; delete k.dataset.crk; }); });
          ratio = await p.evaluate(async ({ b64, col }) => {
            const img = new Image(); img.src = "data:image/png;base64," + b64; await img.decode();
            const cv = document.createElement("canvas"); cv.width = img.width; cv.height = img.height; const g = cv.getContext("2d"); g.drawImage(img, 0, 0);
            const d = g.getImageData(0, 0, cv.width, cv.height).data;
            const lin = v => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); };
            const L = (r, gg, b) => .2126 * lin(r) + .7152 * lin(gg) + .0722 * lin(b);
            let m = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?/.exec(col);
            if (!m) { const c = /color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)(?: \/ ([\d.]+))?\)/.exec(col); m = c && [c[0], c[1] * 255, c[2] * 255, c[3] * 255, c[4]]; }
            const a = m[4] === undefined ? 1 : +m[4];
            let worst = 99;
            for (let i = 0; i < d.length; i += 4 * 3) {
              const bg = [d[i], d[i + 1], d[i + 2]], fg = [0, 1, 2].map(k => +m[k + 1] * a + bg[k] * (1 - a));
              const l1 = L(...fg), l2 = L(...bg), r = (Math.max(l1, l2) + .05) / (Math.min(l1, l2) + .05);
              if (r < worst) worst = r;
            }
            return worst;
          }, { b64: png.toString("base64"), col: box.c });
        }
        if (!box) { bad.push(skin + " " + sel + " missing"); continue; }
        if (box.w < 2 || box.h < 2) continue;
        if (ratio < 4.5) bad.push(skin + " " + sel + " " + ratio.toFixed(2) + (process.env.CR_CONTRAST && !skin ? " color " + box.c + " bg " + box.dbg : ""));
      }
    }
  return bad;
}

// The fast pass of crInkCheck: every selector on screen is blanked at once and read from one shot. Only passes come back, so
// a selector off screen or under 4.5 is measured again on its own, the slow way, before it counts.
async function crInkBatch(p, sels, width) {
  const boxes = await p.evaluate(({ sels, width }) => sels.map(s => {
    const e = document.querySelector(s); if (!e) return null;
    const tn = [...e.childNodes].find(n => n.nodeType === 3 && n.textContent.trim()) || (e.firstElementChild && [...e.firstElementChild.childNodes].find(n => n.nodeType === 3 && n.textContent.trim())) || e;
    const rg = document.createRange(); rg.selectNodeContents(tn); const r = tn === e ? e.getBoundingClientRect() : rg.getBoundingClientRect();
    if (r.width < 2 || r.height < 2 || r.x < 0 || r.y < 0 || r.right > Math.min(width, innerWidth) || r.bottom > innerHeight) return null;
    const kill = tn === e ? e : tn.parentElement;
    return { s, x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), c: getComputedStyle(kill).color, kill };
  }).filter(Boolean).map(b => { b.kill.dataset.crk = "1"; b.kill.style.transition = "none"; b.kill.style.color = "transparent"; delete b.kill; return b; }), { sels, width });
  if (!boxes.length) return new Set();
  const png = await p.screenshot();
  await p.evaluate(() => { document.querySelectorAll("[data-crk]").forEach(k => { k.style.color = ""; k.style.transition = ""; delete k.dataset.crk; }); });
  const ok = await p.evaluate(async ({ b64, boxes }) => {
    const img = new Image(); img.src = "data:image/png;base64," + b64; await img.decode();
    const cv = document.createElement("canvas"); cv.width = img.width; cv.height = img.height; const g = cv.getContext("2d"); g.drawImage(img, 0, 0);
    const lin = v => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); };
    const L = (r, gg, b) => .2126 * lin(r) + .7152 * lin(gg) + .0722 * lin(b);
    return boxes.filter(box => {
      let m = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?/.exec(box.c);
      if (!m) { const c = /color\(srgb ([\d.]+) ([\d.]+) ([\d.]+)(?: \/ ([\d.]+))?\)/.exec(box.c); m = c && [c[0], c[1] * 255, c[2] * 255, c[3] * 255, c[4]]; }
      if (!m) return false;
      const a = m[4] === undefined ? 1 : +m[4], d = g.getImageData(box.x, box.y, box.w, box.h).data;
      for (let i = 0; i < d.length; i += 4 * 3) {
        const bg = [d[i], d[i + 1], d[i + 2]], fg = [0, 1, 2].map(k => +m[k + 1] * a + bg[k] * (1 - a));
        const l1 = L(...fg), l2 = L(...bg);
        if ((Math.max(l1, l2) + .05) / (Math.min(l1, l2) + .05) < 4.5) return false;
      }
      return true;
    }).map(b => b.s);
  }, { b64: png.toString("base64"), boxes });
  return new Set(ok);
}

async function crContrast(browser, base, tag) {
  const skins = [""].concat(((await (await fetch(base + "/css/themes.css")).text()).match(/:root\[data-skin="([a-z]+)"\]/g) || []).map(s => /"([a-z]+)"/.exec(s)[1]));
  const { ctx, p } = await crFixturePage(browser, base, { w: 1700, h: 1500 });
  const sels = [".cr-h2", ".cr-k", ".cr-hero h3", ".cr-hero .cr-quiet", ".cr-hero .cr-btn", ".cr-li.sel .cr-lt", ".cr-li.sel .cr-lm", ".cr-li .cr-needs", ".cr-seg button[aria-pressed=true]", ".cr-tg span", ".cr-crumb", ".cr-title",
    ".cr-detail .hr-badges .hr-state", ".cr-gate > b", ".cr-gate > span", ".cr-steps li", ".cr-field label", ".cr-btn.go", ".cr-hint", ".cr-panel .hr-h", ".cr-why", ".cr-line", ".cr-kv dt", ".cr-kv dd", ".cr-quiet", ".cr-tl .cr-tlt", ".cr-lane .cr-br", ".cr-end small", ".cr-hero .cr-br"];
  let bad;
  try { bad = await crInkCheck(p, skins, sels, 1700, () => p.fill("#cr-sha", "xyz")); } finally { await ctx.close(); }  if (process.env.CR_CONTRAST) console.log(bad.join("\n"));
  if (bad.length) fail(tag + ": text under 4.5:1 on " + bad.length + " pairs: " + bad.slice(0, 14).join("; "));
}

// Real-board shots for review: CR_SHOTS=/dir. Paper and dark, 2000 and 390, the list and the page.
async function crShots(browser, base) {
  const dir = process.env.CR_SHOTS;
  if (!dir) return;
  require("fs").mkdirSync(dir, { recursive: true });
  for (const w of [2000, 390]) for (const skin of ["paper", "dark"]) for (const st of ["full", "closed", "empty", "readonly"]) {
    const { ctx, p } = await crFixturePage(browser, base, { w, h: 900, mode: st === "empty" ? "empty" : st === "readonly" ? "readonly" : "ok" });
    try {
      await p.evaluate(s => { if (s === "paper") document.documentElement.setAttribute("data-skin", "paper"); else document.documentElement.removeAttribute("data-skin"); }, skin);
      if (st === "closed") { await p.click('.cr-seg [data-tab="closed"]'); await p.click('.cr-li[data-id="cr_6"]'); await p.waitForFunction(() => /Bump Go/.test(document.querySelector(".cr-title").textContent)); }
      if (st === "readonly") { await p.click('[data-cr="withdraw"]'); await p.waitForSelector(".cr-ro"); }
      await settleStyle(p);
      const h = await p.evaluate(() => { const l = document.getElementById("hubrepos-list"); return Math.ceil(l.scrollHeight + l.getBoundingClientRect().top + 24); });
      await p.setViewportSize({ width: w, height: Math.min(6000, Math.max(600, h)) });
      await settleStyle(p);
      await p.screenshot({ path: require("path").join(dir, "requests-" + st + "-" + w + "-" + skin + ".png") });
    } finally { await ctx.close(); }
  }
}

// Change requests on the phone (m/js/changereq.js): the "requests" door in the header, the list and a request's page as two
// screens of one sheet with history for back, the same operator actions and sha check as the desktop, a read-only board, an
// empty, offline and old hub, opening a request, text-only titles, and the changes sheet's Pushed line (the hub's push log,
// with the hub not answering and a branch it has never seen). Against scripts/changereq-fixture.js.
async function mChangeReqPage(browser, st, vp, o) {
  o = o || {};
  const hub = require("./changereq-fixture.js")(Date.now());
  if (o.mutate) o.mutate(hub);
  const ctx = await browser.newContext({ viewport: vp, hasTouch: true, isMobile: true, deviceScaleFactor: 1 });
  const errors = [];
  const p = await ctx.newPage();
  p.on("pageerror", e => errors.push(String(e)));
  const fx = require("./hubrepos-fixture.js")(Date.now());
  await p.route(/\/_hub\/git\/repos$/, r => r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ repos: fx.repos }) }));
  await hub.route(p, { mode: o.mode || "ok" });
  // Routes are matched newest first, so the push log's own answer, when a test gives one, goes on after the hub's.
  if (o.pushed) await p.route(/\/_hub\/git\/pushed/, r => o.pushed(r));
  await p.goto(st.url + "/m/" + (o.query || ""), { waitUntil: "domcontentloaded" });
  await p.waitForSelector("#m-seg-all", { timeout: slow(10000) });
  await p.waitForFunction(() => window.mRequests && window.mRequests.state && (window.mRequests.state.loaded || window.mRequests.state.note), null, { timeout: slow(8000) });
  await p.waitForTimeout(150);
  return { ctx, p, errors, hub };
}

async function mChangeReqSection(browser) {
  const tag0 = "mChangeReq";
  const st = mServer({});
  st.tasks = [mCard("cr-1", { alias: "coder", display_title: "coder", runner: "claude", worktree: "/w/card", status: "needs-input", waiting_since: mIso(2 * M_MIN), seen: { turn_ended_at: mIso(20 * M_MIN) } })];
  st.replies["cr-1"] = { source: "transcript", replies: [{ at: new Date(Date.now() - 600000).toISOString(), text: "done", edited: 1 }] };
  await st.open();
  try {
    for (const vp of M_VIEWS) {
      const tag = tag0 + " " + vp.width + ": ";
      let { ctx, p, errors, hub } = await mChangeReqPage(browser, st, vp);
      try {
        const door = await p.evaluate(() => { const b = document.getElementById("m-req-btn"); const r = b.getBoundingClientRect(); return { hidden: b.hidden, text: b.textContent, h: r.height, right: r.right, vw: innerWidth }; });
        if (door.hidden || !/^requests\s*2$/.test(door.text) || door.h < 40) fail(tag + "the door is wrong " + JSON.stringify(door));
        const hdr = await p.evaluate(() => { const h = document.querySelector("header"); return h ? h.scrollWidth - h.clientWidth : 0; });
        if (hdr > 1) fail(tag + "the header scrolls sideways by " + hdr);
        await p.tap("#m-req-btn");
        await p.waitForSelector("#m-requests:not([hidden]) .crm-list");
        const l = await p.evaluate(() => ({ title: document.querySelector(".crm-title").textContent, hero: document.querySelectorAll(".crm-hero").length, rows: [...document.querySelectorAll(".crm-li")].map(b => b.dataset.id).join(),
          groups: [...document.querySelectorAll(".crm-tg span")].map(x => x.textContent).join("|"), needs: document.querySelectorAll(".crm-needs").length, seg: [...document.querySelectorAll(".crm-seg button")].map(b => b.textContent + ":" + b.getAttribute("aria-pressed")).join(),
          hit: Math.min(...[...document.querySelectorAll(".crm-li, .crm-btn, .crm-seg button")].map(b => b.getBoundingClientRect().height)), page: document.documentElement.scrollWidth - innerWidth }));
        if (l.title !== "Change requests" || l.hero !== 2 || l.rows !== "cr_9,cr_8,cr_7" || l.groups !== "into main|into release/1.x" || l.needs !== 2 || l.seg !== "Open 3:true,Closed 3:false") fail(tag + "the list is wrong " + JSON.stringify(l));
        if (l.hit < 40 || l.page > 1) fail(tag + "tap targets or width: " + JSON.stringify([l.hit, l.page]));
        const h0 = await p.evaluate(() => history.length);
        await p.tap('.crm-li[data-id="cr_9"]');
        await p.waitForFunction(() => document.querySelector(".crm-title").textContent === "cr_9" && /hub head matches/.test(document.querySelector(".crm-badges").textContent));
        const pg = await p.evaluate(() => ({ ttl: document.querySelector(".crm-ttl").textContent, gate: document.querySelector(".crm-gate").textContent, panels: [...document.querySelectorAll(".crm-panel h3")].map(x => x.textContent).join(),
          line: document.querySelector(".crm-line").textContent, hist: history.length, btns: [...document.querySelectorAll("#m-requests button")].map(b => b.textContent.trim()).filter(x => /merge/i.test(x)).join(), page: document.documentElement.scrollWidth - innerWidth }));
        if (pg.ttl !== "Fix the router link flap" || !/Needs the orchestrator or clint/.test(pg.gate) || !/Nothing on the board does it/.test(pg.gate) || pg.panels !== "Why,On the hub,Change record,History" || pg.line !== "pushed at abcdef0, hub head matches") fail(tag + "the page is wrong " + JSON.stringify(pg));
        if (pg.hist !== h0 + 1) fail(tag + "opening a request did not push one history entry " + JSON.stringify([h0, pg.hist]));
        if (pg.btns !== "Record that it was merged") fail(tag + "merge wording on a button: " + pg.btns);
        // the sha check, the server's 409, a record
        const dis = () => p.evaluate(() => ({ off: [...document.querySelectorAll(".crm-btn.go")].pop().disabled, bad: document.getElementById("crm-shahint").classList.contains("bad") }));
        if (!(await dis()).off) fail(tag + "record merged is enabled with no sha");
        for (const [v, ok] of CR_SHAS) {
          await p.fill("#crm-sha", v);
          const d = await dis();
          if (d.off === ok || (v && !ok && !d.bad)) fail(tag + "sha " + v + " should be " + (ok ? "accepted" : "refused") + " with a hint " + JSON.stringify(d));
        }
        await p.fill("#crm-sha", CR_ZERO);
        await p.tap(".crm-gate .crm-btn.go");
        await p.waitForSelector(".crm-err");
        if ((await text0(p, ".crm-err")) !== CR_ZERO + " is not reachable from main") fail(tag + "the 409 text is not shown: " + await text0(p, ".crm-err"));
        await p.fill("#crm-sha", CR_FULL);
        await p.tap(".crm-gate .crm-btn.go");
        await p.waitForFunction(() => /Recorded as merged at e40a3c2/.test((document.querySelector(".crm-ended") || {}).textContent || ""));
        if (hub.calls.filter(c => c.body.do === "merged").map(c => c.body.sha).join() !== CR_ZERO + "," + CR_FULL) fail(tag + "posted " + JSON.stringify(hub.calls.map(c => c.body)));
        // back is history: the page goes to the list, the list closes the sheet
        await p.evaluate(() => history.back());
        await p.waitForSelector(".crm-list");
        if (await p.evaluate(() => document.getElementById("m-requests").hidden)) fail(tag + "back from a page closed the sheet");
        const n3 = await p.evaluate(() => [...document.querySelectorAll(".crm-li")].map(b => b.dataset.id).join());
        if (n3 !== "cr_8,cr_7") fail(tag + "the merged request is still open " + n3);
        await p.evaluate(() => history.back());
        await p.waitForFunction(() => document.getElementById("m-requests").hidden);
        // closed records and the unseen branch
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        await p.tap(".crm-seg button:nth-child(2)");
        await p.tap('.crm-li[data-id="cr_5"]');
        await p.waitForFunction(() => /not pushed/.test((document.querySelector(".crm-badges") || {}).textContent || ""));
        const w = await p.evaluate(() => ({ ended: document.querySelector(".crm-ended").textContent, line: document.querySelector(".crm-line").textContent, how: document.querySelector(".crm-panel .crm-note, .crm-panel .crm-quiet") && [...document.querySelectorAll(".crm-note")].map(x => x.textContent).join("|") }));
        if (!/Withdrawn/.test(w.ended) || !/never seen test\/flaky-terminator-race/.test(w.line) || !/git push hub test\/flaky-terminator-race/.test(w.how)) fail(tag + "an unseen branch reads wrong " + JSON.stringify(w));
        if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      } finally { await ctx.close(); }

      // withdraw and close with a note
      ({ ctx, p, errors, hub } = await mChangeReqPage(browser, st, vp));
      try {
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        await p.tap('.crm-li[data-id="cr_9"]'); await p.waitForSelector(".crm-gate");
        await p.tap(".crm-acts .crm-btn:nth-child(1)");
        await p.waitForFunction(() => /Withdrawn/.test((document.querySelector(".crm-ended") || {}).textContent || ""));
        await p.evaluate(() => history.back());
        await p.tap('.crm-li[data-id="cr_8"]'); await p.waitForSelector(".crm-gate");
        await p.tap(".crm-acts .crm-btn:nth-child(2)");
        await p.fill("#crm-note", "landed on the other branch");
        await p.tap('.crm-row .crm-btn:text-is("Close request")');
        await p.waitForFunction(() => /Closed/.test((document.querySelector(".crm-ended") || {}).textContent || ""));
        if (hub.calls.map(c => JSON.stringify(c.body)).join() !== '{"do":"withdraw"},{"do":"close","note":"landed on the other branch"}') fail(tag + "posted " + hub.calls.map(c => JSON.stringify(c.body)));
        if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      } finally { await ctx.close(); }

      // a board that cannot write
      ({ ctx, p, errors } = await mChangeReqPage(browser, st, vp, { mode: "readonly" }));
      try {
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        await p.tap('.crm-li[data-id="cr_9"]'); await p.waitForSelector(".crm-gate");
        await p.tap(".crm-acts .crm-btn:nth-child(1)");
        await p.waitForSelector(".crm-ro");
        const ro = await p.evaluate(() => ({ line: document.querySelector(".crm-ro").textContent, inputs: document.querySelectorAll("#m-requests input, #m-requests .crm-acts").length }));
        if (!/public share without a login/.test(ro.line) || ro.inputs) fail(tag + "a read-only board still offers writes " + JSON.stringify(ro));
        await p.evaluate(() => history.back());
        await p.waitForSelector(".crm-list");
        if (await p.$(".crm-bar .crm-btn")) fail(tag + "a read-only board offers to open a request");
      } finally { await ctx.close(); }

      // the mock says it is on, and only the URL turns it on
      ({ ctx, p } = await mChangeReqPage(browser, st, vp, { query: "?crmock=1" }));
      try {
        const bn = await p.evaluate(() => { const b = document.getElementById("cr-mockbar"); const r = b && b.getBoundingClientRect(); return b ? { t: b.textContent, pos: getComputedStyle(b).position, vis: r.width > 100 && r.height > 10 } : null; });
        if (!bn || !/Mock data: nothing here reaches the hub/.test(bn.t) || bn.pos !== "fixed" || !bn.vis) fail(tag + "the mock is on without a banner " + JSON.stringify(bn));
      } finally { await ctx.close(); }
      ({ ctx, p } = await mChangeReqPage(browser, st, vp, {}));
      try {
        if (await p.evaluate(() => !!document.getElementById("cr-mockbar"))) fail(tag + "a banner with the mock off");
        await p.evaluate(() => localStorage.setItem("atrium.crMock", "1"));
        await p.reload({ waitUntil: "domcontentloaded" }); await p.waitForTimeout(400);
        if (await p.evaluate(() => crCore.mockOn() || !!document.getElementById("cr-mockbar"))) fail(tag + "localStorage still turns the mock on");
      } finally { await ctx.close(); }

      // a 403 that is the action's own is shown as its error and the page stays writable
      ({ ctx, p } = await mChangeReqPage(browser, st, vp, { mode: "forbid" }));
      try {
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        await p.tap('.crm-li[data-id="cr_9"]'); await p.waitForSelector(".crm-gate");
        await p.tap(".crm-acts .crm-btn:nth-child(1)");
        await p.waitForSelector(".crm-err");
        const fb = await p.evaluate(() => ({ err: document.querySelector(".crm-err").textContent, ro: !!document.querySelector(".crm-ro"), acts: !!document.querySelector(".crm-acts") }));
        if (fb.err !== "only the owner may withdraw this request" || fb.ro || !fb.acts) fail(tag + "an action's own 403 hid the actions " + JSON.stringify(fb));
      } finally { await ctx.close(); }

      // empty, and the doors that stay shut
      ({ ctx, p } = await mChangeReqPage(browser, st, vp, { mode: "empty" }));
      try {
        await p.tap("#m-req-btn");
        await p.waitForSelector(".crm-empty");
        if (!/Nothing is waiting to be merged/.test(await text0(p, ".crm-empty"))) fail(tag + "the empty hub reads wrong");
      } finally { await ctx.close(); }
      for (const mode of ["old", "offline"]) {
        ({ ctx, p } = await mChangeReqPage(browser, st, vp, { mode }));
        try { if (!(await p.evaluate(() => document.getElementById("m-req-btn").hidden))) fail(tag + mode + " hub: the door is open"); } finally { await ctx.close(); }
      }
      // a hub that goes away after the door opened says so, with a way to try again
      ({ ctx, p } = await mChangeReqPage(browser, st, vp));
      try {
        await p.evaluate(() => { window.mRequests.state.loaded = false; });
        await p.unroute(/\/_hub\/(change-requests|git\/pushed)/);
        await p.route(/\/_hub\/change-requests/, r => r.abort("failed"));
        await p.tap("#m-req-btn");
        await p.waitForSelector(".crm-warn");
        if (!/hub is not answering/.test(await text0(p, ".crm-warn")) || !(await p.$(".crm-list .crm-btn"))) fail(tag + "a hub that went away reads wrong: " + await text0(p, ".crm-list"));
      } finally { await ctx.close(); }

      // opening a request, the 404, the 409
      ({ ctx, p, errors, hub } = await mChangeReqPage(browser, st, vp));
      try {
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        await p.tap(".crm-bar .crm-btn");
        await p.waitForSelector(".crm-form");
        await p.fill("#crm-f-branch", "nope/missing"); await p.fill("#crm-f-title", "A request");
        await p.tap(".crm-form .crm-btn.go");
        await p.waitForSelector(".crm-form .crm-err");
        if (!/hub has no branch called nope\/missing.*git push hub nope\/missing/.test(await text0(p, ".crm-form .crm-err"))) fail(tag + "the 404 is not explained");
        await p.fill("#crm-f-branch", "feat/metrics-exemplars"); await p.fill("#crm-f-why", "line one\n<b>not bold</b>");
        await p.tap(".crm-form .crm-btn.go");
        await p.waitForFunction(() => /A request/.test((document.querySelector(".crm-ttl") || {}).textContent || ""));
        const c = hub.calls.filter(x => x.path === "/_hub/change-requests").pop().body;
        if (JSON.stringify(c) !== '{"repo":"github/openziti/ziti","source":{"branch":"feat/metrics-exemplars"},"target":{"branch":"main"},"title":"A request","why":"line one\\n<b>not bold</b>"}') fail(tag + "the create body is " + JSON.stringify(c));
        if (await p.$(".crm-why b")) fail(tag + "a why became markup");
        await p.evaluate(() => history.back());
        await p.waitForSelector(".crm-list");
        await p.tap(".crm-bar .crm-btn");
        await p.waitForSelector(".crm-form");
        await p.fill("#crm-f-branch", "fix/router-link-flap"); await p.fill("#crm-f-title", "Again");
        await p.tap(".crm-form .crm-btn.go");
        await p.waitForFunction(() => /already exists/.test((document.querySelector(".crm-err") || {}).textContent || ""));
        if (!/Fix the router link flap/.test(await text0(p, ".crm-ttl"))) fail(tag + "a 409 does not open the request that exists");
        if (errors.length) fail(tag + "page errors: " + errors.join(" | "));
      } finally { await ctx.close(); }

      // title and why are text
      ({ ctx, p } = await mChangeReqPage(browser, st, vp, { mutate: h => { h.rows[0].title = '<img src=x onerror=window.__x=1>T'; h.rows[0].why = '<script>window.__x=2<\/script>w'; } }));
      try {
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        await p.tap('.crm-li[data-id="cr_9"]'); await p.waitForSelector(".crm-why");
        const x = await p.evaluate(() => ({ x: window.__x, n: document.querySelectorAll("#m-requests img, #m-requests script, #m-requests b:not(.crm-b)").length - document.querySelectorAll("#m-requests .crm-steps b, #m-requests .crm-seg b, #m-requests .crm-ended b, #m-requests .crm-gate > b, #m-requests .crm-tl b").length, t: document.getElementById("m-requests").textContent }));
        if (x.x || x.n > 0 || !x.t.includes("<img src=x onerror=window.__x=1>T")) fail(tag + "a title became markup " + JSON.stringify({ x: x.x, n: x.n }));
      } finally { await ctx.close(); }
    }

    // contrast on every skin, phone
    {
      const skins = [""].concat(((await (await fetch(st.url + "/css/themes.css")).text()).match(/:root\[data-skin="([a-z]+)"\]/g) || []).map(s => /"([a-z]+)"/.exec(s)[1]));
      const { ctx, p } = await mChangeReqPage(browser, st, M_VIEWS[0]);
      let bad;
      try {
        await p.tap("#m-req-btn"); await p.waitForSelector(".crm-list");
        const list = [".crm-title", ".crm-k", ".crm-hero h3", ".crm-hero .crm-quiet", ".crm-hero .crm-btn", ".crm-seg button[aria-pressed=true]", ".crm-tg span", ".crm-li .crm-lt", ".crm-li .crm-lm", ".crm-li .crm-needs", ".crm-bar .crm-btn"];
        bad = await crInkCheck(p, skins, list, 390);
        await p.tap('.crm-li[data-id="cr_9"]'); await p.waitForFunction(() => /hub head matches/.test(document.querySelector(".crm-badges").textContent));
        const page = [".crm-crumb", ".crm-ttl", ".crm-badges .crm-pill", ".crm-end small", ".crm-gate > b", ".crm-gate > span", ".crm-steps li", ".crm-field label", ".crm-hint", ".crm-gate .crm-btn.go", ".crm-panel h3", ".crm-why", ".crm-line", ".crm-kv dt", ".crm-kv dd", ".crm-tl li span", ".crm-lane .crm-br"];
        bad = bad.concat(await crInkCheck(p, skins, page, 390, () => p.fill("#crm-sha", CR_FULL)));
      } finally { await ctx.close(); }
      if (process.env.CR_CONTRAST) console.log(bad.join("\n"));
      if (bad.length) fail(tag0 + ": text under 4.5:1 on " + bad.length + " pairs: " + bad.slice(0, 14).join("; "));
    }

    // the changes sheet's Pushed line
    for (const [mode, want] of [["matches", /^Pushedpushed at abcdef0, hub head matches$/], ["behind", /hub is behind/], ["not-pushed", /never seen feat\/x.*git push hub feat\/x/], ["offline", /the hub did not say: the hub is not answering/]]) {
      const vp = M_VIEWS[0];
      st.changesFor = (card, q) => card !== "cr-1" ? { status: 404, body: { error: "not a worktree" } } : { status: 200, body: { against: "head", base: "aaaaaaa1", head: "1a2b3c4d5e6f", dirty: false, total: 1, repo: "github/o/r", branch: "feat/x", files: [{ path: "a.js", status: "modified", added: 1, removed: 1, hunks: "@@ -1 +1 @@\n-a\n+b\n" }] } };
      const asked = [];
      const { ctx, p } = await mChangeReqPage(browser, st, vp, { pushed: r => { asked.push(new URL(r.request().url()).search); if (mode === "offline") return r.abort("failed");
        return r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ state: mode, hub_sha: "abcdef0123456789", room: "sg4", card: "c-1", at: new Date().toISOString(), released: false }) }); } });
      try {
        await p.tap("#m-seg-all"); await p.waitForSelector("#m-list .row");
        await p.tap('#m-list .row[data-id="cr-1"]'); await p.waitForSelector("#m-replies .md");
        await p.tap("#m-card-changes");
        await p.waitForSelector(".cg-pushed .cg-pk");
        await p.waitForFunction(() => !/reading/.test(document.querySelector(".cg-pushed").textContent), null, { timeout: slow(5000) });
        const t = await text0(p, ".cg-pushed");
        if (!want.test(t)) fail(tag0 + " pushed " + mode + ": reads " + t);
        if (asked.length !== 1 || asked[0] !== "?repo=github%2Fo%2Fr&branch=feat%2Fx&head=1a2b3c4d5e6f") fail(tag0 + " pushed " + mode + ": asked " + JSON.stringify(asked));
      } finally { await ctx.close(); }
    }
    // a card whose changes name no branch gets no line and no call
    {
      st.changesFor = (card, q) => ({ status: 200, body: { against: "head", base: "a", head: "1a2b3c4d5e6f", dirty: false, total: 0, files: [] } });
      const asked = [];
      const { ctx, p } = await mChangeReqPage(browser, st, M_VIEWS[0], { pushed: r => { asked.push(1); return r.abort(); } });
      try {
        await p.tap("#m-seg-all"); await p.waitForSelector("#m-list .row");
        await p.tap('#m-list .row[data-id="cr-1"]'); await p.waitForSelector("#m-replies .md");
        await p.tap("#m-card-changes"); await p.waitForSelector(".cg-sub");
        await p.waitForTimeout(200);
        if (await p.$(".cg-pushed") || asked.length) fail(tag0 + ": a card with no branch got a Pushed line or a call");
      } finally { await ctx.close(); }
    }
    await mCrShots(browser, st);
  } finally { await st.close(); }
  if (!bad) console.log("mChangeReq ok");
}
// Phone shots of the real /m sheet for review: CR_SHOTS=/dir. 390 wide, paper and dark, each screen it has.
async function mCrShots(browser, st) {
  const dir = process.env.CR_SHOTS;
  if (!dir) return;
  require("fs").mkdirSync(dir, { recursive: true });
  st.changesFor = () => ({ status: 200, body: { against: "head", base: "aaaaaaa1", head: "1a2b3c4d5e6f", dirty: false, total: 2, repo: "github/o/r", branch: "feat/x",
    files: [{ path: "internal/hub/receive.go", status: "modified", added: 40, removed: 6, hunks: "@@ -1 +1 @@\n-a\n+b\n" }, { path: "docs/notes.md", status: "added", added: 12, removed: 0, hunks: "@@ -0,0 +1 @@\n+x\n" }] } });
  for (const skin of ["paper", "dark"]) for (const view of ["list", "page", "closed", "readonly", "empty", "form", "changes"]) {
    const { ctx, p } = await mChangeReqPage(browser, st, { width: 390, height: 844 }, { mode: view === "empty" ? "empty" : view === "readonly" ? "readonly" : "ok", pushed: view === "changes" ? (r => r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ state: "behind", hub_sha: "abcdef0123456789", room: "sg4", card: "c-101", at: new Date(Date.now() - 3600e3).toISOString() }) })) : undefined });
    try {
      await p.evaluate(s => { if (s === "paper") document.documentElement.setAttribute("data-skin", "paper"); else document.documentElement.removeAttribute("data-skin"); }, skin);
      if (view === "changes") {
        await p.tap("#m-seg-all"); await p.waitForSelector("#m-list .row"); await p.tap('#m-list .row[data-id="cr-1"]'); await p.waitForSelector("#m-replies .md");
        await p.tap("#m-card-changes"); await p.waitForFunction(() => document.querySelector(".cg-pushed") && !/reading/.test(document.querySelector(".cg-pushed").textContent));
      } else {
        await p.tap("#m-req-btn"); await p.waitForSelector("#m-requests .crm-view");
        if (view === "page" || view === "readonly") { await p.tap('.crm-li[data-id="cr_9"]'); await p.waitForFunction(() => /hub head matches/.test((document.querySelector(".crm-badges") || {}).textContent || "")); }
        if (view === "readonly") { await p.tap(".crm-acts .crm-btn:nth-child(1)"); await p.waitForSelector(".crm-ro"); }
        if (view === "closed") { await p.tap(".crm-seg button:nth-child(2)"); await p.tap('.crm-li[data-id="cr_6"]'); await p.waitForFunction(() => /Bump Go/.test((document.querySelector(".crm-ttl") || {}).textContent || "") && document.querySelectorAll(".crm-tl li").length >= 3); }
        if (view === "form") { await p.tap(".crm-bar .crm-btn"); await p.waitForSelector(".crm-form"); }
      }
      await p.waitForTimeout(250);
      const h = await p.evaluate(() => { const sc = document.querySelector("#m-requests:not([hidden]) .crm-scroll") || document.querySelector(".v-scroll"); return sc ? sc.scrollHeight + 90 : 844; });
      await p.setViewportSize({ width: 390, height: Math.min(5000, Math.max(844, h)) });
      await p.waitForTimeout(200);
      await p.screenshot({ path: require("path").join(dir, "m-requests-" + view + "-390-" + skin + ".png") });
    } finally { await ctx.close(); }
  }
}

// The sha forms: the hub's ValidSHA, a full 40 (sha-1) or 64 (sha-256) hex, either case; nothing shorter or longer.
const CR_FULL = "e40a3c2d00112233445566778899aabbccddeeff", CR_ZERO = "0".repeat(40), CR_64 = "ab".repeat(32);
const CR_SHAS = [["xyz", false], ["e40a3c2", false], [CR_FULL.slice(1), false], [CR_FULL + "0", false], [CR_FULL.replace("e", "g"), false], [CR_FULL.toUpperCase(), true], [CR_FULL, true], [CR_64, true], [CR_64.slice(1), false]];
const text0 = (p, sel) => p.evaluate(s => (document.querySelector(s) || {}).textContent || "", sel);

